export default "com/video.mp4\\\"],\\n            base64=\\\"BBBB\\\",\\n            mime_type=\\\"video/mp4\\\",\\n            duration=300,\\n        )\\n        assert video.type == \\\"video\\\"\\n        assert video.urls == [\\\"http://example.com/video.mp4\\\"]\\n        assert video.base64 == \\\"BBBB\\\"\\n        assert video.mime_type == \\\"video/mp4\\\"\\n        assert video.duration == 300\\n\\n    def test_empty_construction_raises(self):\\n        \\\"\\\"\\\"VideoContent with no urls or base64 should raise.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError):\\n            VideoContent()\\n\\n    def test_base64_without_mime_type_raises(self):\\n        \\\"\\\"\\\"VideoContent with base64 but no mime_type should raise.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError):\\n            VideoContent(base64=\\\"BBBB\\\")\\n\\n    def test_serialization_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump -> model_validate round trip.\\\"\\\"\\\"\\n        video = VideoContent(urls=[\\\"http://example.com/v.mp4\\\"], duration=120)\\n        dumped = video.model_dump()\\n        restored = VideoContent.model_validate(dumped)\\n        assert restored.type == \\\"video\\\"\\n        assert restored.urls == video.urls\\n        assert restored.duration == video.duration\\n\\n    def test_json_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump_json -> model_validate_json round trip.\\\"\\\"\\\"\\n        video = VideoContent(urls=[\\\"http://example.com/v.webm\\\"], mime_type=\\\"video/webm\\\")\\n        json_str = video.model_dump_json()\\n        restored = VideoContent.model_validate_json(json_str)\\n        assert restored == video\\n\\n\\nclass TestFileContent:\\n    def test_construction(self):\\n        \\\"\\\"\\\"Test FileContent creation with all fields.\\\"\\\"\\\"\\n        fc = FileContent(\\n            urls=[\\\"http://example.com/report.pdf\\\"],\\n            mime_type=\\\"application/pdf\\\",\\n            filename=\\\"report.pdf\\\",\\n        )\\n        assert fc.type == \\\"file\\\"\\n        assert fc.urls == [\\\"http://example.com/report.pdf\\\"]\\n        assert fc.mime_type == \\\"application/pdf\\\"\\n        assert fc.filename == \\\"report.pdf\\\"\\n\\n    def test_empty_construction_raises(self):\\n        \\\"\\\"\\\"FileContent with no urls should raise.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError):\\n            FileContent()\\n\\n    def test_serialization_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump -> model_validate round trip.\\\"\\\"\\\"\\n        fc = FileContent(urls=[\\\"http://example.com/doc.txt\\\"], filename=\\\"doc.txt\\\")\\n        dumped = fc.model_dump()\\n        restored = FileContent.model_validate(dumped)\\n        assert restored.type == \\\"file\\\"\\n        assert restored.urls == fc.urls\\n        assert restored.filename == fc.filename\\n\\n    def test_json_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump_json -> model_validate_json round trip.\\\"\\\"\\\"\\n        fc = FileContent(urls=[\\\"http://example.com/f.csv\\\"], mime_type=\\\"text/csv\\\", filename=\\\"f.csv\\\")\\n        json_str = fc.model_dump_json()\\n        restored = FileContent.model_validate_json(json_str)\\n        assert restored == fc\\n\\n\\nclass TestReasoningContent:\\n    def test_construction(self):\\n        \\\"\\\"\\\"Test ReasoningContent creation with text.\\\"\\\"\\\"\\n        r = ReasoningContent(text=\\\"Let me think about this step by step.\\\")\\n        assert r.type == \\\"reasoning\\\"\\n        assert r.text == \\\"Let me think about this step by step.\\\"\\n\\n    def test_construction_defaults(self):\\n        \\\"\\\"\\\"Test ReasoningContent with default values.\\\"\\\"\\\"\\n        r = ReasoningContent()\\n        assert r.type == \\\"reasoning\\\"\\n        assert r.text == \\\"\\\"\\n\\n    def test_serialization_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump -> model_validate round trip.\\\"\\\"\\\"\\n        r = ReasoningContent(text=\\\"Step 1: consider the problem.\\\")\\n        dumped = r.model_dump()\\n        restored = ReasoningContent.model_validate(dumped)\\n        assert restored.type == \\\"reasoning\\\"\\n        assert restored.text == r.text\\n\\n    def test_json_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump_json -> model_validate_json round trip.\\\"\\\"\\\"\\n        r = ReasoningContent(text=\\\"Analyzing inputs...\\\")\\n        json_str = r.model_dump_json()\\n        restored = ReasoningContent.model_validate_json(json_str)\\n        assert restored == r\\n\\n\\nclass TestUsageContent:\\n    def test_construction(self):\\n        \\\"\\\"\\\"Test UsageContent creation with all fields.\\\"\\\"\\\"\\n        u = UsageContent(input_tokens=100, output_tokens=250, model=\\\"gpt-4\\\")\\n        assert u.type == \\\"usage\\\"\\n        assert u.input_tokens == 100\\n        assert u.output_tokens == 250\\n        assert u.model == \\\"gpt-4\\\"\\n\\n    def test_construction_defaults(self):\\n        \\\"\\\"\\\"Test UsageContent with default values.\\\"\\\"\\\"\\n        u = UsageContent()\\n        assert u.type == \\\"usage\\\"\\n        assert u.input_tokens is None\\n        assert u.output_tokens is None\\n        assert u.model is None\\n\\n    def test_serialization_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump -> model_validate round trip.\\\"\\\"\\\"\\n        u = UsageContent(input_tokens=50, output_tokens=100, model=\\\"claude-3\\\")\\n        dumped = u.model_dump()\\n        restored = UsageContent.model_validate(dumped)\\n        assert restored.type == \\\"usage\\\"\\n        assert restored.input_tokens == u.input_tokens\\n        assert restored.output_tokens == u.output_tokens\\n        assert restored.model == u.model\\n\\n    def test_json_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump_json -> model_validate_json round trip.\\\"\\\"\\\"\\n        u = UsageContent(input_tokens=10, output_tokens=20)\\n        json_str = u.model_dump_json()\\n        restored = UsageContent.model_validate_json(json_str)\\n        assert restored == u\\n\\n    def test_negative_tokens_raises(self):\\n        \\\"\\\"\\\"Negative token counts should raise.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError):\\n            UsageContent(input_tokens=-5)\\n        with pytest.raises(ValidationError):\\n            UsageContent(output_tokens=-1)\\n\\n\\nclass TestCitationContent:\\n    def test_construction(self):\\n        \\\"\\\"\\\"Test CitationContent creation with all fields.\\\"\\\"\\\"\\n        c = CitationContent(\\n            url=\\\"http://example.com/article\\\",\\n            title=\\\"Test Article\\\",\\n            cited_text=\\\"This is the cited passage.\\\",\\n            start_index=10,\\n            end_index=45,\\n        )\\n        assert c.type == \\\"citation\\\"\\n        assert c.url == \\\"http://example.com/article\\\"\\n        assert c.title == \\\"Test Article\\\"\\n        assert c.cited_text == \\\"This is the cited passage.\\\"\\n        assert c.start_index == 10\\n        assert c.end_index == 45\\n\\n    def test_construction_defaults(self):\\n        \\\"\\\"\\\"Test CitationContent with default values.\\\"\\\"\\\"\\n        c = CitationContent()\\n        assert c.type == \\\"citation\\\"\\n        assert c.url is None\\n        assert c.title is None\\n        assert c.cited_text is None\\n        assert c.start_index is None\\n        assert c.end_index is None\\n\\n    def test_serialization_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump -> model_validate round trip.\\\"\\\"\\\"\\n        c = CitationContent(url=\\\"http://example.com\\\", title=\\\"Example\\\", start_index=0, end_index=10)\\n        dumped = c.model_dump()\\n        restored = CitationContent.model_validate(dumped)\\n        assert restored.type == \\\"citation\\\"\\n        assert restored.url == c.url\\n        assert restored.title == c.title\\n        assert restored.start_index == c.start_index\\n        assert restored.end_index == c.end_index\\n\\n    def test_json_round_trip(self):\\n        \\\"\\\"\\\"Test model_dump_json -> model_validate_json round trip.\\\"\\\"\\\"\\n        c = CitationContent(url=\\\"http://example.com\\\", cited_text=\\\"Some text\\\")\\n        json_str = c.model_dump_json()\\n        restored = CitationContent.model_validate_json(json_str)\\n        assert restored == c\\n\\n    def test_inverted_indices_raises(self):\\n        \\\"\\\"\\\"start_index > end_index should raise.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError):\\n            CitationContent(start_index=50, end_index=10)\\n\\n    def test_negative_index_raises(self):\\n        \\\"\\\"\\\"Negative indices should raise.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError):\\n            CitationContent(start_index=-1)\\n        with pytest.raises(ValidationError):\\n            CitationContent(end_index=-5)\\n\\n\\n# --- Existing type regression tests ---\\n\\n\\ndef test_content_type_discrimination():\\n    \\\"\\\"\\\"Test that different content types are properly discriminated.\\\"\\\"\\\"\\n    contents = [\\n        TextContent(text=\\\"Hello\\\"),\\n        CodeContent(code=\\\"print('hi')\\\", language=\\\"python\\\"),\\n        ErrorContent(reason=\\\"test error\\\"),\\n        JSONContent(data={\\\"test\\\": \\\"data\\\"}),\\n        MediaContent(urls=[\\\"http://example.com/image.jpg\\\"]),\\n        ToolContent(name=\\\"test_tool\\\"),\\n    ]\\n\\n    assert all(\\n        content.type == expected\\n        for content, expected in zip(contents, [\\\"text\\\", \\\"code\\\", \\\"error\\\", \\\"json\\\", \\\"media\\\", \\\"tool_use\\\"], strict=False)\\n    )\\n\\n\\ndef test_existing_types_serialization_round_trip():\\n    \\\"\\\"\\\"Verify serialization round-trip for all existing content types (regression test).\\\"\\\"\\\"\\n    existing = [\\n        TextContent(text=\\\"Hello\\\"),\\n        CodeContent(code=\\\"x = 1\\\", language=\\\"python\\\", title=\\\"snippet\\\"),\\n        ErrorContent(component=\\\"comp\\\", reason=\\\"fail\\\"),\\n        JSONContent(data={\\\"a\\\": 1}),\\n        MediaContent(urls=[\\\"http://example.com/img.png\\\"], caption=\\\"cap\\\"),\\n        ToolContent(name=\\\"tool\\\", tool_input={\\\"k\\\": \\\"v\\\"}, output=\\\"out\\\"),\\n    ]\\n    for content in existing:\\n        dumped = content.model_dump()\\n        restored = type(content).model_validate(dumped)\\n        assert restored == content\\n\\n\\ndef test_existing_types_json_round_trip():\\n    \\\"\\\"\\\"Verify JSON round-trip for all existing content types (regression test).\\\"\\\"\\\"\\n    existing = [\\n        TextContent(text=\\\"Hello\\\"),\\n        CodeContent(code=\\\"x = 1\\\", language=\\\"python\\\"),\\n        ErrorContent(reason=\\\"fail\\\"),\\n        JSONContent(data={\\\"a\\\": [1, 2]}),\\n        MediaContent(urls=[\\\"http://example.com/img.png\\\"]),\\n        ToolContent(name=\\\"tool\\\", tool_input={\\\"k\\\": \\\"v\\\"}),\\n    ]\\n    for content in existing:\\n        json_str = content.model_dump_json()\\n        restored = type(content).model_validate_json(json_str)\\n        assert restored == content\\n\\n\\n# --- Discriminator dispatch tests via ContentBlock ---\\n\\n\\ndef test_discriminator_dispatch_existing_types():\\n    \\\"\\\"\\\"Test ContentBlock correctly dispatches existing content types from dicts.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[\\n            {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"hello\\\"},\\n            {\\\"type\\\": \\\"code\\\", \\\"code\\\": \\\"x=1\\\", \\\"language\\\": \\\"python\\\"},\\n            {\\\"type\\\": \\\"error\\\", \\\"reason\\\": \\\"oops\\\"},\\n            {\\\"type\\\": \\\"json\\\", \\\"data\\\": {\\\"k\\\": \\\"v\\\"}},\\n            {\\\"type\\\": \\\"media\\\", \\\"urls\\\": [\\\"http://example.com/a.jpg\\\"]},\\n            {\\\"type\\\": \\\"tool_use\\\", \\\"name\\\": \\\"my_tool\\\", \\\"input\\\": {}},\\n        ],\\n    )\\n    assert isinstance(block.contents[0], TextContent)\\n    assert isinstance(block.contents[1], CodeContent)\\n    assert isinstance(block.contents[2], ErrorContent)\\n    assert isinstance(block.contents[3], JSONContent)\\n    assert isinstance(block.contents[4], MediaContent)\\n    assert isinstance(block.contents[5], ToolContent)\\n\\n\\ndef test_discriminator_dispatch_image():\\n    \\\"\\\"\\\"Test ContentBlock dispatches ImageContent from dict.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[{\\\"type\\\": \\\"image\\\", \\\"urls\\\": [\\\"http://example.com/pic.png\\\"], \\\"caption\\\": \\\"a pic\\\"}],\\n    )\\n    assert isinstance(block.contents[0], ImageContent)\\n    assert block.contents[0].urls == [\\\"http://example.com/pic.png\\\"]\\n    assert block.contents[0].caption == \\\"a pic\\\"\\n\\n\\ndef test_discriminator_dispatch_audio():\\n    \\\"\\\"\\\"Test ContentBlock dispatches AudioContent from dict.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[{\\\"type\\\": \\\"audio\\\", \\\"urls\\\": [\\\"http://example.com/a.mp3\\\"], \\\"duration\\\": 60, \\\"transcript\\\": \\\"Hi\\\"}],\\n    )\\n    assert isinstance(block.contents[0], AudioContent)\\n    assert block.contents[0].duration == 60\\n    assert block.contents[0].transcript == \\\"Hi\\\"\\n\\n\\ndef test_discriminator_dispatch_video():\\n    \\\"\\\"\\\"Test ContentBlock dispatches VideoContent from dict.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[{\\\"type\\\": \\\"video\\\", \\\"urls\\\": [\\\"http://example.com/v.mp4\\\"], \\\"duration\\\": 120}],\\n    )\\n    assert isinstance(block.contents[0], VideoContent)\\n    assert block.contents[0].duration == 120\\n\\n\\ndef test_discriminator_dispatch_file():\\n    \\\"\\\"\\\"Test ContentBlock dispatches FileContent from dict.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[{\\\"type\\\": \\\"file\\\", \\\"urls\\\": [\\\"http://example.com/f.pdf\\\"], \\\"filename\\\": \\\"f.pdf\\\"}],\\n    )\\n    assert isinstance(block.contents[0], FileContent)\\n    assert block.contents[0].filename == \\\"f.pdf\\\"\\n\\n\\ndef test_discriminator_dispatch_reasoning():\\n    \\\"\\\"\\\"Test ContentBlock dispatches ReasoningContent from dict.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[{\\\"type\\\": \\\"reasoning\\\", \\\"text\\\": \\\"thinking...\\\"}],\\n    )\\n    assert isinstance(block.contents[0], ReasoningContent)\\n    assert block.contents[0].text == \\\"thinking...\\\"\\n\\n\\ndef test_discriminator_dispatch_usage():\\n    \\\"\\\"\\\"Test ContentBlock dispatches UsageContent from dict.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[{\\\"type\\\": \\\"usage\\\", \\\"input_tokens\\\": 100, \\\"output_tokens\\\": 200, \\\"model\\\": \\\"gpt-4\\\"}],\\n    )\\n    assert isinstance(block.contents[0], UsageContent)\\n    assert block.contents[0].input_tokens == 100\\n    assert block.contents[0].output_tokens == 200\\n    assert block.contents[0].model == \\\"gpt-4\\\"\\n\\n\\ndef test_discriminator_dispatch_citation():\\n    \\\"\\\"\\\"Test ContentBlock dispatches CitationContent from dict.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"test\\\",\\n        contents=[\\n            {\\n                \\\"type\\\": \\\"citation\\\",\\n                \\\"url\\\": \\\"http://example.com\\\",\\n                \\\"title\\\": \\\"Example\\\",\\n                \\\"cited_text\\\": \\\"some text\\\",\\n                \\\"start_index\\\": 0,\\n                \\\"end_index\\\": 9,\\n            }\\n        ],\\n    )\\n    assert isinstance(block.contents[0], CitationContent)\\n    assert block.contents[0].url == \\\"http://example.com\\\"\\n    assert block.contents[0].cited_text == \\\"some text\\\"\\n    assert block.contents[0].start_index == 0\\n    assert block.contents[0].end_index == 9\\n\\n\\ndef test_discriminator_dispatch_all_new_types_together():\\n    \\\"\\\"\\\"Test ContentBlock with all new types in a single block.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"all new types\\\",\\n        contents=[\\n            {\\\"type\\\": \\\"image\\\", \\\"urls\\\": [\\\"http://example.com/img.png\\\"]},\\n            {\\\"type\\\": \\\"audio\\\", \\\"urls\\\": [\\\"http://example.com/a.mp3\\\"]},\\n            {\\\"type\\\": \\\"video\\\", \\\"urls\\\": [\\\"http://example.com/v.mp4\\\"]},\\n            {\\\"type\\\": \\\"file\\\", \\\"urls\\\": [\\\"http://example.com/f.txt\\\"]},\\n            {\\\"type\\\": \\\"reasoning\\\", \\\"text\\\": \\\"step 1\\\"},\\n            {\\\"type\\\": \\\"usage\\\", \\\"input_tokens\\\": 10},\\n            {\\\"type\\\": \\\"citation\\\", \\\"url\\\": \\\"http://example.com\\\"},\\n        ],\\n    )\\n    expected_types = [\\n        ImageContent,\\n        AudioContent,\\n        VideoContent,\\n        FileContent,\\n        ReasoningContent,\\n        UsageContent,\\n        CitationContent,\\n    ]\\n    for i, expected_cls in enumerate(expected_types):\\n        assert isinstance(block.contents[i], expected_cls), f\\\"contents[{i}] should be {expected_cls.__name__}\\\"\\n\\n\\ndef test_content_block_serialization_round_trip_with_new_types():\\n    \\\"\\\"\\\"Test ContentBlock model_dump -> model_validate with new content types.\\\"\\\"\\\"\\n    block = ContentBlock(\\n        title=\\\"round trip\\\",\\n        contents=[\\n            ImageContent(urls=[\\\"http://example.com/img.png\\\"], caption=\\\"pic\\\"),\\n            AudioContent(urls=[\\\"http://example.com/a.mp3\\\"], duration=30),\\n            VideoContent(urls=[\\\"http://example.com/v.mp4\\\"]),\\n            FileContent(urls=[\\\"http://example.com/f.pdf\\\"], filename=\\\"f.pdf\\\"),\\n            ReasoningContent(text=\\\"thinking\\\"),\\n            UsageContent(input_tokens=5, output_tokens=10),\\n            CitationContent(url=\\\"http://example.com\\\", title=\\\"Ref\\\"),\\n        ],\\n    )\\n    dumped = block.model_dump()\\n    restored = ContentBlock.model_validate(dumped)\\n    assert len(restored.contents) == 7\\n    assert isinstance(restored.contents[0], ImageContent)\\n    assert restored.contents[0].caption == \\\"pic\\\"\\n    assert isinstance(restored.contents[4], ReasoningContent)\\n    assert restored.contents[4].text == \\\"thinking\\\"\\n    assert isinstance(restored.contents[6], CitationContent)\\n    assert restored.contents[6].title == \\\"Ref\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# BaseContent.id (stable identity across re-emissions)\\n# ---------------------------------------------------------------------------\\n#\\n# Streaming emitters can re-fire the same logical content block as it grows\\n# (e.g. a ToolContent first without output, then with output). Consumers\\n# dedup these re-emissions; a stable id is the only safe key for that, since\\n# position changes on insert and a content hash collides on legitimate\\n# duplicates (two identical \\\"ok\\\" reasoning steps).\\n#\\n# The id is optional: producers that have a natural id (LangChain\\n# tool_call_id, external API id, a UUID the component stamped before the\\n# first emission) set it. Consumers that don't see one fall back to\\n# position-derived dedup. The id flows through the wire as just another\\n# field; nothing on the server mutates it.\\n\\n\\nclass TestBaseContentId:\\n    def test_default_id_is_none(self):\\n        \\\"\\\"\\\"An id is optional; producers opt in by setting it.\\\"\\\"\\\"\\n        assert BaseContent(type=\\\"anything\\\").id is None\\n\\n    def test_id_is_settable_on_construction(self):\\n        assert BaseContent(type=\\\"anything\\\", id=\\\"abc-123\\\").id == \\\"abc-123\\\"\\n\\n    def test_id_round_trips_through_model_dump(self):\\n        c = TextContent(text=\\\"hello\\\", id=\\\"msg-7\\\")\\n        restored = TextContent.model_validate(c.model_dump())\\n        assert restored.id == \\\"msg-7\\\"\\n\\n    def test_id_round_trips_through_json(self):\\n        c = ToolContent(name=\\\"search\\\", id=\\\"call_abc\\\")\\n        restored = ToolContent.model_validate_json(c.model_dump_json())\\n        assert restored.id == \\\"call_abc\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"content_cls\\\", \\\"kwargs\\\"),\\n        [\\n            (TextContent, {\\\"text\\\": \\\"hi\\\"}),\\n            (CodeContent, {\\\"code\\\": \\\"x=1\\\", \\\"language\\\": \\\"python\\\"}),\\n            (JSONContent, {\\\"data\\\": {\\\"k\\\": \\\"v\\\"}}),\\n            (MediaContent, {\\\"urls\\\": [\\\"http://example.com/a.png\\\"]}),\\n            (ToolContent, {\\\"name\\\": \\\"tool\\\"}),\\n            (ErrorContent, {\\\"reason\\\": \\\"boom\\\"}),\\n            (ImageContent, {\\\"urls\\\": [\\\"http://example.com/a.png\\\"]}),\\n            (AudioContent, {\\\"urls\\\": [\\\"http://example.com/a.mp3\\\"]}),\\n            (VideoContent, {\\\"urls\\\": [\\\"http://example.com/a.mp4\\\"]}),\\n            (FileContent, {\\\"urls\\\": [\\\"http://example.com/a.pdf\\\"]}),\\n            (ReasoningContent, {\\\"text\\\": \\\"thinking\\\"}),\\n            (UsageContent, {\\\"input_tokens\\\": 10}),\\n            (CitationContent, {\\\"url\\\": \\\"http://example.com\\\"}),\\n        ],\\n    )\\n    def test_id_inherited_by_every_subclass(self, content_cls, kwargs):\\n        \\\"\\\"\\\"Every concrete content type carries the optional id.\\\"\\\"\\\"\\n        c = content_cls(id=\\\"stable-id\\\", **kwargs)\\n        assert c.id == \\\"stable-id\\\"\\n        assert content_cls.model_validate(c.model_dump()).id == \\\"stable-id\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_data_setattr.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7a5d8733f6ef8b0143da8f8b67291aa92e43d98eb26154991e2554f145bec631\",\"content\":\"from lfx.schema.data import JSON\\nfrom pydantic import Field\\n\\n\\nclass TestDataSetAttrPropertyDescriptor:\\n    def test_property_setter_intercepted(self):\\n        \\\"\\\"\\\"A subclass @property with setter should be routed through by __setattr__.\\\"\\\"\\\"\\n\\n        class MyData(JSON):\\n            _backing: str = \\\"\\\"\\n            items: list[str] = Field(default_factory=list)\\n\\n            @property\\n            def computed(self):\\n                return self._backing.upper()\\n\\n            @computed.setter\\n            def computed(self, value):\\n                object.__setattr__(self, \\\"_backing\\\", str(value))\\n\\n        d = MyData()\\n        d.computed = \\\"hello\\\"\\n        assert d.computed == \\\"HELLO\\\"\\n        # Should NOT end up in data dict since property handled it\\n        assert \\\"computed\\\" not in d.data\\n\\n    def test_regular_field_still_works(self):\\n        class MyData(JSON):\\n            name: str = \\\"\\\"\\n\\n        d = MyData()\\n        d.name = \\\"test\\\"\\n        assert d.name == \\\"test\\\"\\n        assert d.data[\\\"name\\\"] == \\\"test\\\"\\n\\n    def test_dynamic_attribute_still_works(self):\\n        d = JSON()\\n        d.some_key = \\\"value\\\"\\n        assert d.data[\\\"some_key\\\"] == \\\"value\\\"\\n\\n    def test_private_attribute_still_works(self):\\n        d = JSON()\\n        d._private = \\\"secret\\\"\\n        assert \\\"_private\\\" not in d.data\\n\\n    def test_property_without_setter_not_intercepted(self):\\n        \\\"\\\"\\\"Read-only properties should not intercept writes.\\\"\\\"\\\"\\n\\n        class MyData(JSON):\\n            @property\\n            def readonly(self):\\n                return \\\"fixed\\\"\\n\\n        d = MyData()\\n        d.readonly = \\\"attempt\\\"\\n        # Should go to data dict since property has no setter\\n        assert d.data[\\\"readonly\\\"] == \\\"attempt\\\"\\n\\n    def test_non_property_descriptor_not_intercepted(self):\\n        \\\"\\\"\\\"Non-property class attributes should not trigger the property path.\\\"\\\"\\\"\\n        from typing import ClassVar\\n\\n        class MyData(JSON):\\n            class_var: ClassVar[str] = \\\"hello\\\"\\n\\n        d = MyData()\\n        d.class_var = \\\"world\\\"\\n        # Should go through normal path\\n        assert d.data[\\\"class_var\\\"] == \\\"world\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_dotdict.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bfbd33a31281097d922cd709fc96b9773c2a95f48fb26eae3b275190d3992d6d\",\"content\":\"from lfx.schema.dotdict import dotdict\\n\\n\\ndef test_create_dotdict():\\n    \\\"\\\"\\\"Test creating a dotdict from a regular dict.\\\"\\\"\\\"\\n    sample_dict = {\\\"name\\\": \\\"test\\\", \\\"value\\\": 123, \\\"nested\\\": {\\\"key\\\": \\\"value\\\"}}\\n\\n    dd = dotdict(sample_dict)\\n\\n    # Test dot notation access\\n    assert dd.name == \\\"test\\\"\\n    assert dd.value == 123\\n    assert dd.nested.key == \\\"value\\\"\\n\\n    # Test dict-style access still works\\n    assert dd[\\\"name\\\"] == \\\"test\\\"\\n    assert dd[\\\"value\\\"] == 123\\n    assert dd[\\\"nested\\\"][\\\"key\\\"] == \\\"value\\\"\\n\\n\\ndef test_dotdict_with_complex_structure():\\n    \\\"\\\"\\\"Test dotdict with more complex nested structure.\\\"\\\"\\\"\\n    sample_input = {\\n        \\\"_input_type\\\": \\\"MultilineInput\\\",\\n        \\\"advanced\\\": False,\\n        \\\"display_name\\\": \\\"Chat Input - Text\\\",\\n        \\\"dynamic\\\": False,\\n        \\\"info\\\": \\\"Message to be passed as input.\\\",\\n        \\\"input_types\\\": [\\\"Message\\\"],\\n        \\\"list\\\": False,\\n        \\\"load_from_db\\\": False,\\n        \\\"multiline\\\": True,\\n        \\\"name\\\": \\\"ChatInput-xNZ0a|input_value\\\",\\n        \\\"placeholder\\\": \\\"\\\",\\n        \\\"required\\\": False,\\n        \\\"show\\\": True,\\n        \\\"title_case\\\": False,\\n        \\\"tool_mode\\\": True,\\n        \\\"trace_as_input\\\": True,\\n        \\\"trace_as_metadata\\\": True,\\n        \\\"type\\\": \\\"str\\\",\\n        \\\"value\\\": \\\"add 1+1\\\",\\n    }\\n\\n    dd = dotdict(sample_input)\\n\\n    # Test accessing various fields\\n    assert dd[\\\"_input_type\\\"] == \\\"MultilineInput\\\"\\n    assert dd.advanced is False\\n    assert dd.display_name == \\\"Chat Input - Text\\\"\\n    assert dd.input_types == [\\\"Message\\\"]\\n    assert dd.value == \\\"add 1+1\\\"\\n\\n\\ndef test_dotdict_list_conversion():\\n    \\\"\\\"\\\"Test converting a list of dicts to dotdicts.\\\"\\\"\\\"\\n    sample_list = [{\\\"name\\\": \\\"item1\\\", \\\"value\\\": 1}, {\\\"name\\\": \\\"item2\\\", \\\"value\\\": 2}, {\\\"name\\\": \\\"item3\\\", \\\"value\\\": 3}]\\n\\n    # Convert list of dicts to list of dotdicts\\n    dotdict_list = [dotdict(item) for item in sample_list]\\n\\n    assert len(dotdict_list) == 3\\n    assert dotdict_list[0].name == \\\"item1\\\"\\n    assert dotdict_list[1].value == 2\\n    assert dotdict_list[2].name == \\\"item3\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_image.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ca503b8ccb16513e2216a7d77433cdc73d2fd8ba110c275edbea0268dd6b5f2e\",\"content\":\"import tempfile\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport aiofiles\\nimport pytest\\nfrom lfx.schema.image import (\\n    get_file_paths,\\n    get_files,\\n    is_image_file,\\n)\\nfrom PIL import Image as PILImage\\n\\n\\n@pytest.fixture\\ndef file_image():\\n    image = PILImage.new(\\\"RGB\\\", (100, 100), (255, 0, 0))\\n    with tempfile.NamedTemporaryFile(suffix=\\\".png\\\", delete=True) as temp_file:\\n        image.save(temp_file.name)\\n        yield temp_file.name\\n\\n\\n@pytest.fixture\\ndef file_txt():\\n    content = \\\"\\\"\\\"\\\\\\nline1: This is an example text file.\\nline2: It can be used for testing.\\nline3: End of file.\\n\\\"\\\"\\\"\\n    with tempfile.NamedTemporaryFile(suffix=\\\".txt\\\", delete=False) as temp_file:\\n        temp_file.write(content.encode())\\n        temp_file.flush()\\n        yield temp_file.name\\n\\n\\ndef test_is_image_file(file_image):\\n    assert is_image_file(file_image) is True\\n\\n\\ndef test_is_image_file__not_image(file_txt):\\n    assert is_image_file(file_txt) is False\\n\\n\\ndef test_get_file_paths(file_image, file_txt):\\n    files = [file_image, file_txt]\\n    result = get_file_paths(files)\\n    expected_len = 2\\n    assert len(result) == expected_len\\n    assert result[0].endswith(\\\".png\\\")\\n    assert result[1].endswith(\\\".txt\\\")\\n\\n\\ndef test_get_file_paths_with_dicts():\\n    files = [{\\\"path\\\": \\\"test.png\\\"}, {\\\"path\\\": \\\"test.txt\\\"}]\\n    result = get_file_paths(files)\\n    expected_len = 2\\n    assert len(result) == expected_len\\n    assert result[0].endswith(\\\".png\\\")\\n    assert result[1].endswith(\\\".txt\\\")\\n\\n\\ndef test_get_file_paths__empty():\\n    result = get_file_paths([])\\n    expected_len = 0\\n    assert len(result) == expected_len\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_files(file_image, file_txt, caplog):  # noqa: ARG001\\n    file_paths = [file_image, file_txt]\\n\\n    result = await get_files(file_paths)\\n\\n    for index, file in enumerate(result):\\n        async with aiofiles.open(file_paths[index], \\\"rb\\\") as f:\\n            assert file == await f.read()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_files__convert_to_base64(file_image, file_txt, caplog):  # noqa: ARG001\\n    file_paths = [file_image, file_txt]\\n\\n    result = await get_files(file_paths, convert_to_base64=True)\\n\\n    for index, file in enumerate(result):\\n        async with aiofiles.open(file_paths[index], \\\"rb\\\") as f:\\n            assert file != await f.read()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_files__empty():\\n    result = await get_files([])\\n\\n    assert len(result) == 0\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_files_with_storage_service_local_path():\\n    \\\"\\\"\\\"Test that get_files uses parse_file_path for local storage paths.\\\"\\\"\\\"\\n    mock_storage = MagicMock()\\n    mock_storage.parse_file_path = MagicMock(return_value=(\\\"flow_123\\\", \\\"image.png\\\"))\\n    mock_storage.get_file = AsyncMock(return_value=b\\\"fake image content\\\")\\n\\n    with patch(\\\"lfx.schema.image.get_storage_service\\\", return_value=mock_storage):\\n        result = await get_files([\\\"/data/flow_123/image.png\\\"])\\n\\n        # Verify parse_file_path was called with the correct path\\n        mock_storage.parse_file_path.assert_called_once_with(\\\"/data/flow_123/image.png\\\")\\n        # Verify get_file was called with parsed flow_id and file_name\\n        mock_storage.get_file.assert_called_once_with(flow_id=\\\"flow_123\\\", file_name=\\\"image.png\\\")\\n        # Verify result contains the file content\\n        assert result == [b\\\"fake image content\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_files_with_storage_service_s3_path():\\n    \\\"\\\"\\\"Test that get_files uses parse_file_path for S3 storage paths.\\\"\\\"\\\"\\n    mock_storage = MagicMock()\\n    # S3 path with prefix\\n    mock_storage.parse_file_path = MagicMock(return_value=(\\\"flow_456\\\", \\\"document.pdf\\\"))\\n    mock_storage.get_file = AsyncMock(return_value=b\\\"fake pdf content\\\")\\n\\n    with patch(\\\"lfx.schema.image.get_storage_service\\\", return_value=mock_storage):\\n        result = await get_files([\\\"files/flow_456/document.pdf\\\"])\\n\\n        # Verify parse_file_path was called with the S3 path\\n        mock_storage.parse_file_path.assert_called_once_with(\\\"files/flow_456/document.pdf\\\")\\n        # Verify get_file was called with parsed flow_id and file_name\\n        mock_storage.get_file.assert_called_once_with(flow_id=\\\"flow_456\\\", file_name=\\\"document.pdf\\\")\\n        # Verify result contains the file content\\n        assert result == [b\\\"fake pdf content\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_files_with_storage_service_convert_to_base64():\\n    \\\"\\\"\\\"Test that get_files converts to base64 when requested.\\\"\\\"\\\"\\n    import base64\\n\\n    mock_storage = MagicMock()\\n    mock_storage.parse_file_path = MagicMock(return_value=(\\\"flow_789\\\", \\\"test.txt\\\"))\\n    mock_storage.get_file = AsyncMock(return_value=b\\\"test content\\\")\\n\\n    with patch(\\\"lfx.schema.image.get_storage_service\\\", return_value=mock_storage):\\n        result = await get_files([\\\"flow_789/test.txt\\\"], convert_to_base64=True)\\n\\n        # Verify parse_file_path was called\\n        mock_storage.parse_file_path.assert_called_once_with(\\\"flow_789/test.txt\\\")\\n        # Verify result is base64 encoded\\n        assert isinstance(result[0], str)\\n        assert result[0] == base64.b64encode(b\\\"test content\\\").decode(\\\"utf-8\\\")\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_files_with_storage_service_multiple_files():\\n    \\\"\\\"\\\"Test that get_files handles multiple files correctly.\\\"\\\"\\\"\\n    mock_storage = MagicMock()\\n    mock_storage.parse_file_path = MagicMock(side_effect=[(\\\"flow_1\\\", \\\"file1.txt\\\"), (\\\"flow_2\\\", \\\"file2.txt\\\")])\\n    mock_storage.get_file = AsyncMock(side_effect=[b\\\"content1\\\", b\\\"content2\\\"])\\n\\n    with patch(\\\"lfx.schema.image.get_storage_service\\\", return_value=mock_storage):\\n        result = await get_files([\\\"flow_1/file1.txt\\\", \\\"flow_2/file2.txt\\\"])\\n\\n        # Verify parse_file_path was called for each file\\n        assert mock_storage.parse_file_path.call_count == 2\\n        # Verify get_file was called for each file\\n        assert mock_storage.get_file.call_count == 2\\n        # Verify results\\n        assert result == [b\\\"content1\\\", b\\\"content2\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_input_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ec8c7b25042de557e192976335c779fa1e3361259f59b68d74d67e33c6b5e4e2\",\"content\":\"from typing import Literal, get_args, get_origin\\n\\nimport pytest\\nfrom lfx.inputs.inputs import DropdownInput\\nfrom lfx.io.schema import MAX_OPTIONS_FOR_TOOL_ENUM, create_input_schema, create_input_schema_from_dict\\nfrom lfx.schema.dotdict import dotdict\\n\\n\\ndef _serialized_input(field_type):\\n    return [\\n        dotdict(\\n            {\\n                \\\"name\\\": \\\"value\\\",\\n                \\\"display_name\\\": \\\"Value\\\",\\n                \\\"info\\\": \\\"\\\",\\n                \\\"required\\\": True,\\n                \\\"type\\\": field_type,\\n                \\\"value\\\": None,\\n            }\\n        )\\n    ]\\n\\n\\ndef test_create_input_schema_resolves_known_serialized_type():\\n    schema = create_input_schema_from_dict(_serialized_input(\\\"str\\\"))\\n\\n    assert schema.model_fields[\\\"value\\\"].annotation is str\\n\\n\\ndef test_create_input_schema_rejects_unknown_serialized_type():\\n    with pytest.raises(TypeError, match=\\\"Unsupported serialized field type\\\"):\\n        create_input_schema_from_dict(_serialized_input(\\\"module.UnknownType\\\"))\\n\\n\\ndef _serialized_input_with_options(field_type, options):\\n    return [\\n        dotdict(\\n            {\\n                \\\"name\\\": \\\"value\\\",\\n                \\\"display_name\\\": \\\"Value\\\",\\n                \\\"info\\\": \\\"\\\",\\n                \\\"required\\\": True,\\n                \\\"type\\\": field_type,\\n                \\\"value\\\": None,\\n                \\\"options\\\": options,\\n                \\\"is_list\\\": False,\\n            }\\n        )\\n    ]\\n\\n\\ndef test_create_input_schema_from_dict_builds_literal_from_options():\\n    \\\"\\\"\\\"Serialized dropdown options should produce a Literal type without eval().\\\"\\\"\\\"\\n    schema = create_input_schema_from_dict(_serialized_input_with_options(\\\"str\\\", [\\\"a\\\", \\\"b\\\", \\\"c\\\"]))\\n\\n    annotation = schema.model_fields[\\\"value\\\"].annotation\\n    assert get_origin(annotation) is Literal\\n    assert get_args(annotation) == (\\\"a\\\", \\\"b\\\", \\\"c\\\")\\n\\n\\ndef test_create_input_schema_from_dict_literal_single_option():\\n    \\\"\\\"\\\"A single option should still produce a valid Literal type.\\\"\\\"\\\"\\n    schema = create_input_schema_from_dict(_serialized_input_with_options(\\\"str\\\", [\\\"only\\\"]))\\n\\n    annotation = schema.model_fields[\\\"value\\\"].annotation\\n    assert get_origin(annotation) is Literal\\n    assert get_args(annotation) == (\\\"only\\\",)\\n\\n\\ndef _dropdown_input(options):\\n    return DropdownInput(name=\\\"mode\\\", display_name=\\\"Mode\\\", info=\\\"Select mode\\\", required=True, options=options)\\n\\n\\ndef test_create_input_schema_builds_literal_from_options():\\n    \\\"\\\"\\\"DropdownInput options should produce a Literal type without eval().\\\"\\\"\\\"\\n    schema = create_input_schema([_dropdown_input([\\\"fast\\\", \\\"balanced\\\", \\\"thorough\\\"])])\\n\\n    annotation = schema.model_fields[\\\"mode\\\"].annotation\\n    assert get_origin(annotation) is Literal\\n    assert get_args(annotation) == (\\\"fast\\\", \\\"balanced\\\", \\\"thorough\\\")\\n\\n\\ndef test_create_input_schema_literal_single_option():\\n    \\\"\\\"\\\"A single option should still produce a valid Literal type.\\\"\\\"\\\"\\n    schema = create_input_schema([_dropdown_input([\\\"only\\\"])])\\n\\n    annotation = schema.model_fields[\\\"mode\\\"].annotation\\n    assert get_origin(annotation) is Literal\\n    assert get_args(annotation) == (\\\"only\\\",)\\n\\n\\ndef test_literal_skipped_when_options_exceed_limit():\\n    \\\"\\\"\\\"Over-limit option lists fall back to the base type instead of Literal.\\\"\\\"\\\"\\n    many = [f\\\"opt{i}\\\" for i in range(MAX_OPTIONS_FOR_TOOL_ENUM + 1)]\\n\\n    from_dict_schema = create_input_schema_from_dict(_serialized_input_with_options(\\\"str\\\", many))\\n    assert from_dict_schema.model_fields[\\\"value\\\"].annotation is str\\n\\n    schema = create_input_schema([_dropdown_input(many)])\\n    assert schema.model_fields[\\\"mode\\\"].annotation is str\\n\\n\\ndef test_literal_skipped_when_options_empty():\\n    \\\"\\\"\\\"An empty option list falls back to the base type instead of Literal.\\\"\\\"\\\"\\n    from_dict_schema = create_input_schema_from_dict(_serialized_input_with_options(\\\"str\\\", []))\\n    assert from_dict_schema.model_fields[\\\"value\\\"].annotation is str\\n\\n    schema = create_input_schema([_dropdown_input([])])\\n    assert schema.model_fields[\\\"mode\\\"].annotation is str\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_json_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"09b76195b4f758a93deb70353a08b03c0fe6a7266810d54d7c8e053ae15152ac\",\"content\":\"\\\"\\\"\\\"Tests for JSON schema utilities, including self-referential schema handling.\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.io.schema import flatten_schema\\nfrom lfx.schema.json_schema import create_input_schema_from_json_schema\\nfrom pydantic import BaseModel, ValidationError\\n\\n\\nclass TestCreateInputSchemaFromJsonSchema:\\n    \\\"\\\"\\\"Tests for create_input_schema_from_json_schema.\\\"\\\"\\\"\\n\\n    def test_simple_flat_schema(self):\\n        \\\"\\\"\\\"A simple flat schema should build successfully.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"name\\\": {\\\"type\\\": \\\"string\\\", \\\"description\\\": \\\"A name\\\"},\\n                \\\"count\\\": {\\\"type\\\": \\\"integer\\\"},\\n            },\\n            \\\"required\\\": [\\\"name\\\"],\\n        }\\n        model = create_input_schema_from_json_schema(schema)\\n        assert model is not None\\n        instance = model(name=\\\"hello\\\")\\n        assert instance.name == \\\"hello\\\"  # type: ignore[attr-defined]\\n        assert instance.count is None  # type: ignore[attr-defined]\\n\\n    def test_schema_with_defs(self):\\n        \\\"\\\"\\\"A schema with $defs and $ref should resolve correctly.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"Address\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"street\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"city\\\": {\\\"type\\\": \\\"string\\\"},\\n                    },\\n                    \\\"required\\\": [\\\"street\\\"],\\n                }\\n            },\\n            \\\"properties\\\": {\\n                \\\"address\\\": {\\\"$ref\\\": \\\"#/$defs/Address\\\"},\\n            },\\n            \\\"required\\\": [\\\"address\\\"],\\n        }\\n        model = create_input_schema_from_json_schema(schema)\\n        assert model is not None\\n\\n    def test_self_referential_schema_does_not_recurse(self):\\n        \\\"\\\"\\\"A self-referential schema (tree node) must not cause infinite recursion.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"TreeNode\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"value\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"children\\\": {\\n                            \\\"type\\\": \\\"array\\\",\\n                            \\\"items\\\": {\\\"$ref\\\": \\\"#/$defs/TreeNode\\\"},\\n                        },\\n                    },\\n                    \\\"required\\\": [\\\"value\\\"],\\n                }\\n            },\\n            \\\"properties\\\": {\\n                \\\"root\\\": {\\\"$ref\\\": \\\"#/$defs/TreeNode\\\"},\\n            },\\n            \\\"required\\\": [\\\"root\\\"],\\n        }\\n        # Must not raise RecursionError or any other exception\\n        model = create_input_schema_from_json_schema(schema)\\n        assert model is not None\\n\\n    def test_circular_ref_chain_does_not_loop(self):\\n        \\\"\\\"\\\"A circular $ref chain (A \u2192 B \u2192 A) must not cause infinite recursion.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"A\\\": {\\\"$ref\\\": \\\"#/$defs/B\\\"},\\n                \\\"B\\\": {\\\"$ref\\\": \\\"#/$defs/A\\\"},\\n            },\\n            \\\"properties\\\": {\\n                \\\"field\\\": {\\\"$ref\\\": \\\"#/$defs/A\\\"},\\n            },\\n        }\\n        # Must not raise RecursionError\\n        model = create_input_schema_from_json_schema(schema)\\n        assert model is not None\\n\\n    def test_directly_self_referential_def(self):\\n        \\\"\\\"\\\"A $def that directly references itself must not cause infinite recursion.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"Node\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"value\\\": {\\\"type\\\": \\\"integer\\\"},\\n                        \\\"next\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"},\\n                    },\\n                    \\\"required\\\": [\\\"value\\\"],\\n                }\\n            },\\n            \\\"properties\\\": {\\n                \\\"head\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"},\\n            },\\n            \\\"required\\\": [\\\"head\\\"],\\n        }\\n        model = create_input_schema_from_json_schema(schema)\\n        assert model is not None\\n\\n    def test_self_referential_fallback_type(self):\\n        \\\"\\\"\\\"Self-referential field should fall back to dict, not disappear.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"Node\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"value\\\": {\\\"type\\\": \\\"integer\\\"},\\n                        \\\"next\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"},\\n                    },\\n                    \\\"required\\\": [\\\"value\\\"],\\n                }\\n            },\\n            \\\"properties\\\": {\\\"head\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"}},\\n            \\\"required\\\": [\\\"head\\\"],\\n        }\\n        model = create_input_schema_from_json_schema(schema)\\n        # Verify the model can be instantiated with nested data\\n        instance = model(head={\\\"value\\\": 1, \\\"next\\\": {\\\"value\\\": 2}})\\n        assert instance.head is not None\\n\\n    def test_self_referential_logs_warning(self):\\n        \\\"\\\"\\\"Self-referential detection should emit a warning.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"Node\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"value\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"next\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"},\\n                    },\\n                }\\n            },\\n            \\\"properties\\\": {\\\"head\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"}},\\n        }\\n        with patch(\\\"lfx.schema.json_schema.logger\\\") as mock_logger:\\n            create_input_schema_from_json_schema(schema)\\n            # At least one warning about self-referential should be logged\\n            warning_calls = [str(c) for c in mock_logger.warning.call_args_list]\\n            assert any(\\\"Self-referential\\\" in call or \\\"self-referential\\\" in call for call in warning_calls)\\n\\n    def test_schema_with_defs_instantiation(self):\\n        \\\"\\\"\\\"A schema with $defs should produce a model that can be instantiated.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"Address\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"street\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"city\\\": {\\\"type\\\": \\\"string\\\"},\\n                    },\\n                    \\\"required\\\": [\\\"street\\\"],\\n                }\\n            },\\n            \\\"properties\\\": {\\n                \\\"address\\\": {\\\"$ref\\\": \\\"#/$defs/Address\\\"},\\n            },\\n            \\\"required\\\": [\\\"address\\\"],\\n        }\\n        model = create_input_schema_from_json_schema(schema)\\n        instance = model(address={\\\"street\\\": \\\"123 Main St\\\"})\\n        assert instance.address is not None\\n\\n    def test_non_object_root_raises(self):\\n        \\\"\\\"\\\"A root schema that is not type 'object' should raise ValueError.\\\"\\\"\\\"\\n        schema = {\\\"type\\\": \\\"array\\\", \\\"items\\\": {\\\"type\\\": \\\"string\\\"}}\\n        with pytest.raises(ValueError, match=\\\"Root schema must be type 'object'\\\"):\\n            create_input_schema_from_json_schema(schema)\\n\\n    @staticmethod\\n    def _two_level_nested_ref_schema():\\n        return {\\n            \\\"$defs\\\": {\\n                \\\"Inner\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"required\\\": [\\\"key\\\"],\\n                    \\\"properties\\\": {\\n                        \\\"key\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"count\\\": {\\\"type\\\": \\\"integer\\\", \\\"default\\\": 0},\\n                    },\\n                },\\n                \\\"Outer\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"required\\\": [\\\"name\\\", \\\"inner\\\"],\\n                    \\\"properties\\\": {\\n                        \\\"name\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"inner\\\": {\\\"$ref\\\": \\\"#/$defs/Inner\\\"},\\n                    },\\n                },\\n            },\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"required\\\": [\\\"payload\\\"],\\n            \\\"properties\\\": {\\\"payload\\\": {\\\"$ref\\\": \\\"#/$defs/Outer\\\"}},\\n        }\\n\\n    def test_two_level_nested_refs_resolve_to_models_not_dict(self):\\n        \\\"\\\"\\\"Two-level nested $defs/$ref must resolve to nested BaseModels, not dict.\\n\\n        Regression: previously, parse_type stripped the $ref and named both nested\\n        models AnonModel0 (because len(model_cache) is 0 during recursive descent),\\n        falsely tripping the self-reference guard and collapsing Inner to dict.\\n        \\\"\\\"\\\"\\n        schema = self._two_level_nested_ref_schema()\\n        model = create_input_schema_from_json_schema(schema)\\n\\n        outer_type = model.model_fields[\\\"payload\\\"].annotation\\n        # payload is required, so it stays a BaseModel (not Optional)\\n        assert isinstance(outer_type, type)\\n        assert issubclass(outer_type, BaseModel)\\n        inner_type = outer_type.model_fields[\\\"inner\\\"].annotation\\n        assert inner_type is not dict, \\\"inner should be a BaseModel, not dict\\\"\\n        assert isinstance(inner_type, type)\\n        assert issubclass(inner_type, BaseModel)\\n\\n        # A valid payload (with inner.key) must validate successfully.\\n        instance = model.model_validate({\\\"payload\\\": {\\\"name\\\": \\\"test\\\", \\\"inner\\\": {\\\"key\\\": \\\"k\\\"}}})\\n        assert instance.payload.name == \\\"test\\\"\\n        assert instance.payload.inner.key == \\\"k\\\"\\n\\n    def test_two_level_nested_refs_missing_inner_field_raises(self):\\n        \\\"\\\"\\\"Omitting the required `inner` field must raise ValidationError on payload.inner.\\\"\\\"\\\"\\n        schema = self._two_level_nested_ref_schema()\\n        model = create_input_schema_from_json_schema(schema)\\n        with pytest.raises(ValidationError) as excinfo:\\n            model.model_validate({\\\"payload\\\": {\\\"name\\\": \\\"test\\\"}})\\n        # The error must reference payload.inner specifically.\\n        assert any(err[\\\"loc\\\"][:2] == (\\\"payload\\\", \\\"inner\\\") for err in excinfo.value.errors())\\n\\n    def test_two_level_nested_refs_no_self_referential_warning(self):\\n        \\\"\\\"\\\"A non-self-referential two-level nested $ref schema must not log self-ref warnings.\\\"\\\"\\\"\\n        schema = self._two_level_nested_ref_schema()\\n        with patch(\\\"lfx.schema.json_schema.logger\\\") as mock_logger:\\n            create_input_schema_from_json_schema(schema)\\n            warning_calls = [str(c) for c in mock_logger.warning.call_args_list]\\n            assert not any(\\\"Self-referential\\\" in c or \\\"self-referential\\\" in c for c in warning_calls), (\\n                f\\\"Unexpected self-referential warning: {warning_calls}\\\"\\n            )\\n\\n    def test_sibling_inline_objects_get_distinct_models(self):\\n        \\\"\\\"\\\"Two sibling inline-object properties must produce distinct nested models.\\n\\n        Regression: anonymous model names previously used len(model_cache), which is\\n        not unique during recursive descent and caused inline siblings to collide.\\n        \\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"first\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\\"a\\\": {\\\"type\\\": \\\"string\\\"}},\\n                    \\\"required\\\": [\\\"a\\\"],\\n                },\\n                \\\"second\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\\"b\\\": {\\\"type\\\": \\\"integer\\\"}},\\n                    \\\"required\\\": [\\\"b\\\"],\\n                },\\n            },\\n            \\\"required\\\": [\\\"first\\\", \\\"second\\\"],\\n        }\\n        model = create_input_schema_from_json_schema(schema)\\n        first_type = model.model_fields[\\\"first\\\"].annotation\\n        second_type = model.model_fields[\\\"second\\\"].annotation\\n        assert isinstance(first_type, type)\\n        assert issubclass(first_type, BaseModel)\\n        assert isinstance(second_type, type)\\n        assert issubclass(second_type, BaseModel)\\n        assert first_type is not second_type\\n        assert \\\"a\\\" in first_type.model_fields\\n        assert \\\"b\\\" in second_type.model_fields\\n\\n        instance = model.model_validate({\\\"first\\\": {\\\"a\\\": \\\"x\\\"}, \\\"second\\\": {\\\"b\\\": 1}})\\n        assert instance.first.a == \\\"x\\\"\\n        assert instance.second.b == 1\\n\\n\\nclass TestFlattenSchema:\\n    \\\"\\\"\\\"Tests for flatten_schema self-referential handling.\\\"\\\"\\\"\\n\\n    def test_flat_schema_passthrough(self):\\n        \\\"\\\"\\\"An already-flat schema should be returned unchanged.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"properties\\\": {\\n                \\\"name\\\": {\\\"type\\\": \\\"string\\\"},\\n                \\\"age\\\": {\\\"type\\\": \\\"integer\\\"},\\n            },\\n            \\\"required\\\": [\\\"name\\\"],\\n        }\\n        result = flatten_schema(schema)\\n        assert result is schema  # Fast path: returns the same object\\n\\n    def test_self_referential_schema_does_not_recurse(self):\\n        \\\"\\\"\\\"A self-referential schema must not cause infinite recursion in _walk.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"TreeNode\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"value\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"children\\\": {\\n                            \\\"type\\\": \\\"array\\\",\\n                            \\\"items\\\": {\\\"$ref\\\": \\\"#/$defs/TreeNode\\\"},\\n                        },\\n                    },\\n                }\\n            },\\n            \\\"properties\\\": {\\n                \\\"root\\\": {\\\"$ref\\\": \\\"#/$defs/TreeNode\\\"},\\n            },\\n        }\\n        # Must not raise RecursionError\\n        result = flatten_schema(schema)\\n        assert result is not None\\n        assert \\\"properties\\\" in result\\n        # The non-recursive leaf \\\"root.value\\\" should be present\\n        assert \\\"root.value\\\" in result[\\\"properties\\\"]\\n\\n    def test_circular_ref_in_flatten_does_not_loop(self):\\n        \\\"\\\"\\\"A circular $ref chain must not loop in _resolve_if_ref.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"A\\\": {\\\"$ref\\\": \\\"#/$defs/B\\\"},\\n                \\\"B\\\": {\\\"$ref\\\": \\\"#/$defs/A\\\"},\\n            },\\n            \\\"properties\\\": {\\n                \\\"field\\\": {\\\"$ref\\\": \\\"#/$defs/A\\\"},\\n            },\\n        }\\n        # Must not raise RecursionError or loop infinitely\\n        result = flatten_schema(schema)\\n        assert result is not None\\n\\n    def test_flatten_self_ref_preserves_non_recursive_fields(self):\\n        \\\"\\\"\\\"Non-recursive fields of a self-referential schema should still appear.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"Node\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"value\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"next\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"},\\n                    },\\n                }\\n            },\\n            \\\"properties\\\": {\\\"head\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"}},\\n        }\\n        result = flatten_schema(schema)\\n        # The non-recursive leaf \\\"head.value\\\" must NOT be lost\\n        assert \\\"head.value\\\" in result[\\\"properties\\\"]\\n\\n    def test_flatten_self_ref_logs_warning(self):\\n        \\\"\\\"\\\"Self-referential detection in flatten_schema should emit a warning.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {\\n                \\\"Node\\\": {\\n                    \\\"type\\\": \\\"object\\\",\\n                    \\\"properties\\\": {\\n                        \\\"value\\\": {\\\"type\\\": \\\"string\\\"},\\n                        \\\"next\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"},\\n                    },\\n                }\\n            },\\n            \\\"properties\\\": {\\\"head\\\": {\\\"$ref\\\": \\\"#/$defs/Node\\\"}},\\n        }\\n        with patch(\\\"lfx.io.schema.logger\\\") as mock_logger:\\n            flatten_schema(schema)\\n            warning_calls = [str(c) for c in mock_logger.warning.call_args_list]\\n            assert any(\\\"circular\\\" in call.lower() or \\\"self-referential\\\" in call.lower() for call in warning_calls)\\n\\n    def test_flatten_missing_def_logs_warning(self):\\n        \\\"\\\"\\\"A $ref pointing to a nonexistent $def should log a warning.\\\"\\\"\\\"\\n        schema = {\\n            \\\"type\\\": \\\"object\\\",\\n            \\\"$defs\\\": {},\\n            \\\"properties\\\": {\\n                \\\"field\\\": {\\\"$ref\\\": \\\"#/$defs/NonExistent\\\"},\\n            },\\n        }\\n        with patch(\\\"lfx.io.schema.logger\\\") as mock_logger:\\n            flatten_schema(schema)\\n            warning_calls = [str(c) for c in mock_logger.warning.call_args_list]\\n            assert any(\\\"not found\\\" in call.lower() for call in warning_calls)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_legacy_render.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7f110945fc29d74a867beb73a45f889e69d725e44778d71471ddf285dec6c135\",\"content\":\"\\\"\\\"\\\"Tests for the v1 (release-1.11.0) content_blocks projection.\\n\\nCovers the flat-agent-log reconstruction: the agent renderer emits a flat,\\nchronological content_blocks list (interleaved text + tool_use, no wrapping\\ngroup), and ``legacy_content_blocks`` reconstructs an \\\"Agent Steps\\\" group so the\\nv1 wire keeps tool-call visibility. The reconstruction must gate on ``tool_use``\\n(the agent-step signal), NOT on \\\"any non-text leaf\\\", or plain replies that carry\\ntop-level ``usage`` / ``media`` leaves (from ``from_lc_message``) would get a\\nphantom \\\"Agent Steps\\\" group on the v1 wire.\\n\\\"\\\"\\\"\\n\\nfrom langchain_core.messages import AIMessage\\nfrom lfx.schema.legacy_render import legacy_content_blocks, render_v1_content_blocks\\nfrom lfx.schema.message import Message\\n\\n\\ndef _leaf(**kwargs):\\n    return {\\\"id\\\": \\\"x\\\", \\\"duration\\\": None, \\\"header\\\": {}, \\\"contents\\\": [], **kwargs}\\n\\n\\ndef test_flat_agent_log_with_tool_use_wraps_into_agent_steps():\\n    \\\"\\\"\\\"A flat log with a tool_use leaf is wrapped so v1 shows the tool call.\\\"\\\"\\\"\\n    flat = [\\n        _leaf(type=\\\"text\\\", text=\\\"let me search\\\"),\\n        _leaf(type=\\\"tool_use\\\", name=\\\"search\\\", tool_input={\\\"q\\\": \\\"x\\\"}, output=\\\"r\\\", error=None),\\n        _leaf(type=\\\"text\\\", text=\\\"final answer\\\"),\\n    ]\\n    result = legacy_content_blocks(flat)\\n    assert len(result) == 1\\n    group = result[0]\\n    assert group[\\\"title\\\"] == \\\"Agent Steps\\\"\\n    assert group[\\\"allow_markdown\\\"] is True\\n    assert group[\\\"media_url\\\"] is None\\n    # all three leaves are kept, in order, stripped of id/contents\\n    assert [c[\\\"type\\\"] for c in group[\\\"contents\\\"]] == [\\\"text\\\", \\\"tool_use\\\", \\\"text\\\"]\\n    assert all(\\\"id\\\" not in c and \\\"contents\\\" not in c for c in group[\\\"contents\\\"])\\n    assert any(c[\\\"type\\\"] == \\\"tool_use\\\" for c in group[\\\"contents\\\"])\\n\\n\\ndef test_plain_reply_with_usage_leaf_is_not_wrapped():\\n    \\\"\\\"\\\"A plain reply (text + top-level usage) must stay text-only on the v1 wire.\\\"\\\"\\\"\\n    blocks = [_leaf(type=\\\"text\\\", text=\\\"Hello!\\\"), _leaf(type=\\\"usage\\\", input_tokens=10, output_tokens=5)]\\n    assert legacy_content_blocks(blocks) == []\\n\\n\\ndef test_multimodal_message_with_media_leaf_is_not_wrapped():\\n    \\\"\\\"\\\"Text + top-level media (a vision message) is not an agent step log.\\\"\\\"\\\"\\n    blocks = [_leaf(type=\\\"text\\\", text=\\\"look\\\"), _leaf(type=\\\"media\\\", urls=[\\\"http://example.com/i.png\\\"])]\\n    assert legacy_content_blocks(blocks) == []\\n\\n\\ndef test_tool_less_agent_answer_projects_empty():\\n    \\\"\\\"\\\"A flat log with no tool call has no steps to show, so it projects to [].\\\"\\\"\\\"\\n    assert legacy_content_blocks([_leaf(type=\\\"text\\\", text=\\\"just an answer\\\")]) == []\\n\\n\\ndef test_grouped_agent_message_still_folds_output_leaf():\\n    \\\"\\\"\\\"The existing grouped-agent path is unchanged: the answer folds as Output.\\\"\\\"\\\"\\n    grouped = [\\n        {\\n            \\\"type\\\": \\\"group\\\",\\n            \\\"title\\\": \\\"Agent Steps\\\",\\n            \\\"allow_markdown\\\": True,\\n            \\\"media_url\\\": None,\\n            \\\"contents\\\": [_leaf(type=\\\"tool_use\\\", name=\\\"s\\\", tool_input={}, output=\\\"o\\\", error=None)],\\n        },\\n        _leaf(type=\\\"text\\\", text=\\\"the answer\\\"),\\n    ]\\n    result = legacy_content_blocks(grouped)\\n    assert len(result) == 1\\n    output_leaf = result[0][\\\"contents\\\"][-1]\\n    assert output_leaf[\\\"header\\\"] == {\\\"title\\\": \\\"Output\\\", \\\"icon\\\": \\\"MessageSquare\\\"}\\n    assert output_leaf[\\\"text\\\"] == \\\"the answer\\\"\\n\\n\\ndef test_lc_message_with_usage_does_not_get_phantom_group():\\n    \\\"\\\"\\\"End-to-end: a real from_lc_message reply does not gain an Agent Steps group.\\\"\\\"\\\"\\n    lc = AIMessage(\\n        content=\\\"Hello there\\\",\\n        usage_metadata={\\\"input_tokens\\\": 3, \\\"output_tokens\\\": 2, \\\"total_tokens\\\": 5},\\n    )\\n    message = Message.from_lc_message(lc)\\n    rendered = render_v1_content_blocks(message.content_blocks)\\n    assert all(block.get(\\\"title\\\") != \\\"Agent Steps\\\" for block in rendered or [])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_message_content_blocks.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2426ca34b8133a884c0a2a229b2e7949b975506f0db4c3e5ee23cc7871dc8206\",\"content\":\"\\\"\\\"\\\"Tests for Message text/content_blocks behavioral contract.\\n\\nThese tests define how text and content_blocks interact:\\n- content_blocks is the source of truth when content_blocks are provided\\n- text is derived from top-level TextContent blocks when content_blocks exist\\n- Text-only messages (Message(text=\\\"hello\\\")) keep content_blocks empty and use the data dict\\n- Reading msg.text concatenates all top-level TextContent blocks\\n- Setting msg.text replaces TextContent blocks, preserving non-text blocks\\n- Round-trips (model_dump -> model_validate) must not double text\\n\\\"\\\"\\\"\\n\\nfrom langchain_core.messages import AIMessage, HumanMessage\\nfrom lfx.schema.content_block import ContentBlock\\nfrom lfx.schema.content_types import (\\n    ErrorContent,\\n    ImageContent,\\n    TextContent,\\n    ToolContent,\\n)\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import ErrorMessage, Message\\nfrom lfx.schema.properties import Source\\nfrom lfx.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_NAME_USER,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass TestLegacyUntaggedContentBlocks:\\n    \\\"\\\"\\\"Stored/legacy content blocks may lack the ``type`` discriminator.\\n\\n    A DB row (or a v1 wire-shape re-store) can carry a bare text block\\n    ``{\\\"text\\\": ...}`` with no ``type`` field. ``Message.create(**row)`` on\\n    memory reload MUST tolerate it (infer ``text``) instead of raising a\\n    ``union_tag_not_found`` ValidationError \u2014 otherwise every subsequent turn\\n    in the session crashes when the agent reloads its history.\\n    \\\"\\\"\\\"\\n\\n    def test_should_parse_untagged_text_block(self):\\n        msg = Message(content_blocks=[{\\\"text\\\": \\\"Oi! Como posso ajudar?\\\"}])\\n        assert len(msg.content_blocks) == 1\\n        assert isinstance(msg.content_blocks[0], TextContent)\\n        assert msg.content_blocks[0].type == \\\"text\\\"\\n        assert msg.content_blocks[0].text == \\\"Oi! Como posso ajudar?\\\"\\n\\n    def test_should_still_parse_untagged_group_block(self):\\n        # Non-regression: the group (title+contents) legacy shape already worked.\\n        msg = Message(content_blocks=[{\\\"title\\\": \\\"Agent Steps\\\", \\\"contents\\\": []}])\\n        assert isinstance(msg.content_blocks[0], ContentBlock)\\n        assert msg.content_blocks[0].type == \\\"group\\\"\\n\\n    def test_should_parse_mixed_untagged_and_tagged_blocks(self):\\n        msg = Message(\\n            content_blocks=[\\n                {\\\"title\\\": \\\"Agent Steps\\\", \\\"contents\\\": []},\\n                {\\\"text\\\": \\\"final answer\\\"},\\n                {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"already tagged\\\"},\\n            ]\\n        )\\n        assert [b.type for b in msg.content_blocks] == [\\\"group\\\", \\\"text\\\", \\\"text\\\"]\\n\\n\\nclass TestContentTypeDiscriminatorSurvivesSerialization:\\n    \\\"\\\"\\\"The ``type`` discriminator must survive every serialization mode.\\n\\n    ``TextContent(text=...)`` leaves ``type`` at its default, so it is NOT in\\n    ``model_fields_set``. A ``model_dump(exclude_unset=True)`` (used by the\\n    message-update path) therefore dropped it, persisting a bare ``{\\\"text\\\": ...}``\\n    that later fails ``union_tag_not_found`` on reload. The discriminator must\\n    always be emitted.\\n    \\\"\\\"\\\"\\n\\n    def test_exclude_unset_keeps_type(self):\\n        assert TextContent(text=\\\"hi\\\").model_dump(exclude_unset=True)[\\\"type\\\"] == \\\"text\\\"\\n\\n    def test_exclude_defaults_keeps_type(self):\\n        assert TextContent(text=\\\"hi\\\").model_dump(exclude_defaults=True)[\\\"type\\\"] == \\\"text\\\"\\n\\n    def test_serialized_block_round_trips_through_message(self):\\n        # The exact failure cycle: dump a text block with exclude_unset, then\\n        # reload it as a Message \u2014 must not raise.\\n        dumped = TextContent(text=\\\"final answer\\\").model_dump(exclude_unset=True)\\n        msg = Message(content_blocks=[dumped])\\n        assert msg.content_blocks[0].type == \\\"text\\\"\\n        assert msg.content_blocks[0].text == \\\"final answer\\\"\\n\\n\\nclass TestMessageConstruction:\\n    \\\"\\\"\\\"Tests for constructing Message objects with the new content_blocks-first model.\\\"\\\"\\\"\\n\\n    def test_text_only(self):\\n        \\\"\\\"\\\"Message(text=\\\"hello\\\") keeps content_blocks empty, text from data dict.\\\"\\\"\\\"\\n        msg = Message(text=\\\"hello\\\")\\n        assert msg.content_blocks == []\\n        assert msg.text == \\\"hello\\\"\\n\\n    def test_content_blocks_only(self):\\n        \\\"\\\"\\\"Message with only content_blocks should derive text from TextContent blocks.\\\"\\\"\\\"\\n        msg = Message(content_blocks=[TextContent(text=\\\"hello\\\")])\\n        assert msg.text == \\\"hello\\\"\\n\\n    def test_both_text_and_content_blocks_prefers_content_blocks(self):\\n        \\\"\\\"\\\"When both text and content_blocks are provided, content_blocks wins.\\\"\\\"\\\"\\n        msg = Message(\\n            text=\\\"ignored\\\",\\n            content_blocks=[TextContent(text=\\\"from blocks\\\")],\\n        )\\n        assert msg.text == \\\"from blocks\\\"\\n        # The content_blocks should contain only what was passed, not a duplicate from text\\n        text_blocks = [b for b in msg.content_blocks if isinstance(b, TextContent)]\\n        assert len(text_blocks) == 1\\n        assert text_blocks[0].text == \\\"from blocks\\\"\\n\\n    def test_empty_message(self):\\n        \\\"\\\"\\\"Message() with no arguments should have empty content_blocks and empty text.\\\"\\\"\\\"\\n        msg = Message()\\n        assert msg.content_blocks == []\\n        assert msg.text == \\\"\\\"\\n\\n    def test_empty_string_text(self):\\n        \\\"\\\"\\\"Message(text='') should not create a TextContent block.\\\"\\\"\\\"\\n        msg = Message(text=\\\"\\\")\\n        # Empty string should not produce a TextContent block\\n        text_blocks = [b for b in msg.content_blocks if isinstance(b, TextContent)]\\n        assert len(text_blocks) == 0\\n        assert msg.text == \\\"\\\"\\n\\n    def test_none_text(self):\\n        \\\"\\\"\\\"Message(text=None) should result in empty text and no content blocks.\\\"\\\"\\\"\\n        msg = Message(text=None)\\n        assert msg.text == \\\"\\\"\\n        assert msg.content_blocks == []\\n\\n    def test_mixed_content_blocks(self):\\n        \\\"\\\"\\\"Text should be concatenated from only top-level TextContent blocks.\\\"\\\"\\\"\\n        msg = Message(\\n            content_blocks=[\\n                TextContent(text=\\\"Hello \\\"),\\n                ToolContent(name=\\\"search\\\", tool_input={\\\"q\\\": \\\"test\\\"}),\\n                TextContent(text=\\\"World\\\"),\\n            ]\\n        )\\n        assert msg.text == \\\"Hello World\\\"\\n\\n    def test_construction_with_grouped_content_block(self):\\n        \\\"\\\"\\\"Old-style ContentBlock(title=..., contents=[...]) should still work in content_blocks.\\\"\\\"\\\"\\n        grouped_block = ContentBlock(\\n            title=\\\"Results\\\",\\n            contents=[TextContent(text=\\\"inside group\\\")],\\n        )\\n        msg = Message(content_blocks=[grouped_block])\\n        # The grouped ContentBlock should be preserved\\n        assert len(msg.content_blocks) == 1\\n        assert isinstance(msg.content_blocks[0], ContentBlock)\\n        assert msg.content_blocks[0].title == \\\"Results\\\"\\n\\n    def test_construction_with_all_other_fields(self):\\n        \\\"\\\"\\\"Text + sender + session_id + other fields should all work together.\\\"\\\"\\\"\\n        msg = Message(\\n            text=\\\"hello\\\",\\n            sender=MESSAGE_SENDER_USER,\\n            sender_name=MESSAGE_SENDER_NAME_USER,\\n            session_id=\\\"session-123\\\",\\n            flow_id=\\\"flow-456\\\",\\n        )\\n        assert msg.text == \\\"hello\\\"\\n        assert msg.sender == MESSAGE_SENDER_USER\\n        assert msg.sender_name == MESSAGE_SENDER_NAME_USER\\n        assert msg.session_id == \\\"session-123\\\"\\n        assert msg.flow_id == \\\"flow-456\\\"\\n        # Text-only messages keep content_blocks empty\\n        assert msg.content_blocks == []\\n\\n\\nclass TestTextGetter:\\n    \\\"\\\"\\\"Tests for reading the text property from content_blocks.\\\"\\\"\\\"\\n\\n    def test_single_text_block(self):\\n        \\\"\\\"\\\"Single TextContent block should return its text.\\\"\\\"\\\"\\n        msg = Message(content_blocks=[TextContent(text=\\\"hello\\\")])\\n        assert msg.text == \\\"hello\\\"\\n\\n    def test_multiple_text_blocks_concatenated(self):\\n        \\\"\\\"\\\"Multiple TextContent blocks should be concatenated.\\\"\\\"\\\"\\n        msg = Message(\\n            content_blocks=[\\n                TextContent(text=\\\"Hello\\\"),\\n                TextContent(text=\\\" \\\"),\\n                TextContent(text=\\\"World\\\"),\\n            ]\\n        )\\n        assert msg.text == \\\"Hello World\\\"\\n\\n    def test_no_text_blocks(self):\\n        \\\"\\\"\\\"When only non-text content exists, text should be empty string.\\\"\\\"\\\"\\n        msg = Message(\\n            content_blocks=[\\n                ToolContent(name=\\\"search\\\", tool_input={\\\"q\\\": \\\"test\\\"}),\\n                ImageContent(urls=[\\\"http://example.com/img.png\\\"]),\\n            ]\\n        )\\n        assert msg.text == \\\"\\\"\\n\\n    def test_text_interspersed_with_other_types(self):\\n        \\\"\\\"\\\"TextContent blocks interspersed with other types should all be concatenated.\\\"\\\"\\\"\\n        msg = Message(\\n            content_blocks=[\\n                TextContent(text=\\\"Part 1\\\"),\\n                ToolContent(name=\\\"calc\\\", tool_input={\\\"expr\\\": \\\"1+1\\\"}),\\n                TextContent(text=\\\" Part 2\\\"),\\n                ImageContent(urls=[\\\"http://example.com/img.png\\\"]),\\n                TextContent(text=\\\" Part 3\\\"),\\n            ]\\n        )\\n        assert msg.text == \\\"Part 1 Part 2 Part 3\\\"\\n\\n    def test_empty_content_blocks(self):\\n        \\\"\\\"\\\"Empty content_blocks list should result in empty text.\\\"\\\"\\\"\\n        msg = Message(content_blocks=[])\\n        assert msg.text == \\\"\\\"\\n\\n    def test_text_is_a_string(self):\\n        \\\"\\\"\\\"msg.text should always be a str instance.\\\"\\\"\\\"\\n        msg = Message(content_blocks=[TextContent(text=\\\"hello\\\")])\\n        assert isinstance(msg.text, str)\\n\\n    def test_text_in_string_operations(self):\\n        \\\"\\\"\\\"msg.text should work in f-strings, .upper(), etc.\\\"\\\"\\\"\\n        msg = Message(content_blocks=[TextContent(text=\\\"hello\\\")])\\n        assert f\\\"Say: {msg.text}\\\" == \\\"Say: hello\\\"\\n        assert msg.text.upper() == \\\"HELLO\\\"\\n        assert msg.text.startswith(\\\"he\\\")\\n        assert len(msg.text) == 5\\n\\n    def test_text_does_not_extract_from_grouped_blocks(self):\\n        \\\"\\\"\\\"TextContent inside a ContentBlock group should NOT contribute to .text.\\\"\\\"\\\"\\n        grouped = ContentBlock(\\n            title=\\\"Details\\\",\\n            contents=[TextContent(text=\\\"hidden inside group\\\")],\\n        )\\n        msg = Message(\\n            content_blocks=[\\n                TextContent(text=\\\"visible\\\"),\\n                grouped,\\n            ]\\n        )\\n        # Only the top-level TextContent should be in .text\\n        assert msg.text == \\\"visible\\\"\\n        assert \\\"hidden inside group\\\" not in msg.text\\n\\n\\nclass TestTextSetter:\\n    \\\"\\\"\\\"Tests for setting the text property and its effect on content_blocks.\\\"\\\"\\\"\\n\\n    def test_set_text_on_empty_appends_text_content(self):\\n        \\\"\\\"\\\"Setting text appends a TextContent at the end of content_blocks.\\n\\n        The value is also mirrored into ``data[text_key]`` for backwards\\n        compatibility with legacy callers.\\n        \\\"\\\"\\\"\\n        msg = Message()\\n        msg.text = \\\"hello\\\"\\n        assert msg.text == \\\"hello\\\"\\n        # New unified behavior: text is materialized as a TextContent block.\\n        assert len(msg.content_blocks) == 1\\n        assert isinstance(msg.content_blocks[-1], TextContent)\\n        assert msg.content_blocks[-1].text == \\\"hello\\\"\\n        # Mirror still present in data for legacy callers.\\n        assert msg.data.get(msg.text_key) == \\\"hello\\\"\\n\\n    def test_set_text_replaces_existing(self):\\n        \\\"\\\"\\\"Setting text should replace text value.\\\"\\\"\\\"\\n        msg = Message(text=\\\"old text\\\")\\n        msg.text = \\\"new text\\\"\\n        assert msg.text == \\\"new text\\\"\\n\\n    def test_set_text_preserves_non_text_blocks(self):\\n        \\\"\\\"\\\"Setting text should preserve non-TextContent blocks.\\\"\\\"\\\"\\n        tool_block = ToolContent(name=\\\"search\\\", tool_input={\\\"q\\\": \\\"test\\\"})\\n        msg = Message(\\n            content_blocks=[\\n                TextContent(text=\\\"old\\\"),\\n                tool_block,\\n            ]\\n        )\\n        msg.text = \\\"new\\\"\\n        assert msg.text == \\\"new\\\"\\n        # The tool block should still be there\\n        tool_blocks = [b for b in msg.content_blocks if isinstance(b, ToolContent)]\\n        assert len(tool_blocks) == 1\\n        assert tool_blocks[0].name == \\\"search\\\"\\n\\n    def test_set_empty_string_removes_text(self):\\n        \\\"\\\"\\\"Setting text to empty string should remove TextContent blocks.\\\"\\\"\\\"\\n        msg = Message(text=\\\"something\\\")\\n        msg.text = \\\"\\\"\\n        assert msg.text == \\\"\\\"\\n        text_blocks = [b for b in msg.content_blocks if isinstance(b, TextContent)]\\n        assert len(text_blocks) == 0\\n\\n    def test_set_text_on_empty_message(self):\\n        \\\"\\\"\\\"Setting text on a completely empty message should work.\\\"\\\"\\\"\\n        msg = Message()\\n        assert msg.text == \\\"\\\"\\n        msg.text = \\\"now has text\\\"\\n        assert msg.text == \\\"now has text\\\"\\n\\n    def test_multiple_set_get_cycles(self):\\n        \\\"\\\"\\\"Multiple set/get cycles should not accumulate garbage.\\\"\\\"\\\"\\n        msg = Message()\\n        for i in range(5):\\n            msg.text = f\\\"iteration {i}\\\"\\n            assert msg.text == f\\\"iteration {i}\\\"\\n\\n    def test_text_block_goes_last(self):\\n        \\\"\\\"\\\"Setting text on a message with non-text blocks appends at the end.\\n\\n        content_blocks reflects chronological order: tool calls first, final\\n        answer last.\\n        \\\"\\\"\\\"\\n        tool_block = ToolContent(name=\\\"tool\\\", tool_input={})\\n        msg = Message(content_blocks=[tool_block])\\n        msg.text = \\\"first\\\"\\n        assert isinstance(msg.content_blocks[-1], TextContent)\\n        assert msg.content_blocks[-1].text == \\\"first\\\"\\n        # Non-text block stays at its original position\\n        assert isinstance(msg.content_blocks[0], ToolContent)\\n\\n    def test_set_text_to_iterator_drops_stale_text_content(self):\\n        \\\"\\\"\\\"Setting text to a stream drops existing TextContent and stashes the stream.\\n\\n        The stale prior-round TextContent is removed so it can't resurface once the\\n        stream is consumed, and the data mirror is cleared. The getter returns the\\n        pending stream as-is for streaming consumers; non-text blocks are preserved.\\n        \\\"\\\"\\\"\\n\\n        def gen():\\n            yield \\\"streamed\\\"\\n\\n        stream = gen()\\n        tool_block = ToolContent(name=\\\"search\\\", tool_input={\\\"q\\\": \\\"x\\\"})\\n        msg = Message(content_blocks=[TextContent(text=\\\"old\\\"), tool_block])\\n        msg.text = stream\\n        # The stale prior TextContent is dropped, not left to resurface.\\n        assert all(not isinstance(b, TextContent) for b in msg.content_blocks)\\n        # The getter returns the pending stream for streaming consumers.\\n        assert msg.text is stream\\n        # Non-text blocks stay.\\n        tool_blocks = [b for b in msg.content_blocks if isinstance(b, ToolContent)]\\n        assert len(tool_blocks) == 1\\n        # The stream is stashed for later consumption.\\n        assert msg.text_stream is not None\\n\\n\\nclass TestSerialization:\\n    \\\"\\\"\\\"Tests for model_dump / model_validate round-trip behavior.\\\"\\\"\\\"\\n\\n    def test_model_dump_includes_text(self):\\n        \\\"\\\"\\\"model_dump() should include a 'text' key (computed_field appears in serialization).\\\"\\\"\\\"\\n        msg = Message(text=\\\"hello\\\")\\n        dumped = msg.model_dump()\\n        assert \\\"text\\\" in dumped\\n        assert dumped[\\\"text\\\"] == \\\"hello\\\"\\n\\n    def test_model_dump_includes_content_blocks(self):\\n        \\\"\\\"\\\"model_dump() should include content_blocks.\\\"\\\"\\\"\\n        msg = Message(content_blocks=[TextContent(text=\\\"hello\\\")])\\n        dumped = msg.model_dump()\\n        assert \\\"content_blocks\\\" in dumped\\n        assert len(dumped[\\\"content_blocks\\\"]) >= 1\\n\\n    def test_roundtrip_text_only(self):\\n        \\\"\\\"\\\"model_dump -> model_validate should preserve text correctly.\\\"\\\"\\\"\\n        msg = Message(text=\\\"hello\\\")\\n        dumped = msg.model_dump()\\n        restored = Message.model_validate(dumped)\\n        assert restored.text == \\\"hello\\\"\\n        # Text-only messages keep content_blocks empty\\n        assert restored.content_blocks == []\\n\\n    def test_roundtrip_mixed_content(self):\\n        \\\"\\\"\\\"Round-trip with mixed content types should preserve everything.\\\"\\\"\\\"\\n        msg = Message(\\n            content_blocks=[\\n                TextContent(text=\\\"hello\\\"),\\n                ToolContent(name=\\\"search\\\", tool_input={\\\"q\\\": \\\"test\\\"}),\\n            ]\\n        )\\n        dumped = msg.model_dump()\\n        restored = Message.model_validate(dumped)\\n        assert restored.text == \\\"hello\\\"\\n        assert len(restored.content_blocks) == 2\\n        assert isinstance(restored.content_blocks[0], TextContent)\\n        assert isinstance(restored.content_blocks[1], ToolContent)\\n\\n    def test_roundtrip_json(self):\\n        \\\"\\\"\\\"model_dump_json -> model_validate_json round-trip should work.\\\"\\\"\\\"\\n        msg = Message(\\n            text=\\\"hello\\\",\\n            sender=MESSAGE_SENDER_USER,\\n            sender_name=MESSAGE_SENDER_NAME_USER,\\n        )\\n        json_str = msg.model_dump_json()\\n        restored = Message.model_validate_json(json_str)\\n        assert restored.text == \\\"hello\\\"\\n\\n    def test_deserialize_old_format_text_only(self):\\n        \\\"\\\"\\\"Deserializing old format with text and empty content_blocks should work.\\\"\\\"\\\"\\n        old_data = {\\n            \\\"text\\\": \\\"hello\\\",\\n            \\\"content_blocks\\\": [],\\n        }\\n        msg = Message(**old_data)\\n        assert msg.text == \\\"hello\\\"\\n        # Text stays in data dict, content_blocks stays empty\\n        assert msg.content_blocks == []\\n\\n    def test_deserialize_new_format(self):\\n        \\\"\\\"\\\"Deserializing new format with content_blocks containing TextContent should work.\\\"\\\"\\\"\\n        new_data = {\\n            \\\"content_blocks\\\": [{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"hello\\\"}],\\n        }\\n        msg = Message(**new_data)\\n        assert msg.text == \\\"hello\\\"\\n\\n    def test_deserialize_both_present_content_blocks_wins(self):\\n        \\\"\\\"\\\"When both text and content_blocks are present in data, content_blocks wins.\\\"\\\"\\\"\\n        data = {\\n            \\\"text\\\": \\\"from text field\\\",\\n            \\\"content_blocks\\\": [{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"from blocks\\\"}],\\n        }\\n        msg = Message(**data)\\n        assert msg.text == \\\"from blocks\\\"\\n\\n\\nclass TestBackwardsCompatibility:\\n    \\\"\\\"\\\"Tests for backwards compatibility with existing Message usage patterns.\\\"\\\"\\\"\\n\\n    def test_from_lc_message_human(self):\\n        \\\"\\\"\\\"Message.from_lc_message with HumanMessage should work.\\\"\\\"\\\"\\n        lc_msg = HumanMessage(content=\\\"hello from user\\\")\\n        msg = Message.from_lc_message(lc_msg)\\n        assert msg.text == \\\"hello from user\\\"\\n        assert msg.sender == MESSAGE_SENDER_USER\\n        assert msg.sender_name == MESSAGE_SENDER_NAME_USER\\n\\n    def test_from_lc_message_ai(self):\\n        \\\"\\\"\\\"Message.from_lc_message with AIMessage should work.\\\"\\\"\\\"\\n        lc_msg = AIMessage(content=\\\"hello from ai\\\")\\n        msg = Message.from_lc_message(lc_msg)\\n        assert msg.text == \\\"hello from ai\\\"\\n        assert msg.sender == MESSAGE_SENDER_AI\\n        assert msg.sender_name == MESSAGE_SENDER_NAME_AI\\n\\n    def test_to_lc_message_user(self):\\n        \\\"\\\"\\\"Converting a user Message to lc_message should produce HumanMessage.\\\"\\\"\\\"\\n        msg = Message(text=\\\"hello\\\", sender=MESSAGE_SENDER_USER)\\n        lc_msg = msg.to_lc_message()\\n        assert isinstance(lc_msg, HumanMessage)\\n        assert lc_msg.content == \\\"hello\\\"\\n\\n    def test_to_lc_message_ai(self):\\n        \\\"\\\"\\\"Converting an AI Message to lc_message should produce AIMessage.\\\"\\\"\\\"\\n        msg = Message(text=\\\"hello\\\", sender=MESSAGE_SENDER_AI)\\n        lc_msg = msg.to_lc_message()\\n        assert isinstance(lc_msg, AIMessage)\\n        assert lc_msg.content == \\\"hello\\\"\\n\\n    def test_error_message_still_works(self):\\n        \\\"\\\"\\\"ErrorMessage should still create content_blocks with ErrorContent.\\\"\\\"\\\"\\n        source = Source(\\n            id=\\\"test-id\\\",\\n            display_name=\\\"TestComponent\\\",\\n            source=\\\"TestComponent\\\",\\n        )\\n        exc = ValueError(\\\"something went wrong\\\")\\n        err_msg = ErrorMessage(\\n            exception=exc,\\n            session_id=\\\"session-1\\\",\\n            source=source,\\n            flow_id=\\\"flow-1\\\",\\n        )\\n        assert err_msg.error is True\\n        assert err_msg.category == \\\"error\\\"\\n        # .text should contain the plain error reason\\n        assert \\\"something went wrong\\\" in err_msg.text\\n        # Should have a TextContent (plain reason) and a ContentBlock (error details)\\n        assert len(err_msg.content_blocks) >= 2\\n        assert isinstance(err_msg.content_blocks[0], TextContent)\\n        # Find the grouped error block\\n        error_blocks = [b for b in err_msg.content_blocks if isinstance(b, ContentBlock)]\\n        assert len(error_blocks) == 1\\n        assert error_blocks[0].title == \\\"Error\\\"\\n        error_contents = [c for c in error_blocks[0].contents if isinstance(c, ErrorContent)]\\n        assert len(error_contents) == 1\\n\\n    def test_error_message_renders_complete_os_error(self):\\n        \\\"\\\"\\\"OS errors must show their message and path instead of only the numeric errno.\\\"\\\"\\\"\\n        exc = PermissionError(13, \\\"Permission denied\\\", \\\"tmp_toolguard\\\")\\n\\n        err_msg = ErrorMessage(exception=exc)\\n\\n        assert err_msg.text == \\\"[Errno 13] Permission denied: 'tmp_toolguard'\\\\n\\\"\\n        [error_block] = [block for block in err_msg.content_blocks if isinstance(block, ContentBlock)]\\n        [error_content] = [content for content in error_block.contents if isinstance(content, ErrorContent)]\\n        assert \\\"[Errno 13] Permission denied: 'tmp_toolguard'\\\" in error_content.reason\\n\\n    def test_error_message_renders_reason_coded_exception_message(self):\\n        \\\"\\\"\\\"A reason-coded error shows its human message, not just the class name and code.\\\"\\\"\\\"\\n        from lfx.services.model_provider_policy import ModelProviderPolicyError, ModelProviderPolicyPurpose\\n\\n        exc = ModelProviderPolicyError(\\\"anthropic\\\", ModelProviderPolicyPurpose.USE, model_name=\\\"claude-sonnet-5\\\")\\n        err_msg = ErrorMessage(exception=exc)\\n\\n        assert err_msg.text == str(exc) + \\\"\\\\n\\\"\\n        [error_block] = [block for block in err_msg.content_blocks if isinstance(block, ContentBlock)]\\n        [error_content] = [content for content in error_block.contents if isinstance(content, ErrorContent)]\\n        assert error_content.reason == f\\\"**{exc}**\\\\n - **Code: policy_blocked**\\\\n\\\"\\n        assert \\\"ModelProviderPolicyError\\\" not in error_content.reason\\n\\n    def test_error_message_keeps_code_only_rendering_for_messageless_coded_errors(self):\\n        class CodedError(Exception):\\n            code = \\\"rate_limited\\\"\\n\\n        err_msg = ErrorMessage(exception=CodedError())\\n\\n        assert err_msg.text == \\\"Code: rate_limited\\\\n\\\"\\n        [error_block] = [block for block in err_msg.content_blocks if isinstance(block, ContentBlock)]\\n        [error_content] = [content for content in error_block.contents if isinstance(content, ErrorContent)]\\n        assert error_content.reason == \\\"**CodedError**\\\\n - **Code: rate_limited**\\\\n\\\"\\n\\n    def test_error_message_shows_the_text_of_a_driver_exception_that_carries_a_code(self):\\n        \\\"\\\"\\\"LE-2352: a coded DRIVER error must not collapse to its numeric code.\\n\\n        ``_coded_exception_message`` only looked at ``args[0]``, which reason-coded\\n        Langflow errors populate. A database or SDK exception carries a protocol status\\n        on ``.code`` with ``args`` EMPTY and the human text on ``__str__``, so the\\n        ``hasattr(exception, \\\"code\\\")`` branch short-circuited past the ``.message`` and\\n        ``.detail`` fallbacks below it and rendered a bare code.\\n\\n        Reproduced against a real Astra database: a Table Name containing ``-`` is\\n        invalid CQL, the driver raises ``SyntaxException`` (0x2000 = 8192), and the UI\\n        showed only ``Code: 8192`` while the parser message sat in the logs.\\n        \\\"\\\"\\\"\\n\\n        class DriverError(Exception):\\n            \\\"\\\"\\\"Shaped like cassandra.protocol.SyntaxException: coded, no args.\\\"\\\"\\\"\\n\\n            code = 8192\\n\\n            def __str__(self):\\n                return \\\"<Error from server: code=2000 [Syntax error in CQL query] message=\\\\\\\"mismatched input '-'\\\\\\\">\\\"\\n\\n        exc = DriverError()\\n        assert exc.args == (), \\\"the fixture must reproduce the empty-args shape\\\"\\n\\n        err_msg = ErrorMessage(exception=exc)\\n\\n        assert \\\"Code: 8192\\\" not in err_msg.text, \\\"the numeric code replaced the message\\\"\\n        assert \\\"Syntax error in CQL query\\\" in err_msg.text\\n        [error_block] = [block for block in err_msg.content_blocks if isinstance(block, ContentBlock)]\\n        [error_content] = [content for content in error_block.contents if isinstance(content, ErrorContent)]\\n        assert \\\"Syntax error in CQL query\\\" in error_content.reason\\n        assert \\\"Code: 8192\\\" in error_content.reason, \\\"the code is still useful context alongside the message\\\"\\n\\n    def test_error_message_prefers_an_explicit_message_attribute_over_repr(self):\\n        \\\"\\\"\\\"SDKs that expose ``.message`` should surface it rather than their __str__ noise.\\\"\\\"\\\"\\n\\n        class CodedWithMessageError(Exception):\\n            code = \\\"invalid_request\\\"\\n            message = \\\"Table name must not contain a hyphen.\\\"\\n\\n            def __str__(self):\\n                return \\\"<CodedWithMessageError object at 0xdeadbeef>\\\"\\n\\n        err_msg = ErrorMessage(exception=CodedWithMessageError())\\n\\n        assert \\\"Table name must not contain a hyphen.\\\" in err_msg.text\\n        assert \\\"0xdeadbeef\\\" not in err_msg.text\\n\\n    def test_error_message_can_omit_active_exception_traceback(self):\\n        \\\"\\\"\\\"Public/delegated errors keep a generic reason without the caught traceback.\\\"\\\"\\\"\\n        sensitive_detail = \\\"owner-provider-secret\\\"\\n        try:\\n            raise RuntimeError(sensitive_detail)\\n        except RuntimeError:\\n            err_msg = ErrorMessage(\\n                exception=RuntimeError(\\\"Workflow execution failed.\\\"),\\n                include_traceback=False,\\n            )\\n\\n        [error_block] = [block for block in err_msg.content_blocks if isinstance(block, ContentBlock)]\\n        [error_content] = [content for content in error_block.contents if isinstance(content, ErrorContent)]\\n        assert error_content.traceback == \\\"\\\"\\n        assert sensitive_detail not in err_msg.model_dump_json()\\n\\n    def test_message_from_data(self):\\n        \\\"\\\"\\\"Message.from_data should preserve text through content_blocks.\\\"\\\"\\\"\\n        data = Data(text=\\\"data text\\\")\\n        msg = Message.from_data(data)\\n        assert msg.text == \\\"data text\\\"\\n\\n\\nclass TestFromLcMessageToolCallId:\\n    \\\"\\\"\\\"LangChain plumbs ``tool_call_id`` into ToolContent.id.\\n\\n    LangChain stamps a stable ``tool_call_id`` on every AIMessage.tool_calls\\n    entry. That id is the gold standard for cross-frame correlation: it is\\n    stable across the whole tool lifecycle (start, args streaming, result),\\n    so a ``ToolContent`` re-emitted with output populated keeps the same id\\n    as when it was first emitted without output.\\n\\n    ``id`` is required on the LangChain ``ToolCall`` TypedDict, so there is\\n    no \\\"missing id\\\" path to test from real LangChain usage; ``tc.get(\\\"id\\\")``\\n    is defensive only.\\n    \\\"\\\"\\\"\\n\\n    def test_tool_call_id_lands_on_tool_content(self):\\n        lc_msg = AIMessage(\\n            content=\\\"\\\",\\n            tool_calls=[{\\\"name\\\": \\\"search\\\", \\\"args\\\": {\\\"q\\\": \\\"x\\\"}, \\\"id\\\": \\\"call_abc\\\", \\\"type\\\": \\\"tool_call\\\"}],\\n        )\\n        msg = Message.from_lc_message(lc_msg)\\n        tool_blocks = [b for b in msg.content_blocks if isinstance(b, ToolContent)]\\n        assert len(tool_blocks) == 1\\n        assert tool_blocks[0].id == \\\"call_abc\\\"\\n        assert tool_blocks[0].name == \\\"search\\\"\\n        assert tool_blocks[0].tool_input == {\\\"q\\\": \\\"x\\\"}\\n\\n    def test_id_is_stable_across_repeated_conversion(self):\\n        \\\"\\\"\\\"Replaying from_lc_message produces matching ids.\\n\\n        This is what makes the id useful for dedup: a re-fired add_message\\n        that carries the same logical tool call lands at the same id, not a\\n        new one.\\n        \\\"\\\"\\\"\\n        lc_msg = AIMessage(\\n            content=\\\"\\\",\\n            tool_calls=[{\\\"name\\\": \\\"search\\\", \\\"args\\\": {\\\"q\\\": \\\"x\\\"}, \\\"id\\\": \\\"call_abc\\\", \\\"type\\\": \\\"tool_call\\\"}],\\n        )\\n        first = Message.from_lc_message(lc_msg)\\n        second = Message.from_lc_message(lc_msg)\\n        first_tool = next(b for b in first.content_blocks if isinstance(b, ToolContent))\\n        second_tool = next(b for b in second.content_blocks if isinstance(b, ToolContent))\\n        assert first_tool.id == second_tool.id == \\\"call_abc\\\"\\n\\n    def test_multiple_tool_calls_each_get_their_own_id(self):\\n        lc_msg = AIMessage(\\n            content=\\\"\\\",\\n            tool_calls=[\\n                {\\\"name\\\": \\\"search\\\", \\\"args\\\": {}, \\\"id\\\": \\\"call_a\\\", \\\"type\\\": \\\"tool_call\\\"},\\n                {\\\"name\\\": \\\"calc\\\", \\\"args\\\": {}, \\\"id\\\": \\\"call_b\\\", \\\"type\\\": \\\"tool_call\\\"},\\n            ],\\n        )\\n        msg = Message.from_lc_message(lc_msg)\\n        tool_blocks = [b for b in msg.content_blocks if isinstance(b, ToolContent)]\\n        assert [b.id for b in tool_blocks] == [\\\"call_a\\\", \\\"call_b\\\"]\\n\\n    def test_tool_calls_alongside_string_content(self):\\n        \\\"\\\"\\\"An AIMessage with both text content and tool_calls keeps both.\\n\\n        Tool-calling agents commonly emit ``content=\\\"thinking...\\\"`` plus a\\n        ``tool_calls`` list. Both should land on ``content_blocks``.\\n        \\\"\\\"\\\"\\n        lc_msg = AIMessage(\\n            content=\\\"I'll search for that.\\\",\\n            tool_calls=[{\\\"name\\\": \\\"search\\\", \\\"args\\\": {\\\"q\\\": \\\"x\\\"}, \\\"id\\\": \\\"call_abc\\\", \\\"type\\\": \\\"tool_call\\\"}],\\n        )\\n        msg = Message.from_lc_message(lc_msg)\\n        text_blocks = [b for b in msg.content_blocks if isinstance(b, TextContent)]\\n        tool_blocks = [b for b in msg.content_blocks if isinstance(b, ToolContent)]\\n        assert [b.text for b in text_blocks] == [\\\"I'll search for that.\\\"]\\n        assert [b.id for b in tool_blocks] == [\\\"call_abc\\\"]\\n\\n    def test_raw_tool_use_block_in_content_is_captured(self):\\n        \\\"\\\"\\\"Capture an inline Anthropic ``tool_use`` content block.\\n\\n        LangChain leaves ``.tool_calls`` empty for raw-content messages, so the\\n        content walk must capture it or the call is dropped on round-trips.\\n        \\\"\\\"\\\"\\n        lc_msg = AIMessage(\\n            content=[\\n                {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Let me check\\\"},\\n                {\\\"type\\\": \\\"tool_use\\\", \\\"id\\\": \\\"tu_1\\\", \\\"name\\\": \\\"search\\\", \\\"input\\\": {\\\"q\\\": \\\"x\\\"}},\\n            ],\\n        )\\n        # Raw-content AIMessages leave tool_calls empty \u2014 the fallback below\\n        # the content walk won't fire, so the content walk must capture it.\\n        assert lc_msg.tool_calls == []\\n        msg = Message.from_lc_message(lc_msg)\\n        tool_blocks = [b for b in msg.content_blocks if isinstance(b, ToolContent)]\\n        assert len(tool_blocks) == 1\\n        assert tool_blocks[0].name == \\\"search\\\"\\n        assert tool_blocks[0].id == \\\"tu_1\\\"\\n        assert tool_blocks[0].tool_input == {\\\"q\\\": \\\"x\\\"}\\n\\n    def test_tool_use_in_content_and_tool_calls_not_doubled(self):\\n        \\\"\\\"\\\"Inline tool_use plus a matching ``.tool_calls`` entry yield one block.\\n\\n        The same logical call (same id) must not be doubled across the content\\n        walk and the tool_calls fallback.\\n        \\\"\\\"\\\"\\n        lc_msg = AIMessage(\\n            content=[\\n                {\\\"type\\\": \\\"tool_use\\\", \\\"id\\\": \\\"tu_1\\\", \\\"name\\\": \\\"search\\\", \\\"input\\\": {\\\"q\\\": \\\"x\\\"}},\\n            ],\\n            tool_calls=[{\\\"name\\\": \\\"search\\\", \\\"args\\\": {\\\"q\\\": \\\"x\\\"}, \\\"id\\\": \\\"tu_1\\\", \\\"type\\\": \\\"tool_call\\\"}],\\n        )\\n        msg = Message.from_lc_message(lc_msg)\\n        tool_blocks = [b for b in msg.content_blocks if isinstance(b, ToolContent)]\\n        assert len(tool_blocks) == 1\\n        assert tool_blocks[0].id == \\\"tu_1\\\"\\n\\n\\nclass TestMessageResponseFromMessage:\\n    \\\"\\\"\\\"Regression tests for ``MessageResponse.from_message`` timestamp parity.\\n\\n    ``Message.timestamp`` is a string with microsecond precision and a UTC\\n    timezone label (``2026-05-28 19:41:56.196419 UTC``). Pydantic's default\\n    datetime parser rejects that shape, so freshly built Messages used to\\n    raise ``ValidationError`` when round-tripped through\\n    ``MessageResponse.from_message``. The field now uses the shared\\n    ``str_to_timestamp_validator`` so any format ``Message`` recognises also\\n    round-trips through ``MessageResponse``.\\n    \\\"\\\"\\\"\\n\\n    def test_from_message_round_trips_microsecond_timestamp(self):\\n        from lfx.schema.message import Message, MessageResponse\\n\\n        msg = Message(sender=\\\"AI\\\", sender_name=\\\"Bot\\\", text=\\\"hi\\\")\\n        # If the default format ever drifts, this test should still catch\\n        # the regression because Message.timestamp is fed straight into\\n        # MessageResponse.timestamp during ``from_message``.\\n        assert \\\" UTC\\\" in msg.timestamp\\n\\n        response = MessageResponse.from_message(msg)\\n        # Naive equality against the source timestamp would require a\\n        # round-trip serialization; just confirm we got a real datetime\\n        # back and that it's tz-aware (UTC).\\n        assert response.timestamp.tzinfo is not None\\n        assert response.timestamp.utcoffset().total_seconds() == 0\\n\\n\\nclass TestContentBlockExcludeUnset:\\n    \\\"\\\"\\\"Regression test for ``ContentBlock.__init__`` only marking the discriminator as set.\\n\\n    The previous override marked every field as ``model_fields_set``, which\\n    defeated ``model_dump(exclude_unset=True)`` for ``ContentBlock``: a patch\\n    like ``ContentBlock(title=\\\"...\\\")`` would dump every default field and,\\n    when merged onto an existing block by ``aupdate_messages``, would\\n    overwrite fields the caller never touched (e.g. ``duration``).\\n    \\\"\\\"\\\"\\n\\n    def test_exclude_unset_only_carries_explicit_fields(self):\\n        from lfx.schema.content_types import ContentBlock\\n\\n        patch = ContentBlock(title=\\\"new\\\", allow_markdown=False)\\n        dump = patch.model_dump(exclude_unset=True)\\n        # The discriminator must survive so downstream validators that\\n        # consume the partial dict still pick the right ContentType\\n        # variant.\\n        assert dump[\\\"type\\\"] == \\\"group\\\"\\n        # Only the explicitly-set fields (plus the discriminator) ride\\n        # along. Defaulted fields like ``duration``, ``contents``,\\n        # ``header``, ``media_url`` must stay out of the dump so they\\n        # don't clobber existing values on merge.\\n        assert dump.keys() <= {\\\"type\\\", \\\"title\\\", \\\"allow_markdown\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_mustache_template_processing.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b034a1a00dc0c8afb2e076bbfde568cbe43522db36de57e2c6a3e87e8f6d96bf\",\"content\":\"\\\"\\\"\\\"Tests for mustache template processing in the Message class.\\n\\nNote: Our mustache implementation only supports simple variable substitution\\nfor security reasons. Complex features like conditionals, loops, and sections\\nare not supported.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.schema.message import Message\\nfrom lfx.utils.mustache_security import validate_mustache_template\\n\\n\\nclass TestMustacheTemplateProcessing:\\n    \\\"\\\"\\\"Test mustache template processing in the Message class.\\\"\\\"\\\"\\n\\n    def test_format_text_mustache_basic(self):\\n        \\\"\\\"\\\"Test basic mustache template formatting.\\\"\\\"\\\"\\n        message = Message(template=\\\"Hello {{name}}!\\\", variables={\\\"name\\\": \\\"World\\\"})\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Hello World!\\\"\\n        assert message.text == \\\"Hello World!\\\"\\n\\n    def test_format_text_mustache_multiple_variables(self):\\n        \\\"\\\"\\\"Test mustache template with multiple variables.\\\"\\\"\\\"\\n        message = Message(\\n            template=\\\"Hello {{name}}! You are {{age}} years old.\\\", variables={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": \\\"25\\\"}\\n        )\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Hello Alice! You are 25 years old.\\\"\\n\\n    def test_format_text_mustache_missing_variable(self):\\n        \\\"\\\"\\\"Test mustache template with missing variable.\\\"\\\"\\\"\\n        message = Message(template=\\\"Hello {{name}}! You are {{age}} years old.\\\", variables={\\\"name\\\": \\\"Bob\\\"})\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        # Missing variables should render as empty strings\\n        assert result == \\\"Hello Bob! You are  years old.\\\"\\n\\n    def test_format_text_mustache_no_variables(self):\\n        \\\"\\\"\\\"Test mustache template with no variables.\\\"\\\"\\\"\\n        message = Message(template=\\\"Hello World!\\\", variables={})\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Hello World!\\\"\\n\\n    def test_format_text_mustache_empty_template(self):\\n        \\\"\\\"\\\"Test mustache template with empty template.\\\"\\\"\\\"\\n        message = Message(template=\\\"\\\", variables={\\\"name\\\": \\\"Test\\\"})\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"\\\"\\n\\n    def test_format_text_mustache_with_numeric_values(self):\\n        \\\"\\\"\\\"Test mustache template with numeric values.\\\"\\\"\\\"\\n        message = Message(\\n            template=\\\"Price: ${{price}}, Quantity: {{quantity}}\\\", variables={\\\"price\\\": 19.99, \\\"quantity\\\": 3}\\n        )\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Price: $19.99, Quantity: 3\\\"\\n\\n    def test_format_text_mustache_with_newlines(self):\\n        \\\"\\\"\\\"Test mustache template with newlines.\\\"\\\"\\\"\\n        message = Message(\\n            template=\\\"Line 1: {{line1}}\\\\nLine 2: {{line2}}\\\", variables={\\\"line1\\\": \\\"First\\\", \\\"line2\\\": \\\"Second\\\"}\\n        )\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Line 1: First\\\\nLine 2: Second\\\"\\n\\n    def test_format_text_mustache_with_empty_string_variable(self):\\n        \\\"\\\"\\\"Test mustache template with empty string variable.\\\"\\\"\\\"\\n        message = Message(template=\\\"Hello {{name}}!\\\", variables={\\\"name\\\": \\\"\\\"})\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Hello !\\\"\\n\\n    def test_format_text_mustache_with_none_variable(self):\\n        \\\"\\\"\\\"Test mustache template with None variable.\\\"\\\"\\\"\\n        message = Message(template=\\\"Hello {{name}}!\\\", variables={\\\"name\\\": None})\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        # None should render as empty string\\n        assert result == \\\"Hello !\\\"\\n\\n    async def test_from_template_and_variables_mustache(self):\\n        \\\"\\\"\\\"Test from_template_and_variables with mustache format.\\\"\\\"\\\"\\n        message = await Message.from_template_and_variables(\\n            template=\\\"Hello {{name}}!\\\", template_format=\\\"mustache\\\", name=\\\"World\\\"\\n        )\\n\\n        assert isinstance(message, Message)\\n        assert message.text == \\\"Hello World!\\\"\\n        assert message.template == \\\"Hello {{name}}!\\\"\\n        assert message.variables == {\\\"name\\\": \\\"World\\\"}\\n\\n    async def test_from_template_and_variables_mustache_no_variables(self):\\n        \\\"\\\"\\\"Test from_template_and_variables with no variables.\\\"\\\"\\\"\\n        message = await Message.from_template_and_variables(template=\\\"Static message\\\", template_format=\\\"mustache\\\")\\n\\n        assert isinstance(message, Message)\\n        assert message.text == \\\"Static message\\\"\\n        assert message.variables == {}\\n\\n    def test_format_text_mustache_preserves_original_variables(self):\\n        \\\"\\\"\\\"Test that format_text doesn't modify the original variables.\\\"\\\"\\\"\\n        original_variables = {\\\"name\\\": \\\"Test\\\", \\\"age\\\": 25}\\n        message = Message(template=\\\"Hello {{name}}, age {{age}}!\\\", variables=original_variables.copy())\\n\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Hello Test, age 25!\\\"\\n        assert message.variables == original_variables\\n\\n    def test_format_text_mustache_with_zero_values(self):\\n        \\\"\\\"\\\"Test mustache template with zero values.\\\"\\\"\\\"\\n        message = Message(template=\\\"Count: {{count}}, Price: {{price}}\\\", variables={\\\"count\\\": 0, \\\"price\\\": 0.0})\\n        result = message.format_text(template_format=\\\"mustache\\\")\\n\\n        assert result == \\\"Count: 0, Price: 0.0\\\"\\n\\n    def test_mustache_security_rejects_conditionals(self):\\n        \\\"\\\"\\\"Test that conditional syntax is rejected for security.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{#show}}Hello{{/show}}\\\")\\n\\n    def test_mustache_security_rejects_inverted_sections(self):\\n        \\\"\\\"\\\"Test that inverted section syntax is rejected for security.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{^items}}No items{{/items}}\\\")\\n\\n    def test_mustache_security_rejects_loops(self):\\n        \\\"\\\"\\\"Test that loop syntax is rejected for security.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{#items}}{{.}}{{/items}}\\\")\\n\\n    def test_mustache_security_rejects_unescaped_variables(self):\\n        \\\"\\\"\\\"Test that unescaped variable syntax is rejected for security.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{&variable}}\\\")\\n\\n    def test_mustache_security_rejects_partials(self):\\n        \\\"\\\"\\\"Test that partial syntax is rejected for security.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{>partial}}\\\")\\n\\n    def test_mustache_security_rejects_comments(self):\\n        \\\"\\\"\\\"Test that comment syntax is rejected for security.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{!comment}}\\\")\\n\\n    def test_mustache_security_allows_simple_variables(self):\\n        \\\"\\\"\\\"Test that simple variables are allowed.\\\"\\\"\\\"\\n        # Should not raise\\n        validate_mustache_template(\\\"Hello {{name}}!\\\")\\n        validate_mustache_template(\\\"{{var1}} and {{var2}}\\\")\\n\\n    def test_mustache_security_rejects_dot_notation(self):\\n        \\\"\\\"\\\"Test that dot notation is NOT allowed.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_mustache_template(\\\"{{user.name}}\\\")\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_mustache_template(\\\"{{company.ceo.name}}\\\")\\n\\n    def test_format_text_defaults_to_f_string(self):\\n        \\\"\\\"\\\"Test that format_text defaults to f-string format.\\\"\\\"\\\"\\n        message = Message(template=\\\"Hello {name}!\\\", variables={\\\"name\\\": \\\"World\\\"})\\n        result = message.format_text()  # No template_format specified\\n\\n        assert result == \\\"Hello World!\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_output_event.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"07214aee350ee6182977802b9962ddaccb1b48d9b0062e627e7fbd6829445edb\",\"content\":\"\\\"\\\"\\\"Tests for ``OutputEvent`` \u2014 the per-component output shape carried on the stream.\\n\\n``OutputEvent`` is the ``langflow``-protocol stream counterpart of a sync\\n``outputs[id]`` entry: the same ``ComponentOutput`` fields plus the\\n``component_id`` (which, in sync, is the dict key). One parser handles both.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom lfx.schema.workflow import ComponentOutput, JobStatus, OutputEvent\\n\\n\\nclass TestOutputEvent:\\n    def test_is_a_component_output_with_component_id(self):\\n        event = OutputEvent(\\n            component_id=\\\"ChatOutput-abc\\\",\\n            type=\\\"message\\\",\\n            status=JobStatus.COMPLETED,\\n            display_name=\\\"Chat Output\\\",\\n            content=\\\"Hi there!\\\",\\n            metadata={\\\"component_type\\\": \\\"ChatOutput\\\"},\\n        )\\n        # Same payload a parser reads off a sync ``outputs[id]`` entry...\\n        assert event.type == \\\"message\\\"\\n        assert event.status == JobStatus.COMPLETED\\n        assert event.display_name == \\\"Chat Output\\\"\\n        assert event.content == \\\"Hi there!\\\"\\n        assert event.metadata == {\\\"component_type\\\": \\\"ChatOutput\\\"}\\n        # ...plus the id that sync carries as the dict key.\\n        assert event.component_id == \\\"ChatOutput-abc\\\"\\n        # IS-A ComponentOutput, so a handler typed for the sync shape accepts it.\\n        assert isinstance(event, ComponentOutput)\\n\\n    def test_component_id_is_required(self):\\n        import pytest\\n        from pydantic import ValidationError\\n\\n        with pytest.raises(ValidationError) as exc:\\n            OutputEvent(type=\\\"message\\\", status=JobStatus.COMPLETED)\\n        assert \\\"component_id\\\" in str(exc.value)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_schema_data.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b4d8473c5eabd7ec3b07a3a2642313e4ca8a85eb7efcdc8596fc8b2436cb3f0\",\"content\":\"import base64\\n\\nimport pytest\\nfrom langchain_core.messages import AIMessage, HumanMessage\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.constants import MESSAGE_SENDER_AI, MESSAGE_SENDER_USER\\n\\n\\n@pytest.fixture\\ndef sample_image(tmp_path):\\n    \\\"\\\"\\\"Create a sample image file for testing.\\\"\\\"\\\"\\n    image_path = tmp_path / \\\"test_image.png\\\"\\n    # Create a small black 1x1 pixel PNG file\\n    image_content = base64.b64decode(\\n        \\\"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==\\\"\\n    )\\n    image_path.write_bytes(image_content)\\n    return image_path\\n\\n\\nclass TestDataSchema:\\n    def test_data_to_message_with_text_only(self):\\n        \\\"\\\"\\\"Test conversion of Data to Message with text only.\\\"\\\"\\\"\\n        data = Data(data={\\\"text\\\": \\\"Hello, world!\\\", \\\"sender\\\": MESSAGE_SENDER_USER})\\n        message = data.to_lc_message()\\n        assert isinstance(message, HumanMessage)\\n        assert message.content == [{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Hello, world!\\\"}]\\n\\n    def test_data_to_message_with_image(self, sample_image):\\n        \\\"\\\"\\\"Test conversion of Data to Message with text and image.\\\"\\\"\\\"\\n        data = Data(data={\\\"text\\\": \\\"Check out this image\\\", \\\"sender\\\": MESSAGE_SENDER_USER, \\\"files\\\": [str(sample_image)]})\\n        message = data.to_lc_message()\\n\\n        assert isinstance(message, HumanMessage)\\n        assert isinstance(message.content, list)\\n        expected_content_len = 2\\n        assert len(message.content) == expected_content_len\\n\\n        # Check text content\\n        text_content = message.content[0]\\n        assert text_content == {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Check out this image\\\"}\\n\\n        # Check image content\\n        assert message.content[1][\\\"type\\\"] == \\\"image_url\\\"\\n        assert \\\"image_url\\\" in message.content[1]\\n        assert \\\"url\\\" in message.content[1][\\\"image_url\\\"]\\n        assert message.content[1][\\\"image_url\\\"][\\\"url\\\"].startswith(\\\"data:image/png;base64,\\\")\\n\\n    def test_data_to_message_with_multiple_images(self, sample_image, tmp_path):\\n        \\\"\\\"\\\"Test conversion of Data to Message with multiple images.\\\"\\\"\\\"\\n        # Create a second image\\n        second_image = tmp_path / \\\"second_image.png\\\"\\n        second_image.write_bytes(sample_image.read_bytes())\\n\\n        data = Data(\\n            data={\\n                \\\"text\\\": \\\"Multiple images\\\",\\n                \\\"sender\\\": MESSAGE_SENDER_USER,\\n                \\\"files\\\": [str(sample_image), str(second_image)],\\n            }\\n        )\\n        message = data.to_lc_message()\\n\\n        assert isinstance(message, HumanMessage)\\n        assert isinstance(message.content, list)\\n        expected_content_len = 3  # text + 2 images\\n        assert len(message.content) == expected_content_len\\n\\n        # Check text content\\n        text_content = message.content[0]\\n        assert text_content[\\\"type\\\"] == \\\"text\\\"\\n\\n        # Check both images\\n        assert message.content[1][\\\"type\\\"] == \\\"image_url\\\"\\n        assert \\\"image_url\\\" in message.content[1]\\n        assert \\\"url\\\" in message.content[1][\\\"image_url\\\"]\\n        assert message.content[1][\\\"image_url\\\"][\\\"url\\\"].startswith(\\\"data:image/png;base64,\\\")\\n\\n        assert message.content[2][\\\"type\\\"] == \\\"image_url\\\"\\n        assert \\\"image_url\\\" in message.content[2]\\n        assert \\\"url\\\" in message.content[2][\\\"image_url\\\"]\\n        assert message.content[2][\\\"image_url\\\"][\\\"url\\\"].startswith(\\\"data:image/png;base64,\\\")\\n\\n    def test_data_to_message_ai_response(self):\\n        \\\"\\\"\\\"Test conversion of Data to AI Message.\\\"\\\"\\\"\\n        data = Data(data={\\\"text\\\": \\\"AI response\\\", \\\"sender\\\": MESSAGE_SENDER_AI})\\n        message = data.to_lc_message()\\n        assert isinstance(message, AIMessage)\\n        assert message.content == \\\"AI response\\\"\\n\\n    def test_data_to_message_missing_required_keys(self):\\n        \\\"\\\"\\\"Test conversion fails with missing required keys.\\\"\\\"\\\"\\n        data = Data(data={\\\"incomplete\\\": \\\"data\\\"})\\n        with pytest.raises(ValueError, match=\\\"Missing required keys\\\"):\\n            data.to_lc_message()\\n\\n    def test_data_to_message_invalid_image_path(self, tmp_path):\\n        \\\"\\\"\\\"Test handling of invalid image path.\\\"\\\"\\\"\\n        non_existent_image = tmp_path / \\\"non_existent.png\\\"\\n        data = Data(data={\\\"text\\\": \\\"Invalid image\\\", \\\"sender\\\": MESSAGE_SENDER_USER, \\\"files\\\": [str(non_existent_image)]})\\n\\n        with pytest.raises(FileNotFoundError):\\n            data.to_lc_message()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_schema_data_set.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"78cc64a490de616e1961318c1717dcd3e1a4f32cfc5ac99c33d7a356e0d96afd\",\"content\":\"import pandas as pd\\nimport pytest\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\n@pytest.fixture\\ndef sample_data_objects() -> list[Data]:\\n    \\\"\\\"\\\"Fixture providing a list of sample Data objects.\\\"\\\"\\\"\\n    return [\\n        Data(data={\\\"name\\\": \\\"John\\\", \\\"age\\\": 30, \\\"city\\\": \\\"New York\\\"}),\\n        Data(data={\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25, \\\"city\\\": \\\"Boston\\\"}),\\n        Data(data={\\\"name\\\": \\\"Bob\\\", \\\"age\\\": 35, \\\"city\\\": \\\"Chicago\\\"}),\\n    ]\\n\\n\\n@pytest.fixture\\ndef sample_dataset(sample_data_objects) -> DataFrame:\\n    \\\"\\\"\\\"Fixture providing a sample DataFrame instance.\\\"\\\"\\\"\\n    return DataFrame(sample_data_objects)\\n\\n\\ndef test_from_data_list_basic():\\n    \\\"\\\"\\\"Test basic functionality of from_data_list.\\\"\\\"\\\"\\n    data_objects = [Data(data={\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}), Data(data={\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25})]\\n    dataset = DataFrame(data_objects)\\n\\n    assert isinstance(dataset, DataFrame)\\n    assert isinstance(dataset, pd.DataFrame)\\n    expected_len = 2\\n    assert len(dataset) == expected_len\\n    assert list(dataset.columns) == [\\\"name\\\", \\\"age\\\"]\\n    assert dataset.iloc[0][\\\"name\\\"] == \\\"John\\\"\\n    expected_age = 25\\n    assert dataset.iloc[1][\\\"age\\\"] == expected_age\\n\\n\\ndef test_from_data_list_empty():\\n    \\\"\\\"\\\"Test from_data_list with empty input.\\\"\\\"\\\"\\n    dataset = DataFrame([])\\n    assert isinstance(dataset, DataFrame)\\n    assert len(dataset) == 0\\n\\n\\ndef test_from_data_list_missing_fields():\\n    \\\"\\\"\\\"Test from_data_list with inconsistent data fields.\\\"\\\"\\\"\\n    data_objects = [\\n        Data(data={\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}),\\n        Data(data={\\\"name\\\": \\\"Jane\\\", \\\"city\\\": \\\"Boston\\\"}),  # Missing age\\n    ]\\n    dataset = DataFrame(data_objects)\\n\\n    assert isinstance(dataset, DataFrame)\\n    assert set(dataset.columns) == {\\\"name\\\", \\\"age\\\", \\\"city\\\"}\\n    assert pd.isna(dataset.iloc[1][\\\"age\\\"])\\n    assert pd.isna(dataset.iloc[0][\\\"city\\\"])\\n\\n\\ndef test_from_data_list_nested_data():\\n    \\\"\\\"\\\"Test from_data_list with nested dictionary data.\\\"\\\"\\\"\\n    data_objects = [\\n        Data(data={\\\"name\\\": \\\"John\\\", \\\"address\\\": {\\\"city\\\": \\\"New York\\\", \\\"zip\\\": \\\"10001\\\"}}),\\n        Data(data={\\\"name\\\": \\\"Jane\\\", \\\"address\\\": {\\\"city\\\": \\\"Boston\\\", \\\"zip\\\": \\\"02108\\\"}}),\\n    ]\\n    dataset = DataFrame(data_objects)\\n\\n    assert isinstance(dataset, DataFrame)\\n    assert isinstance(dataset[\\\"address\\\"][0], dict)\\n    assert dataset[\\\"address\\\"][0][\\\"city\\\"] == \\\"New York\\\"\\n\\n\\ndef test_to_data_list_basic(sample_dataset, sample_data_objects):\\n    \\\"\\\"\\\"Test basic functionality of to_data_list.\\\"\\\"\\\"\\n    result = sample_dataset.to_data_list()\\n\\n    assert isinstance(result, list)\\n    assert all(isinstance(item, Data) for item in result)\\n    assert len(result) == len(sample_data_objects)\\n\\n    # Check if data is preserved\\n    for original, converted in zip(sample_data_objects, result, strict=False):\\n        assert original.data == converted.data\\n\\n\\ndef test_to_data_list_empty():\\n    \\\"\\\"\\\"Test to_data_list with empty DataFrame.\\\"\\\"\\\"\\n    empty_dataset = DataFrame()\\n    result = empty_dataset.to_data_list()\\n    assert isinstance(result, list)\\n    assert len(result) == 0\\n\\n\\ndef test_to_data_list_modified_data(sample_dataset):\\n    \\\"\\\"\\\"Test to_data_list after DataFrame modifications.\\\"\\\"\\\"\\n    # Modify the dataset\\n    sample_dataset[\\\"new_column\\\"] = [1, 2, 3]\\n    sample_dataset.iloc[0, sample_dataset.columns.get_loc(\\\"age\\\")] = 31\\n\\n    result = sample_dataset.to_data_list()\\n\\n    assert isinstance(result, list)\\n    assert all(isinstance(item, Data) for item in result)\\n    assert result[0].data[\\\"new_column\\\"] == 1\\n    expected_age = 31\\n    assert result[0].data[\\\"age\\\"] == expected_age\\n\\n\\ndef test_dataset_pandas_operations(sample_dataset):\\n    \\\"\\\"\\\"Test that pandas operations work correctly on DataFrame.\\\"\\\"\\\"\\n    # Test filtering\\n    filtered = sample_dataset[sample_dataset[\\\"age\\\"] > 30]\\n    assert isinstance(filtered, DataFrame), f\\\"Expected DataFrame, got {type(filtered)}\\\"\\n    expected_len = 1\\n    assert len(filtered) == expected_len\\n    assert filtered.iloc[0][\\\"name\\\"] == \\\"Bob\\\"\\n\\n    # Test aggregation\\n    mean_age = sample_dataset[\\\"age\\\"].mean()\\n    expected_mean = 30\\n    assert mean_age == expected_mean\\n\\n    # Test groupby\\n    grouped = sample_dataset.groupby(\\\"city\\\").agg({\\\"age\\\": \\\"mean\\\"})\\n    assert isinstance(grouped, pd.DataFrame)\\n    expected_len = 3\\n    assert len(grouped) == expected_len\\n\\n\\ndef test_dataset_with_null_values():\\n    \\\"\\\"\\\"Test handling of null values in DataFrame.\\\"\\\"\\\"\\n    data_objects = [Data(data={\\\"name\\\": \\\"John\\\", \\\"age\\\": None}), Data(data={\\\"name\\\": None, \\\"age\\\": 25})]\\n    dataset = DataFrame(data_objects)\\n\\n    assert pd.isna(dataset.iloc[0][\\\"age\\\"])\\n    assert pd.isna(dataset.iloc[1][\\\"name\\\"])\\n\\n    # Test that null values are preserved when converting back\\n    result = dataset.to_data_list()\\n    assert pd.isna(result[0].data[\\\"age\\\"]), f\\\"Expected NaN, got {result[0].data['age']}\\\"\\n    assert pd.isna(result[1].data[\\\"name\\\"]), f\\\"Expected NaN, got {result[1].data['name']}\\\"\\n\\n\\ndef test_dataset_type_preservation():\\n    \\\"\\\"\\\"Test that data types are preserved through conversion.\\\"\\\"\\\"\\n    data_objects = [\\n        Data(\\n            data={\\n                \\\"int_val\\\": 1,\\n                \\\"float_val\\\": 1.5,\\n                \\\"str_val\\\": \\\"test\\\",\\n                \\\"bool_val\\\": True,\\n                \\\"list_val\\\": [1, 2, 3],\\n                \\\"dict_val\\\": {\\\"key\\\": \\\"value\\\"},\\n            }\\n        )\\n    ]\\n    dataset = DataFrame(data_objects)\\n    result = dataset.to_data_list()\\n\\n    assert isinstance(result[0].data[\\\"int_val\\\"], int)\\n    assert isinstance(result[0].data[\\\"float_val\\\"], float)\\n    assert isinstance(result[0].data[\\\"str_val\\\"], str)\\n    assert isinstance(result[0].data[\\\"bool_val\\\"], bool)\\n    assert isinstance(result[0].data[\\\"list_val\\\"], list)\\n    assert isinstance(result[0].data[\\\"dict_val\\\"], dict)\\n\\n\\ndef test_add_row_with_dict(sample_dataset):\\n    \\\"\\\"\\\"Test adding a single row using a dictionary.\\\"\\\"\\\"\\n    new_row = {\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 28, \\\"city\\\": \\\"Seattle\\\"}\\n    result = sample_dataset.add_row(new_row)\\n\\n    assert isinstance(result, DataFrame)\\n    assert len(result) == len(sample_dataset) + 1\\n    assert result.iloc[-1][\\\"name\\\"] == \\\"Alice\\\"\\n    expected_age = 28\\n    assert result.iloc[-1][\\\"age\\\"] == expected_age\\n    assert result.iloc[-1][\\\"city\\\"] == \\\"Seattle\\\"\\n\\n\\ndef test_add_row_with_data_object(sample_dataset):\\n    \\\"\\\"\\\"Test adding a single row using a Data object.\\\"\\\"\\\"\\n    new_row = Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 28, \\\"city\\\": \\\"Seattle\\\"})\\n    result = sample_dataset.add_row(new_row)\\n\\n    assert isinstance(result, DataFrame)\\n    assert len(result) == len(sample_dataset) + 1\\n    assert result.iloc[-1][\\\"name\\\"] == \\\"Alice\\\"\\n    expected_age = 28\\n    assert result.iloc[-1][\\\"age\\\"] == expected_age\\n    assert result.iloc[-1][\\\"city\\\"] == \\\"Seattle\\\"\\n\\n\\ndef test_add_rows_with_dicts(sample_dataset):\\n    \\\"\\\"\\\"Test adding multiple rows using dictionaries.\\\"\\\"\\\"\\n    new_rows = [{\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 28, \\\"city\\\": \\\"Seattle\\\"}, {\\\"name\\\": \\\"Charlie\\\", \\\"age\\\": 32, \\\"city\\\": \\\"Portland\\\"}]\\n    result = sample_dataset.add_rows(new_rows)\\n\\n    assert isinstance(result, DataFrame)\\n    assert len(result) == len(sample_dataset) + 2\\n    assert result.iloc[-2][\\\"name\\\"] == \\\"Alice\\\"\\n    assert result.iloc[-1][\\\"name\\\"] == \\\"Charlie\\\"\\n\\n\\ndef test_add_rows_with_data_objects(sample_dataset):\\n    \\\"\\\"\\\"Test adding multiple rows using Data objects.\\\"\\\"\\\"\\n    new_rows = [\\n        Data(data={\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 28, \\\"city\\\": \\\"Seattle\\\"}),\\n        Data(data={\\\"name\\\": \\\"Charlie\\\", \\\"age\\\": 32, \\\"city\\\": \\\"Portland\\\"}),\\n    ]\\n    result = sample_dataset.add_rows(new_rows)\\n\\n    assert isinstance(result, DataFrame)\\n    assert len(result) == len(sample_dataset) + 2\\n    assert result.iloc[-2][\\\"name\\\"] == \\\"Alice\\\"\\n    assert result.iloc[-1][\\\"name\\\"] == \\\"Charlie\\\"\\n\\n\\ndef test_add_rows_mixed_types(sample_dataset):\\n    \\\"\\\"\\\"Test adding multiple rows using a mix of dictionaries and Data objects.\\\"\\\"\\\"\\n    new_rows = [\\n        {\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 28, \\\"city\\\": \\\"Seattle\\\"},\\n        Data(data={\\\"name\\\": \\\"Charlie\\\", \\\"age\\\": 32, \\\"city\\\": \\\"Portland\\\"}),\\n    ]\\n    result = sample_dataset.add_rows(new_rows)\\n\\n    assert isinstance(result, DataFrame)\\n    assert len(result) == len(sample_dataset) + 2\\n    assert result.iloc[-2][\\\"name\\\"] == \\\"Alice\\\"\\n    assert result.iloc[-1][\\\"name\\\"] == \\\"Charlie\\\"\\n\\n\\ndef test_init_with_data_objects():\\n    \\\"\\\"\\\"Test initialization with Data objects.\\\"\\\"\\\"\\n    data_objects = [Data(data={\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}), Data(data={\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25})]\\n    dataset = DataFrame(data_objects)\\n\\n    assert isinstance(dataset, DataFrame)\\n    expected_len = 2\\n    assert len(dataset) == expected_len\\n    assert list(dataset.columns) == [\\\"name\\\", \\\"age\\\"]\\n    assert dataset.iloc[0][\\\"name\\\"] == \\\"John\\\"\\n    expected_age = 25\\n    assert dataset.iloc[1][\\\"age\\\"] == expected_age\\n\\n\\ndef test_init_with_dicts():\\n    \\\"\\\"\\\"Test initialization with dictionaries.\\\"\\\"\\\"\\n    data_dicts = [{\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}, {\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25}]\\n    dataset = DataFrame(data_dicts)\\n\\n    assert isinstance(dataset, DataFrame)\\n    expected_len = 2\\n    assert len(dataset) == expected_len\\n    assert list(dataset.columns) == [\\\"name\\\", \\\"age\\\"]\\n    assert dataset.iloc[0][\\\"name\\\"] == \\\"John\\\"\\n    expected_age = 25\\n    assert dataset.iloc[1][\\\"age\\\"] == expected_age\\n\\n\\ndef test_init_with_dict_of_lists():\\n    \\\"\\\"\\\"Test initialization with a dictionary of lists.\\\"\\\"\\\"\\n    data = {\\\"name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"age\\\": [30, 25]}\\n    dataset = DataFrame(data)\\n\\n    assert isinstance(dataset, DataFrame)\\n    expected_len = 2\\n    assert len(dataset) == expected_len\\n    assert list(dataset.columns) == [\\\"name\\\", \\\"age\\\"]\\n    assert dataset.iloc[0][\\\"name\\\"] == \\\"John\\\"\\n    expected_age = 25\\n    assert dataset.iloc[1][\\\"age\\\"] == expected_age\\n\\n\\ndef test_init_with_pandas_dataframe():\\n    \\\"\\\"\\\"Test initialization with a pandas DataFrame.\\\"\\\"\\\"\\n    test_df = pd.DataFrame({\\\"name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"age\\\": [30, 25]})\\n    dataset = DataFrame(test_df)\\n\\n    assert isinstance(dataset, DataFrame)\\n    expected_len = 2\\n    assert len(dataset) == expected_len\\n    assert list(dataset.columns) == [\\\"name\\\", \\\"age\\\"]\\n    assert dataset.iloc[0][\\\"name\\\"] == \\\"John\\\"\\n    expected_age = 25\\n    assert dataset.iloc[1][\\\"age\\\"] == expected_age\\n\\n\\ndef test_init_with_none():\\n    \\\"\\\"\\\"Test initialization with None.\\\"\\\"\\\"\\n    dataset = DataFrame(None)\\n    assert isinstance(dataset, DataFrame)\\n    assert len(dataset) == 0\\n\\n\\ndef test_init_with_invalid_list():\\n    \\\"\\\"\\\"Test initialization with invalid list items.\\\"\\\"\\\"\\n    invalid_data = [\\n        {\\\"name\\\": \\\"John\\\", \\\"age\\\": 30},\\n        Data(data={\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25}),  # Mixed types should fail\\n    ]\\n    with pytest.raises(ValueError, match=\\\"List items must be either all Data objects or all dictionaries\\\"):\\n        DataFrame(invalid_data)\\n\\n\\ndef test_init_with_kwargs():\\n    \\\"\\\"\\\"Test initialization with additional kwargs.\\\"\\\"\\\"\\n    data = {\\\"name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"age\\\": [30, 25]}\\n    dataset = DataFrame(data=data, index=[\\\"a\\\", \\\"b\\\"])\\n\\n    assert isinstance(dataset, DataFrame)\\n    expected_len = 2\\n    assert len(dataset) == expected_len\\n    assert list(dataset.index) == [\\\"a\\\", \\\"b\\\"]\\n    assert dataset.loc[\\\"a\\\"][\\\"name\\\"] == \\\"John\\\"\\n    expected_age = 25\\n    assert dataset.loc[\\\"b\\\"][\\\"age\\\"] == expected_age\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_schema_dataframe.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cee2e108fbaeb724940dc06fba1a22141e7767ed490efbc78d4b2adbbe47360c\",\"content\":\"import pandas as pd\\nimport pytest\\nfrom langchain_core.documents import Document\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\n@pytest.fixture\\ndef sample_dataframe():\\n    \\\"\\\"\\\"Create a sample DataFrame for testing.\\\"\\\"\\\"\\n    return pd.DataFrame({\\\"name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"text\\\": [\\\"name is John\\\", \\\"name is Jane\\\"]})\\n\\n\\n@pytest.fixture\\ndef dataframe_with_metadata():\\n    \\\"\\\"\\\"Create a DataFrame instance with metadata for testing.\\\"\\\"\\\"\\n    data_df = pd.DataFrame({\\\"name\\\": [\\\"John\\\", \\\"Jane\\\"], \\\"text\\\": [\\\"name is John\\\", \\\"name is Jane\\\"]})\\n    return DataFrame(data_df)\\n\\n\\nclass TestDataFrameSchema:\\n    def test_to_data_list(self, sample_dataframe):\\n        \\\"\\\"\\\"Test conversion of DataFrame to list of Data objects.\\\"\\\"\\\"\\n        data_frame = DataFrame(sample_dataframe)\\n        data_list = data_frame.to_data_list()\\n        assert isinstance(data_list, list)\\n        assert all(isinstance(item, Data) for item in data_list)\\n        assert len(data_list) == len(sample_dataframe)\\n        assert data_list[0].data[\\\"name\\\"] == \\\"John\\\"\\n        assert data_list[0].data[\\\"text\\\"] == \\\"name is John\\\"\\n\\n    def test_add_row(self, sample_dataframe):\\n        \\\"\\\"\\\"Test adding a single row to DataFrame.\\\"\\\"\\\"\\n        data_frame = DataFrame(sample_dataframe)\\n        # Test adding dict\\n        new_df = data_frame.add_row({\\\"name\\\": \\\"Bob\\\", \\\"text\\\": \\\"name is Bob\\\"})\\n        assert len(new_df) == len(sample_dataframe) + 1\\n        assert new_df.iloc[-1][\\\"name\\\"] == \\\"Bob\\\"\\n        assert new_df.iloc[-1][\\\"text\\\"] == \\\"name is Bob\\\"\\n\\n        # Test adding Data object\\n        data_obj = Data(data={\\\"name\\\": \\\"Alice\\\", \\\"text\\\": \\\"name is Alice\\\"})\\n        new_df = data_frame.add_row(data_obj)\\n        assert len(new_df) == len(sample_dataframe) + 1\\n        assert new_df.iloc[-1][\\\"name\\\"] == \\\"Alice\\\"\\n        assert new_df.iloc[-1][\\\"text\\\"] == \\\"name is Alice\\\"\\n\\n    def test_add_rows(self, sample_dataframe):\\n        \\\"\\\"\\\"Test adding multiple rows to DataFrame.\\\"\\\"\\\"\\n        data_frame = DataFrame(sample_dataframe)\\n        new_rows = [{\\\"name\\\": \\\"Bob\\\", \\\"text\\\": \\\"name is Bob\\\"}, Data(data={\\\"name\\\": \\\"Alice\\\", \\\"text\\\": \\\"name is Alice\\\"})]\\n        new_df = data_frame.add_rows(new_rows)\\n        assert len(new_df) == len(sample_dataframe) + 2\\n        assert new_df.iloc[-2:][\\\"name\\\"].tolist() == [\\\"Bob\\\", \\\"Alice\\\"]\\n        assert new_df.iloc[-2:][\\\"text\\\"].tolist() == [\\\"name is Bob\\\", \\\"name is Alice\\\"]\\n\\n    def test_to_lc_document(self, dataframe_with_metadata):\\n        documents = dataframe_with_metadata.to_lc_documents()\\n        assert isinstance(documents, list)\\n        assert all(isinstance(doc, Document) for doc in documents)\\n        expected_documents_len = 2\\n        assert len(documents) == expected_documents_len\\n        assert documents[0].page_content == \\\"name is John\\\"\\n        assert documents[0].metadata == {\\\"name\\\": \\\"John\\\"}\\n        assert documents[1].page_content == \\\"name is Jane\\\"\\n\\n    def test_bool_operator(self):\\n        \\\"\\\"\\\"Test boolean operator behavior.\\\"\\\"\\\"\\n        empty_df = DataFrame()\\n        assert not bool(empty_df)\\n\\n        non_empty_df = DataFrame({\\\"name\\\": [\\\"John\\\"], \\\"text\\\": [\\\"name is John\\\"]})\\n        assert bool(non_empty_df)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_schema_message.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"21174017e5b6cb08b47e1feb5e77457b47d034b8aa19283861ca3f5701c587cb\",\"content\":\"import base64\\nimport shutil\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langchain_core.messages import AIMessage, HumanMessage\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.message import Message\\nfrom lfx.utils.constants import MESSAGE_SENDER_AI, MESSAGE_SENDER_USER\\nfrom platformdirs import user_cache_dir\\n\\n\\n@pytest.fixture\\ndef langflow_cache_dir(tmp_path):\\n    \\\"\\\"\\\"Create a temporary langflow cache directory.\\\"\\\"\\\"\\n    cache_dir = tmp_path / \\\"langflow\\\"\\n    cache_dir.mkdir(parents=True)\\n    return cache_dir\\n\\n\\n@pytest.fixture\\ndef sample_image(langflow_cache_dir):\\n    \\\"\\\"\\\"Create a sample image file for testing.\\\"\\\"\\\"\\n    # Create the test_flow directory in the cache\\n    flow_dir = langflow_cache_dir / \\\"test_flow\\\"\\n    flow_dir.mkdir(parents=True, exist_ok=True)\\n\\n    # Create the image in the flow directory\\n    image_path = flow_dir / \\\"test_image.png\\\"\\n    # Create a small black 1x1 pixel PNG file\\n    image_content = base64.b64decode(\\n        \\\"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==\\\"\\n    )\\n    image_path.write_bytes(image_content)\\n\\n    # Use platformdirs to get the cache directory\\n    real_cache_dir = Path(user_cache_dir(\\\"langflow\\\"))\\n    real_cache_dir.mkdir(parents=True, exist_ok=True)\\n    real_flow_dir = real_cache_dir / \\\"test_flow\\\"\\n    real_flow_dir.mkdir(parents=True, exist_ok=True)\\n\\n    # Copy the image to the real cache location\\n    real_image_path = real_flow_dir / \\\"test_image.png\\\"\\n    shutil.copy2(str(image_path), str(real_image_path))\\n\\n    return image_path\\n\\n\\ndef test_message_prompt_serialization():\\n    template = \\\"Hello, {name}!\\\"\\n    message = Message.from_template(template, name=\\\"Langflow\\\")\\n    assert message.text == \\\"Hello, Langflow!\\\"\\n\\n    # The base Message class in lfx doesn't support prompt serialization\\n    # This functionality is only available in the enhanced message class\\n    pytest.skip(\\\"Prompt serialization not supported in lfx base Message class\\\")\\n\\n\\ndef test_message_from_human_text():\\n    \\\"\\\"\\\"Test creating a message from human text.\\\"\\\"\\\"\\n    text = \\\"Hello, AI!\\\"\\n    message = Message(text=text, sender=MESSAGE_SENDER_USER)\\n    lc_message = message.to_lc_message()\\n\\n    assert isinstance(lc_message, HumanMessage)\\n    assert isinstance(lc_message.content, str)\\n    assert lc_message.content == text\\n\\n\\ndef test_message_from_ai_text():\\n    \\\"\\\"\\\"Test creating a message from AI text.\\\"\\\"\\\"\\n    text = \\\"Hello, Human!\\\"\\n    message = Message(text=text, sender=MESSAGE_SENDER_AI)\\n    lc_message = message.to_lc_message()\\n\\n    assert isinstance(lc_message, AIMessage)\\n    assert lc_message.content == text\\n\\n\\ndef test_message_serializes_run_id_as_string():\\n    run_id = uuid4()\\n    message = Message(text=\\\"hello\\\", run_id=run_id)\\n    dumped = message.model_dump()\\n    assert dumped[\\\"run_id\\\"] == str(run_id)\\n\\n\\ndef test_message_with_single_image(sample_image):\\n    \\\"\\\"\\\"Test creating a message with text and an image.\\\"\\\"\\\"\\n    text = \\\"Check out this image\\\"\\n    # Format the file path as expected: \\\"flow_id/filename\\\"\\n    file_path = f\\\"test_flow/{sample_image.name}\\\"\\n    message = Message(text=text, sender=MESSAGE_SENDER_USER, files=[file_path])\\n    lc_message = message.to_lc_message()\\n\\n    # The Message class now properly handles multimodal content\\n    assert isinstance(lc_message, HumanMessage)\\n    assert isinstance(lc_message.content, list)\\n    assert len(lc_message.content) == 2  # text + image\\n    assert lc_message.content[0][\\\"type\\\"] == \\\"text\\\"\\n    assert lc_message.content[0][\\\"text\\\"] == text\\n    assert lc_message.content[1][\\\"type\\\"] == \\\"image_url\\\"\\n    assert \\\"image_url\\\" in lc_message.content[1]\\n    assert \\\"url\\\" in lc_message.content[1][\\\"image_url\\\"]\\n    assert lc_message.content[1][\\\"image_url\\\"][\\\"url\\\"].startswith(\\\"data:image/\\\")\\n\\n    # Verify the message object has files\\n    assert message.files == [file_path]\\n\\n\\ndef test_message_with_multiple_images(sample_image, langflow_cache_dir):\\n    \\\"\\\"\\\"Test creating a message with multiple images.\\\"\\\"\\\"\\n    # Create a second image in the cache directory\\n    flow_dir = langflow_cache_dir / \\\"test_flow\\\"\\n    second_image = flow_dir / \\\"second_image.png\\\"\\n    shutil.copy2(str(sample_image), str(second_image))\\n\\n    # Use platformdirs for the real cache location\\n    real_cache_dir = Path(user_cache_dir(\\\"langflow\\\")) / \\\"test_flow\\\"\\n    real_cache_dir.mkdir(parents=True, exist_ok=True)\\n    real_second_image = real_cache_dir / \\\"second_image.png\\\"\\n    shutil.copy2(str(sample_image), str(real_second_image))\\n\\n    text = \\\"Multiple images\\\"\\n    message = Message(\\n        text=text,\\n        sender=MESSAGE_SENDER_USER,\\n        files=[f\\\"test_flow/{sample_image.name}\\\", f\\\"test_flow/{second_image.name}\\\"],\\n    )\\n    lc_message = message.to_lc_message()\\n\\n    # The Message class now properly handles multimodal content\\n    assert isinstance(lc_message, HumanMessage)\\n    assert isinstance(lc_message.content, list)\\n    assert len(lc_message.content) == 3  # text + 2 images\\n    assert lc_message.content[0][\\\"type\\\"] == \\\"text\\\"\\n    assert lc_message.content[0][\\\"text\\\"] == text\\n    assert lc_message.content[1][\\\"type\\\"] == \\\"image_url\\\"\\n    assert lc_message.content[2][\\\"type\\\"] == \\\"image_url\\\"\\n\\n    # Verify the message object has the files\\n    assert len(message.files) == 2\\n    assert f\\\"test_flow/{sample_image.name}\\\" in message.files\\n    assert f\\\"test_flow/{second_image.name}\\\" in message.files\\n\\n\\ndef test_message_with_invalid_image_path():\\n    \\\"\\\"\\\"Test handling of invalid image path.\\\"\\\"\\\"\\n    file_path = \\\"test_flow/non_existent.png\\\"\\n    message = Message(text=\\\"Invalid image\\\", sender=MESSAGE_SENDER_USER, files=[file_path])\\n\\n    # Missing images are skipped during conversion (no exception), leaving only the text content.\\n    lc_message = message.to_lc_message()\\n    assert isinstance(lc_message, HumanMessage)\\n    assert isinstance(lc_message.content, list)\\n    assert lc_message.content == [{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"Invalid image\\\"}]\\n\\n    # The invalid file path is still stored in the message\\n    assert message.files == [file_path]\\n\\n\\ndef test_message_without_sender():\\n    \\\"\\\"\\\"Test message creation without sender specification.\\\"\\\"\\\"\\n    # Create message without sender\\n    message = Message(text=\\\"Test message\\\")\\n    # Verify the message was created but has no sender\\n    assert message.text == \\\"Test message\\\"\\n    assert message.sender is None\\n\\n\\ndef test_message_serialization():\\n    \\\"\\\"\\\"Test message serialization to dict.\\\"\\\"\\\"\\n    # Create a timestamp with timezone\\n    message = Message(text=\\\"Test message\\\", sender=MESSAGE_SENDER_USER)\\n    timestamp_str = message.timestamp\\n    timestamp_dt = datetime.strptime(timestamp_str, \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\").replace(tzinfo=timezone.utc)\\n\\n    serialized = message.model_dump()\\n\\n    assert serialized[\\\"text\\\"] == \\\"Test message\\\"\\n    assert serialized[\\\"sender\\\"] == MESSAGE_SENDER_USER\\n    assert serialized[\\\"timestamp\\\"] == timestamp_str\\n\\n    parsed = datetime.strptime(serialized[\\\"timestamp\\\"], \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\").replace(tzinfo=timezone.utc)\\n    assert parsed.tzinfo == timezone.utc\\n    assert parsed == timestamp_dt\\n\\n\\ndef test_message_to_lc_without_sender():\\n    \\\"\\\"\\\"Test converting a message without sender to langchain message.\\\"\\\"\\\"\\n    message = Message(text=\\\"Test message\\\")\\n    # When no sender is specified, it defaults to AIMessage\\n    lc_message = message.to_lc_message()\\n    assert isinstance(lc_message, HumanMessage)\\n\\n\\ndef test_timestamp_serialization():\\n    \\\"\\\"\\\"Test timestamp serialization with different formats.\\\"\\\"\\\"\\n    # Test with timezone\\n    msg1 = Message(text=\\\"Test message\\\", sender=MESSAGE_SENDER_USER, timestamp=\\\"2023-12-25 15:30:45 UTC\\\")\\n    serialized1 = msg1.model_dump()\\n    ts1 = datetime.strptime(serialized1[\\\"timestamp\\\"], \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\").replace(tzinfo=timezone.utc)\\n    assert ts1.tzinfo == timezone.utc\\n\\n    # Test without timezone\\n    msg2 = Message(text=\\\"Test message\\\", sender=MESSAGE_SENDER_USER, timestamp=\\\"2023-12-25 15:30:45\\\")\\n    serialized2 = msg2.model_dump()\\n    ts2 = datetime.strptime(serialized2[\\\"timestamp\\\"], \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\").replace(tzinfo=timezone.utc)\\n    assert ts2.tzinfo == timezone.utc\\n\\n    # Test that both formats result in equivalent UTC times when appropriate\\n    msg_with_tz = Message(text=\\\"Test message\\\", sender=MESSAGE_SENDER_USER, timestamp=\\\"2023-12-25 15:30:45 UTC\\\")\\n    msg_without_tz = Message(text=\\\"Test message\\\", sender=MESSAGE_SENDER_USER, timestamp=\\\"2023-12-25 15:30:45\\\")\\n\\n    ser_with_tz = msg_with_tz.model_dump()[\\\"timestamp\\\"]\\n    ser_without_tz = msg_without_tz.model_dump()[\\\"timestamp\\\"]\\n\\n    parsed_with_tz = datetime.strptime(ser_with_tz, \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\").replace(tzinfo=timezone.utc)\\n    parsed_without_tz = datetime.strptime(ser_without_tz, \\\"%Y-%m-%d %H:%M:%S.%f %Z\\\").replace(tzinfo=timezone.utc)\\n\\n    assert parsed_with_tz == parsed_without_tz\\n\\n\\ndef test_message_with_image_object_direct():\\n    \\\"\\\"\\\"Test that Message properly handles Image objects after model_post_init.\\n\\n    This test verifies the fix for the bug where get_file_content_dicts() would fail\\n    when self.files contained Image objects instead of string paths.\\n    \\\"\\\"\\\"\\n    # Create a temporary image file\\n    import tempfile\\n\\n    with tempfile.NamedTemporaryFile(suffix=\\\".png\\\", delete=False) as tmp:\\n        image_content = base64.b64decode(\\n            \\\"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==\\\"\\n        )\\n        tmp.write(image_content)\\n        tmp_path = tmp.name\\n\\n    try:\\n        # Create message with absolute path\\n        message = Message(text=\\\"Test with absolute path\\\", sender=MESSAGE_SENDER_USER, files=[tmp_path])\\n\\n        # After model_post_init, files should contain Image objects\\n        from lfx.schema.image import Image\\n\\n        assert len(message.files) == 1\\n        assert isinstance(message.files[0], Image)\\n        assert message.files[0].path == tmp_path\\n\\n        # Convert to LangChain message should work\\n        lc_message = message.to_lc_message()\\n        assert isinstance(lc_message, HumanMessage)\\n        assert isinstance(lc_message.content, list)\\n        assert len(lc_message.content) == 2  # text + image\\n        assert lc_message.content[0][\\\"type\\\"] == \\\"text\\\"\\n        assert lc_message.content[1][\\\"type\\\"] == \\\"image_url\\\"\\n        assert \\\"url\\\" in lc_message.content[1][\\\"image_url\\\"]\\n    finally:\\n        # Clean up\\n        Path(tmp_path).unlink(missing_ok=True)\\n\\n\\ndef test_get_file_content_dicts_with_image_objects():\\n    \\\"\\\"\\\"Test that get_file_content_dicts() properly handles Image objects.\\n\\n    This is a regression test for the bug where get_file_paths() would fail\\n    when called with Image objects, causing no images to be included in messages.\\n    \\\"\\\"\\\"\\n    import tempfile\\n\\n    from lfx.schema.image import Image\\n\\n    # Create a temporary image\\n    with tempfile.NamedTemporaryFile(suffix=\\\".png\\\", delete=False) as tmp:\\n        image_content = base64.b64decode(\\n            \\\"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==\\\"\\n        )\\n        tmp.write(image_content)\\n        tmp_path = tmp.name\\n\\n    try:\\n        # Create a message and manually set files to Image objects\\n        # (simulating what happens after model_post_init)\\n        message = Message(text=\\\"Test\\\", sender=MESSAGE_SENDER_USER)\\n        message.files = [Image(path=tmp_path)]\\n\\n        # get_file_content_dicts should handle Image objects\\n        content_dicts = message.get_file_content_dicts()\\n\\n        assert len(content_dicts) == 1\\n        assert content_dicts[0][\\\"type\\\"] == \\\"image_url\\\"\\n        assert \\\"image_url\\\" in content_dicts[0]\\n        assert \\\"url\\\" in content_dicts[0][\\\"image_url\\\"]\\n        assert content_dicts[0][\\\"image_url\\\"][\\\"url\\\"].startswith(\\\"data:image/\\\")\\n    finally:\\n        Path(tmp_path).unlink(missing_ok=True)\\n\\n\\ndef test_get_file_content_dicts_with_string_paths():\\n    \\\"\\\"\\\"Test that get_file_content_dicts() still works with string paths.\\\"\\\"\\\"\\n    import tempfile\\n\\n    # Create a temporary image\\n    with tempfile.NamedTemporaryFile(suffix=\\\".png\\\", delete=False) as tmp:\\n        image_content = base64.b64decode(\\n            \\\"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==\\\"\\n        )\\n        tmp.write(image_content)\\n        tmp_path = tmp.name\\n\\n    try:\\n        # Create a message and manually set files to string paths\\n        # (simulating the case before model_post_init)\\n        message = Message(text=\\\"Test\\\", sender=MESSAGE_SENDER_USER)\\n        message.files = [tmp_path]\\n\\n        # get_file_content_dicts should handle string paths\\n        content_dicts = message.get_file_content_dicts()\\n\\n        assert len(content_dicts) == 1\\n        assert content_dicts[0][\\\"type\\\"] == \\\"image_url\\\"\\n        assert \\\"image_url\\\" in content_dicts[0]\\n        assert \\\"url\\\" in content_dicts[0][\\\"image_url\\\"]\\n        assert content_dicts[0][\\\"image_url\\\"][\\\"url\\\"].startswith(\\\"data:image/\\\")\\n    finally:\\n        Path(tmp_path).unlink(missing_ok=True)\\n\\n\\ndef test_should_not_inject_binary_payload_as_text_when_file_is_neither_image_nor_known_text_type():\\n    \\\"\\\"\\\"QA API-010: refuse to text-decode unknown binary files.\\n\\n    ``tweaks.ChatInput.files=['<path>']`` was injecting raw bytes as text into the\\n    HumanMessage when the file was not detected as an image.\\n\\n    Root cause: ``read_text_file`` falls back to ``latin-1`` decoding (which always\\n    succeeds), so binary content like a non-PIL-readable PNG slips through and is\\n    embedded as a long stream of garbled latin-1 characters in the message. The\\n    guard MUST refuse to text-decode files whose extension is neither a known text\\n    type nor a known image type \u2014 silently skipping is safer than feeding the LLM\\n    a binary blob.\\n    \\\"\\\"\\\"\\n    import tempfile\\n\\n    binary_content = b\\\"\\\\x00\\\\x01\\\\x02\\\\xff\\\\xfe\\\\xfd\\\" + bytes(range(256)) * 4\\n    with tempfile.NamedTemporaryFile(suffix=\\\".bin\\\", delete=False) as tmp:\\n        tmp.write(binary_content)\\n        tmp_path = tmp.name\\n\\n    try:\\n        message = Message(text=\\\"Look at this\\\", sender=MESSAGE_SENDER_USER)\\n        message.files = [tmp_path]\\n\\n        content_dicts = message.get_file_content_dicts()\\n\\n        assert content_dicts == [], (\\n            f\\\"Binary attachment with an unknown extension must be skipped, not decoded as text. \\\"\\n            f\\\"Got {len(content_dicts)} content dict(s) with text starting \\\"\\n            f\\\"{content_dicts[0].get('text', '')[:60]!r}...\\\"\\n        )\\n    finally:\\n        Path(tmp_path).unlink(missing_ok=True)\\n\\n\\ndef test_should_not_use_attachment_prefix_that_triggers_gemini_refusal_in_file_text_content():\\n    r\\\"\\\"\\\"QA GAP-M-3: avoid attachment framing that triggers Gemini refusals.\\n\\n    The ``Attachment: <filename>\\\\n<contents>`` framing triggers Gemini refusals\\n    (``\\\"I cannot process attachments in this environment\\\"``). Wrap text-file\\n    contents in a neutral header that doesn't read as a multimodal-attachment request.\\n    \\\"\\\"\\\"\\n    import tempfile\\n\\n    with tempfile.NamedTemporaryFile(suffix=\\\".txt\\\", delete=False, mode=\\\"w\\\", encoding=\\\"utf-8\\\") as tmp:\\n        tmp.write(\\\"hello world, this is the file body\\\")\\n        tmp_path = tmp.name\\n\\n    try:\\n        message = Message(text=\\\"Summarize this\\\", sender=MESSAGE_SENDER_USER)\\n        message.files = [tmp_path]\\n\\n        content_dicts = message.get_file_content_dicts()\\n\\n        assert len(content_dicts) == 1\\n        text = content_dicts[0].get(\\\"text\\\", \\\"\\\")\\n        assert \\\"hello world, this is the file body\\\" in text\\n        assert not text.startswith(\\\"Attachment:\\\"), (\\n            \\\"The 'Attachment:' prefix triggers Gemini refusals. Use a neutral header that does \\\"\\n            \\\"not look like a multimodal-attachment request to the model.\\\"\\n        )\\n    finally:\\n        Path(tmp_path).unlink(missing_ok=True)\\n\\n\\n# Clean up the cache directory after all tests\\n@pytest.fixture(autouse=True)\\ndef cleanup():\\n    yield\\n    # Clean up the real cache directory after tests\\n    cache_dir = Path(user_cache_dir(\\\"langflow\\\"))\\n    if cache_dir.exists():\\n        try:\\n            shutil.rmtree(str(cache_dir))\\n        except OSError as exc:\\n            logger.error(f\\\"Error cleaning up cache directory: {exc}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_table.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2740a0ba32f2788bc24006500bdf69e18495cd81bf75346db7d03b64c55e9669\",\"content\":\"# Generated by qodo Gen\\n\\nimport pytest\\nfrom lfx.schema.table import Column, FormatterType\\n\\n\\nclass TestColumn:\\n    # Creating a Column instance without display_name sets it to the name\\n    def test_create_column_without_display_name(self):\\n        column = Column(name=\\\"test_column\\\")\\n        assert column.display_name == \\\"test_column\\\"\\n\\n    # Creating a Column instance with valid formatter values\\n    def test_create_column_with_valid_formatter(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\", formatter=\\\"date\\\")\\n        assert column.formatter == FormatterType.date\\n\\n    # Formatter is set based on provided formatter value\\n    def test_formatter_set_based_on_value(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\", formatter=\\\"int\\\")\\n        assert column.formatter == FormatterType.number\\n\\n    # Default values for sortable and filterable are set to True\\n    def test_default_sortable_filterable(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\")\\n        assert column.sortable is True\\n        assert column.filterable is True\\n\\n    # Ensure formatter field is correctly set when provided a FormatterType\\n    def test_formatter_explicitly_set_to_enum(self):\\n        column = Column(display_name=\\\"Date Column\\\", name=\\\"date_column\\\", formatter=FormatterType.date)\\n        assert column.formatter == FormatterType.date\\n\\n    # Invalid formatter raises ValueError\\n    def test_invalid_formatter_raises_value_error(self):\\n        with pytest.raises(ValueError, match=\\\"'invalid' is not a valid FormatterType\\\"):\\n            Column(display_name=\\\"Invalid Column\\\", name=\\\"invalid_column\\\", formatter=\\\"invalid\\\")\\n\\n    # Formatter is None when not provided\\n    def test_formatter_none_when_not_provided(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\")\\n        assert column.formatter is None\\n\\n    # Description and default can be set\\n    def test_description_and_default(self):\\n        column = Column(\\n            display_name=\\\"Test Column\\\", name=\\\"test_column\\\", description=\\\"A test column\\\", default=\\\"default_value\\\"\\n        )\\n        assert column.description == \\\"A test column\\\"\\n        assert column.default == \\\"default_value\\\"\\n\\n    def test_create_with_type_instead_of_formatter(self):\\n        column = Column(display_name=\\\"Test Column\\\", name=\\\"test_column\\\", type=\\\"date\\\")\\n        assert column.formatter == FormatterType.date\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/schema/test_token_usage.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a1f48125c092425fcb0d276772472dd8738824cd79bad2c84d326d4f571f966d\",\"content\":\"\\\"\\\"\\\"Tests for lfx.schema.token_usage shared extraction functions.\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\n\\nfrom langchain_core.messages import AIMessage\\nfrom lfx.schema.properties import Usage\\nfrom lfx.schema.token_usage import (\\n    _normalize_usage_metadata,\\n    accumulate_usage,\\n    extract_usage_from_chunk,\\n    extract_usage_from_llm_result,\\n    extract_usage_from_message,\\n)\\n\\n\\nclass TestExtractUsageFromMessage:\\n    \\\"\\\"\\\"Tests for extract_usage_from_message().\\\"\\\"\\\"\\n\\n    def test_extracts_from_usage_metadata(self):\\n        message = AIMessage(content=\\\"hi\\\")\\n        message.usage_metadata = {\\\"input_tokens\\\": 15, \\\"output_tokens\\\": 25}\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 15\\n        assert result.output_tokens == 25\\n        assert result.total_tokens == 40\\n\\n    def test_extracts_from_openai_response_metadata(self):\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\n                \\\"token_usage\\\": {\\n                    \\\"prompt_tokens\\\": 50,\\n                    \\\"completion_tokens\\\": 100,\\n                    \\\"total_tokens\\\": 150,\\n                }\\n            },\\n        )\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 50\\n        assert result.output_tokens == 100\\n        assert result.total_tokens == 150\\n\\n    def test_extracts_from_anthropic_response_metadata(self):\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\n                \\\"usage\\\": {\\n                    \\\"input_tokens\\\": 200,\\n                    \\\"output_tokens\\\": 300,\\n                }\\n            },\\n        )\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 200\\n        assert result.output_tokens == 300\\n        assert result.total_tokens == 500\\n\\n    def test_returns_none_for_no_metadata(self):\\n        message = AIMessage(content=\\\"hi\\\")\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert result is None\\n\\n    def test_returns_none_for_empty_response_metadata(self):\\n        message = AIMessage(content=\\\"hi\\\", response_metadata={})\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert result is None\\n\\n    def test_returns_none_for_zero_usage_metadata(self):\\n        message = AIMessage(content=\\\"hi\\\")\\n        message.usage_metadata = {\\\"input_tokens\\\": 0, \\\"output_tokens\\\": 0}\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert result is None\\n\\n    def test_usage_metadata_takes_priority_over_response_metadata(self):\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\\"usage\\\": {\\\"input_tokens\\\": 999, \\\"output_tokens\\\": 999}},\\n        )\\n        message.usage_metadata = {\\\"input_tokens\\\": 10, \\\"output_tokens\\\": 20}\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert result is not None\\n        assert result.input_tokens == 10\\n        assert result.output_tokens == 20\\n\\n    def test_openai_takes_priority_over_anthropic(self):\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\n                \\\"token_usage\\\": {\\\"prompt_tokens\\\": 10, \\\"completion_tokens\\\": 20, \\\"total_tokens\\\": 30},\\n                \\\"usage\\\": {\\\"input_tokens\\\": 999, \\\"output_tokens\\\": 999},\\n            },\\n        )\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert result is not None\\n        assert result.input_tokens == 10\\n        assert result.output_tokens == 20\\n\\n    def test_anthropic_total_tokens_calculated_when_both_present(self):\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\n                \\\"usage\\\": {\\\"input_tokens\\\": 100, \\\"output_tokens\\\": 200},\\n            },\\n        )\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert result is not None\\n        assert result.total_tokens == 300\\n\\n    def test_anthropic_total_tokens_none_when_both_missing(self):\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\n                \\\"usage\\\": {\\\"input_tokens\\\": None, \\\"output_tokens\\\": None},\\n            },\\n        )\\n\\n        result = extract_usage_from_message(message)\\n\\n        assert result is not None\\n        assert result.total_tokens is None\\n\\n\\nclass TestExtractUsageFromLlmResult:\\n    \\\"\\\"\\\"Tests for extract_usage_from_llm_result().\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _make_llm_result(llm_output=None, generations=None):\\n        \\\"\\\"\\\"Create a duck-typed LLMResult-like object for testing.\\\"\\\"\\\"\\n        return SimpleNamespace(\\n            llm_output=llm_output,\\n            generations=generations or [],\\n        )\\n\\n    @staticmethod\\n    def _make_generation(message=None, generation_info=None):\\n        \\\"\\\"\\\"Create a duck-typed generation object.\\\"\\\"\\\"\\n        return SimpleNamespace(message=message, generation_info=generation_info)\\n\\n    def test_extracts_from_llm_output_token_usage(self):\\n        \\\"\\\"\\\"Strategy 1: llm_output['token_usage'] (legacy OpenAI path).\\\"\\\"\\\"\\n        result_obj = self._make_llm_result(\\n            llm_output={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 10, \\\"completion_tokens\\\": 20, \\\"total_tokens\\\": 30}},\\n        )\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 10\\n        assert result.output_tokens == 20\\n        assert result.total_tokens == 30\\n\\n    def test_extracts_from_usage_metadata_via_message(self):\\n        \\\"\\\"\\\"Strategy 2: generations[].message.usage_metadata via extract_usage_from_message().\\\"\\\"\\\"\\n        message = AIMessage(content=\\\"hi\\\")\\n        message.usage_metadata = {\\\"input_tokens\\\": 15, \\\"output_tokens\\\": 25}\\n        gen = self._make_generation(message=message)\\n        result_obj = self._make_llm_result(generations=[[gen]])\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 15\\n        assert result.output_tokens == 25\\n        assert result.total_tokens == 40\\n\\n    def test_extracts_from_response_metadata_token_usage(self):\\n        \\\"\\\"\\\"Strategy 2: generations[].message.response_metadata['token_usage'] via extract_usage_from_message().\\\"\\\"\\\"\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 50, \\\"completion_tokens\\\": 100, \\\"total_tokens\\\": 150}},\\n        )\\n        gen = self._make_generation(message=message)\\n        result_obj = self._make_llm_result(generations=[[gen]])\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 50\\n        assert result.output_tokens == 100\\n        assert result.total_tokens == 150\\n\\n    def test_extracts_from_response_metadata_usage_anthropic(self):\\n        \\\"\\\"\\\"Strategy 2: generations[].message.response_metadata['usage'] via extract_usage_from_message().\\\"\\\"\\\"\\n        message = AIMessage(\\n            content=\\\"hi\\\",\\n            response_metadata={\\\"usage\\\": {\\\"input_tokens\\\": 200, \\\"output_tokens\\\": 300}},\\n        )\\n        gen = self._make_generation(message=message)\\n        result_obj = self._make_llm_result(generations=[[gen]])\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 200\\n        assert result.output_tokens == 300\\n        assert result.total_tokens == 500\\n\\n    def test_extracts_from_generation_info_token_usage(self):\\n        \\\"\\\"\\\"Strategy 3: generation_info['token_usage'] fallback (older adapters).\\\"\\\"\\\"\\n        gen = self._make_generation(\\n            message=None,\\n            generation_info={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 5, \\\"completion_tokens\\\": 10, \\\"total_tokens\\\": 15}},\\n        )\\n        result_obj = self._make_llm_result(generations=[[gen]])\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 5\\n        assert result.output_tokens == 10\\n        assert result.total_tokens == 15\\n\\n    def test_extracts_from_generation_info_usage_anthropic(self):\\n        \\\"\\\"\\\"Strategy 3: generation_info['usage'] fallback (older Anthropic adapters).\\\"\\\"\\\"\\n        gen = self._make_generation(\\n            message=None,\\n            generation_info={\\\"usage\\\": {\\\"input_tokens\\\": 30, \\\"output_tokens\\\": 40}},\\n        )\\n        result_obj = self._make_llm_result(generations=[[gen]])\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 30\\n        assert result.output_tokens == 40\\n        assert result.total_tokens == 70\\n\\n    def test_returns_none_when_no_usage_data(self):\\n        result_obj = self._make_llm_result(llm_output={}, generations=[[]])\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert result is None\\n\\n    def test_returns_none_for_empty_result(self):\\n        result_obj = self._make_llm_result()\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert result is None\\n\\n    def test_llm_output_takes_priority_over_usage_metadata(self):\\n        \\\"\\\"\\\"llm_output strategy should win over message-level extraction.\\\"\\\"\\\"\\n        message = AIMessage(content=\\\"hi\\\")\\n        message.usage_metadata = {\\\"input_tokens\\\": 999, \\\"output_tokens\\\": 999}\\n        gen = self._make_generation(message=message)\\n        result_obj = self._make_llm_result(\\n            llm_output={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 10, \\\"completion_tokens\\\": 20, \\\"total_tokens\\\": 30}},\\n            generations=[[gen]],\\n        )\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert result.input_tokens == 10\\n        assert result.output_tokens == 20\\n\\n    def test_message_takes_priority_over_generation_info(self):\\n        \\\"\\\"\\\"Message-level extraction should win over generation_info fallback.\\\"\\\"\\\"\\n        message = AIMessage(content=\\\"hi\\\")\\n        message.usage_metadata = {\\\"input_tokens\\\": 10, \\\"output_tokens\\\": 20}\\n        gen = self._make_generation(\\n            message=message,\\n            generation_info={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 999, \\\"completion_tokens\\\": 999}},\\n        )\\n        result_obj = self._make_llm_result(generations=[[gen]])\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert result.input_tokens == 10\\n        assert result.output_tokens == 20\\n\\n    def test_skips_zero_llm_output_falls_through_to_message(self):\\n        \\\"\\\"\\\"Zero values in llm_output should fall through to message strategies.\\\"\\\"\\\"\\n        message = AIMessage(content=\\\"hi\\\")\\n        message.usage_metadata = {\\\"input_tokens\\\": 15, \\\"output_tokens\\\": 25}\\n        gen = self._make_generation(message=message)\\n        result_obj = self._make_llm_result(\\n            llm_output={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 0, \\\"completion_tokens\\\": 0}},\\n            generations=[[gen]],\\n        )\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        assert result.input_tokens == 15\\n        assert result.output_tokens == 25\\n\\n    def test_returns_none_for_none_response(self):\\n        \\\"\\\"\\\"Passing None should not raise and should return None.\\\"\\\"\\\"\\n        result = extract_usage_from_llm_result(None)\\n\\n        assert result is None\\n\\n    def test_total_tokens_is_recalculated_from_sum(self):\\n        \\\"\\\"\\\"total_tokens is always recalculated as input + output, not taken from provider.\\\"\\\"\\\"\\n        result_obj = self._make_llm_result(\\n            llm_output={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 10, \\\"completion_tokens\\\": 20, \\\"total_tokens\\\": 999}},\\n        )\\n\\n        result = extract_usage_from_llm_result(result_obj)\\n\\n        # The function recalculates total_tokens rather than using the provider value\\n        assert result.total_tokens == 30\\n\\n\\nclass TestExtractUsageFromChunk:\\n    \\\"\\\"\\\"Tests for extract_usage_from_chunk().\\\"\\\"\\\"\\n\\n    def test_extracts_from_usage_metadata_dict(self):\\n        chunk = SimpleNamespace(\\n            content=\\\"hi\\\",\\n            usage_metadata={\\\"input_tokens\\\": 10, \\\"output_tokens\\\": 20, \\\"total_tokens\\\": 30},\\n            response_metadata=None,\\n        )\\n\\n        result = extract_usage_from_chunk(chunk)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 10\\n        assert result.output_tokens == 20\\n        assert result.total_tokens == 30\\n\\n    def test_extracts_from_response_metadata_token_usage(self):\\n        chunk = SimpleNamespace(\\n            content=\\\"hi\\\",\\n            usage_metadata=None,\\n            response_metadata={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 50, \\\"completion_tokens\\\": 100, \\\"total_tokens\\\": 150}},\\n        )\\n\\n        result = extract_usage_from_chunk(chunk)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 50\\n        assert result.output_tokens == 100\\n        assert result.total_tokens == 150\\n\\n    def test_extracts_from_response_metadata_usage(self):\\n        chunk = SimpleNamespace(\\n            content=\\\"hi\\\",\\n            usage_metadata=None,\\n            response_metadata={\\\"usage\\\": {\\\"input_tokens\\\": 200, \\\"output_tokens\\\": 300}},\\n        )\\n\\n        result = extract_usage_from_chunk(chunk)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 200\\n        assert result.output_tokens == 300\\n        assert result.total_tokens is None\\n\\n    def test_returns_none_for_no_metadata(self):\\n        chunk = SimpleNamespace(content=\\\"hi\\\", usage_metadata=None, response_metadata=None)\\n\\n        result = extract_usage_from_chunk(chunk)\\n\\n        assert result is None\\n\\n    def test_returns_none_for_empty_usage_metadata(self):\\n        chunk = SimpleNamespace(content=\\\"hi\\\", usage_metadata={}, response_metadata=None)\\n\\n        result = extract_usage_from_chunk(chunk)\\n\\n        assert result is None\\n\\n\\nclass TestAccumulateUsage:\\n    \\\"\\\"\\\"Tests for accumulate_usage().\\\"\\\"\\\"\\n\\n    def test_first_chunk_returns_new(self):\\n        new = Usage(input_tokens=100, output_tokens=50, total_tokens=150)\\n\\n        result = accumulate_usage(None, new)\\n\\n        assert result is new\\n\\n    def test_none_new_returns_existing(self):\\n        existing = Usage(input_tokens=100, output_tokens=50, total_tokens=150)\\n\\n        result = accumulate_usage(existing, None)\\n\\n        assert result is existing\\n\\n    def test_both_none_returns_none(self):\\n        result = accumulate_usage(None, None)\\n\\n        assert result is None\\n\\n    def test_accumulates_split_anthropic_chunks(self):\\n        start = Usage(input_tokens=100, output_tokens=0, total_tokens=100)\\n        delta = Usage(input_tokens=0, output_tokens=50, total_tokens=50)\\n\\n        result = accumulate_usage(None, start)\\n        result = accumulate_usage(result, delta)\\n\\n        assert result.input_tokens == 100\\n        assert result.output_tokens == 50\\n        assert result.total_tokens == 150\\n\\n    def test_merges_cumulative_chunks_via_max(self):\\n        \\\"\\\"\\\"OpenAI sends cumulative totals \u2014 max picks the latest value.\\\"\\\"\\\"\\n        chunk1 = Usage(input_tokens=10, output_tokens=20, total_tokens=30)\\n        chunk2 = Usage(input_tokens=30, output_tokens=40, total_tokens=70)\\n\\n        result = accumulate_usage(None, chunk1)\\n        result = accumulate_usage(result, chunk2)\\n\\n        assert result.input_tokens == 30\\n        assert result.output_tokens == 40\\n        assert result.total_tokens == 70\\n\\n    def test_handles_none_values_in_new(self):\\n        existing = Usage(input_tokens=100, output_tokens=0, total_tokens=100)\\n        new = Usage(input_tokens=None, output_tokens=50, total_tokens=None)\\n\\n        result = accumulate_usage(existing, new)\\n\\n        assert result.input_tokens == 100\\n        assert result.output_tokens == 50\\n        assert result.total_tokens == 150\\n\\n\\nclass TestStreamingTokenAccumulation:\\n    \\\"\\\"\\\"Tests for streaming token accumulation across multiple chunks.\\\"\\\"\\\"\\n\\n    def test_openai_cumulative_chunks_use_max(self):\\n        # Simulate OpenAI streaming where each chunk carries cumulative totals.\\n        # max-based merge picks the latest (largest) value without double-counting.\\n        chunks = [\\n            SimpleNamespace(\\n                content=\\\"Hello\\\",\\n                usage_metadata=None,\\n                response_metadata={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 10, \\\"completion_tokens\\\": 5, \\\"total_tokens\\\": 15}},\\n            ),\\n            SimpleNamespace(\\n                content=\\\" world\\\",\\n                usage_metadata=None,\\n                response_metadata={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 10, \\\"completion_tokens\\\": 10, \\\"total_tokens\\\": 20}},\\n            ),\\n            SimpleNamespace(\\n                content=\\\"!\\\",\\n                usage_metadata=None,\\n                response_metadata={\\\"token_usage\\\": {\\\"prompt_tokens\\\": 10, \\\"completion_tokens\\\": 15, \\\"total_tokens\\\": 25}},\\n            ),\\n        ]\\n\\n        usage_data = None\\n        for chunk in chunks:\\n            chunk_usage = extract_usage_from_chunk(chunk)\\n            usage_data = accumulate_usage(usage_data, chunk_usage)\\n\\n        assert usage_data is not None\\n        assert usage_data.input_tokens == 10\\n        assert usage_data.output_tokens == 15\\n        assert usage_data.total_tokens == 25\\n\\n    def test_accumulates_anthropic_format_chunks(self):\\n        # Simulate Anthropic streaming where input comes first, then output\\n        start_chunk = SimpleNamespace(\\n            content=\\\"\\\", usage_metadata=None, response_metadata={\\\"usage\\\": {\\\"input_tokens\\\": 100, \\\"output_tokens\\\": 0}}\\n        )\\n        delta_chunk = SimpleNamespace(\\n            content=\\\"response text\\\",\\n            usage_metadata=None,\\n            response_metadata={\\\"usage\\\": {\\\"input_tokens\\\": 0, \\\"output_tokens\\\": 50}},\\n        )\\n\\n        usage_data = None\\n        for chunk in [start_chunk, delta_chunk]:\\n            chunk_usage = extract_usage_from_chunk(chunk)\\n            usage_data = accumulate_usage(usage_data, chunk_usage)\\n\\n        assert usage_data is not None\\n        assert usage_data.input_tokens == 100\\n        assert usage_data.output_tokens == 50\\n\\n    def test_usage_metadata_chunks_use_max(self):\\n        # Simulate standard LangChain usage_metadata format with cumulative values.\\n        # max-based merge picks the highest value per field.\\n        chunks = [\\n            SimpleNamespace(\\n                content=\\\"part1\\\",\\n                usage_metadata={\\\"input_tokens\\\": 5, \\\"output_tokens\\\": 3, \\\"total_tokens\\\": 8},\\n                response_metadata=None,\\n            ),\\n            SimpleNamespace(\\n                content=\\\"part2\\\",\\n                usage_metadata={\\\"input_tokens\\\": 5, \\\"output_tokens\\\": 7, \\\"total_tokens\\\": 12},\\n                response_metadata=None,\\n            ),\\n        ]\\n\\n        usage_data = None\\n        for chunk in chunks:\\n            chunk_usage = extract_usage_from_chunk(chunk)\\n            usage_data = accumulate_usage(usage_data, chunk_usage)\\n\\n        assert usage_data is not None\\n        assert usage_data.input_tokens == 5\\n        assert usage_data.output_tokens == 7\\n        assert usage_data.total_tokens == 12\\n\\n    def test_skips_chunks_without_usage_data(self):\\n        # Intermediate streaming chunks typically have no usage \u2014 only the last chunk does\\n        chunks = [\\n            SimpleNamespace(content=\\\"token1\\\", usage_metadata=None, response_metadata=None),\\n            SimpleNamespace(content=\\\"token2\\\", usage_metadata=None, response_metadata=None),\\n            SimpleNamespace(\\n                content=\\\"token3\\\",\\n                usage_metadata={\\\"input_tokens\\\": 20, \\\"output_tokens\\\": 30, \\\"total_tokens\\\": 50},\\n                response_metadata=None,\\n            ),\\n        ]\\n\\n        usage_data = None\\n        for chunk in chunks:\\n            chunk_usage = extract_usage_from_chunk(chunk)\\n            usage_data = accumulate_usage(usage_data, chunk_usage)\\n\\n        assert usage_data is not None\\n        assert usage_data.input_tokens == 20\\n        assert usage_data.output_tokens == 30\\n        assert usage_data.total_tokens == 50\\n\\n    def test_all_chunks_without_usage_returns_none(self):\\n        # If no chunk carries usage, result should be None\\n        chunks = [\\n            SimpleNamespace(content=\\\"a\\\", usage_metadata=None, response_metadata=None),\\n            SimpleNamespace(content=\\\"b\\\", usage_metadata=None, response_metadata=None),\\n        ]\\n\\n        usage_data = None\\n        for chunk in chunks:\\n            chunk_usage = extract_usage_from_chunk(chunk)\\n            usage_data = accumulate_usage(usage_data, chunk_usage)\\n\\n        assert usage_data is None\\n\\n\\nclass TestNormalizeUsageMetadata:\\n    \\\"\\\"\\\"Tests for _normalize_usage_metadata().\\\"\\\"\\\"\\n\\n    def test_from_dict(self):\\n        um = {\\\"input_tokens\\\": 10, \\\"output_tokens\\\": 20, \\\"total_tokens\\\": 30}\\n\\n        result = _normalize_usage_metadata(um)\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 10\\n        assert result.output_tokens == 20\\n        assert result.total_tokens == 30\\n\\n    def test_from_object(self):\\n        class UsageMeta:\\n            input_tokens = 15\\n            output_tokens = 25\\n            total_tokens = 40\\n\\n        result = _normalize_usage_metadata(UsageMeta())\\n\\n        assert isinstance(result, Usage)\\n        assert result.input_tokens == 15\\n        assert result.output_tokens == 25\\n        assert result.total_tokens == 40\\n\\n    def test_handles_missing_attrs_on_object(self):\\n        class Partial:\\n            input_tokens = 10\\n\\n        result = _normalize_usage_metadata(Partial())\\n\\n        assert result.input_tokens == 10\\n        assert result.output_tokens is None\\n        assert result.total_tokens is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/adapter_test_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7cd0a8147da81d1409fa999563087651dfd481ff86467ac3ee09ea87cf4ad4b7\",\"content\":\"\\\"\\\"\\\"Shared test helpers for adapter registry tests.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom lfx.services.adapters import registry as adapter_registry_mod\\nfrom lfx.services.adapters.deployment.base import BaseDeploymentService\\nfrom lfx.services.adapters.schema import AdapterType\\n\\n\\nclass DeploymentAdapterStub(BaseDeploymentService):\\n    \\\"\\\"\\\"Minimal stub subclassing BaseDeploymentService for adapter registry tests.\\\"\\\"\\\"\\n\\n    name = \\\"stub_deployment\\\"\\n\\n    async def create(self, **kw): ...\\n    async def list_types(self, **kw): ...\\n    async def list_llms(self, **kw): ...\\n    async def list(self, **kw): ...\\n    async def get(self, **kw): ...\\n    async def update(self, **kw): ...\\n    async def redeploy(self, **kw): ...\\n    async def duplicate(self, **kw): ...\\n    async def delete(self, **kw): ...\\n    async def get_status(self, **kw): ...\\n    async def create_execution(self, **kw): ...\\n    async def get_execution(self, **kw): ...\\n    async def list_configs(self, **kw): ...\\n    async def list_snapshots(self, **kw): ...\\n    async def verify_credentials(self, **kw): ...\\n    async def teardown(self): ...\\n\\n\\ndef make_deployment_adapter_registry():\\n    \\\"\\\"\\\"Create a deployment adapter registry with convention-derived parameters.\\\"\\\"\\\"\\n    return adapter_registry_mod.get_adapter_registry(adapter_type=AdapterType.DEPLOYMENT)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/authorization/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/authorization/test_default_authorization_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"062ce521d64774c070dec375b91d781918ff0581f749a996e7d4c59e65f7de8e\",\"content\":\"\\\"\\\"\\\"Tests for the default LFX AuthorizationService (no-op allow-all implementation).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import FrozenInstanceError\\nfrom datetime import datetime, timezone\\nfrom unittest.mock import AsyncMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom lfx.services.authorization import DirectoryMembershipIngestResult\\nfrom lfx.services.authorization.base import (\\n    AuthorizationMutation,\\n    AuthorizationMutationKind,\\n    AuthorizationMutationRejected,\\n    BaseAuthorizationService,\\n    DirectoryMembershipSnapshot,\\n)\\nfrom lfx.services.authorization.service import AuthorizationService\\n\\n\\n@pytest.fixture\\ndef service() -> AuthorizationService:\\n    \\\"\\\"\\\"Build a fresh default authorization service.\\\"\\\"\\\"\\n    return AuthorizationService()\\n\\n\\ndef test_service_is_ready_and_named(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"The default service initializes ready and uses the canonical service name.\\\"\\\"\\\"\\n    assert service.ready is True\\n    assert service.name == \\\"authorization_service\\\"\\n\\n\\ndef test_service_subclasses_base(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"The default implementation conforms to the BaseAuthorizationService contract.\\\"\\\"\\\"\\n    assert isinstance(service, BaseAuthorizationService)\\n\\n\\ndef test_mutation_rejection_exposes_only_public_detail() -> None:\\n    \\\"\\\"\\\"Plugins can reject unsafe mutations with an API-safe typed error.\\\"\\\"\\\"\\n    rejection = AuthorizationMutationRejected(\\\"At least one recovery administrator is required.\\\")\\n    assert rejection.public_detail == \\\"At least one recovery administrator is required.\\\"\\n    assert str(rejection) == rejection.public_detail\\n\\n\\nasync def test_is_enabled_returns_false(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"The LFX default reports authorization as disabled.\\\"\\\"\\\"\\n    assert await service.is_enabled() is False\\n\\n\\nasync def test_enforce_returns_true_for_any_input(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"Default enforce permits every request regardless of arguments.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    assert (\\n        await service.enforce(\\n            user_id=user_id,\\n            domain=\\\"*\\\",\\n            obj=\\\"flow:xyz\\\",\\n            act=\\\"write\\\",\\n        )\\n        is True\\n    )\\n    assert (\\n        await service.enforce(\\n            user_id=user_id,\\n            domain=\\\"other\\\",\\n            obj=\\\"project:1\\\",\\n            act=\\\"delete\\\",\\n            context={\\\"is_superuser\\\": False},\\n        )\\n        is True\\n    )\\n\\n\\nasync def test_batch_enforce_returns_all_true_for_any_length(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"batch_enforce returns a True list matching the request count, for any length.\\\"\\\"\\\"\\n    user_id = uuid4()\\n\\n    empty = await service.batch_enforce(user_id=user_id, domain=\\\"*\\\", requests=[])\\n    assert empty == []\\n\\n    single = await service.batch_enforce(user_id=user_id, domain=\\\"*\\\", requests=[(\\\"flow:a\\\", \\\"read\\\")])\\n    assert single == [True]\\n\\n    requests = [(f\\\"flow:{i}\\\", \\\"read\\\") for i in range(5)]\\n    five = await service.batch_enforce(user_id=user_id, domain=\\\"*\\\", requests=requests)\\n    assert five == [True, True, True, True, True]\\n\\n\\nasync def test_get_allowed_actions_returns_full_list(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"get_allowed_actions returns every requested action when default service is used.\\\"\\\"\\\"\\n    actions = [\\\"read\\\", \\\"write\\\", \\\"delete\\\", \\\"execute\\\"]\\n    result = await service.get_allowed_actions(\\n        user_id=uuid4(),\\n        domain=\\\"*\\\",\\n        obj=\\\"flow:abc\\\",\\n        actions=actions,\\n    )\\n    assert result == actions\\n\\n\\nasync def test_get_effective_permissions_default_returns_all_actions_per_resource(\\n    service: AuthorizationService,\\n) -> None:\\n    \\\"\\\"\\\"Default impl returns every requested action for every resource (no enforcement).\\\"\\\"\\\"\\n    rids = [uuid4(), uuid4()]\\n    actions = [\\\"read\\\", \\\"write\\\"]\\n    result = await service.get_effective_permissions(\\n        user_id=uuid4(),\\n        resource_type=\\\"flow\\\",\\n        resource_ids=rids,\\n        actions=actions,\\n        domain=\\\"*\\\",\\n    )\\n    assert result == {rids[0]: actions, rids[1]: actions}\\n\\n\\nasync def test_get_effective_permissions_validates_batch_enforce_length(\\n    service: AuthorizationService,\\n) -> None:\\n    \\\"\\\"\\\"A plugin returning a wrong-sized batch must raise ValueError, not silently slice.\\n\\n    Without this guard, a too-short ``flat`` produces empty lists for later\\n    resources (out-of-bounds slice returns ``[]``) and a too-long ``flat``\\n    drops the tail \u2014 both yielding incorrect per-resource permissions.\\n    \\\"\\\"\\\"\\n\\n    async def bad_batch_enforce(**_kwargs):\\n        # Caller will pass 2 resources x 2 actions = 4 requests; return only 3.\\n        return [True, True, True]\\n\\n    service.batch_enforce = bad_batch_enforce  # type: ignore[assignment]\\n\\n    with pytest.raises(ValueError, match=\\\"returned 3 results for 4 requests\\\"):\\n        await service.get_effective_permissions(\\n            user_id=uuid4(),\\n            resource_type=\\\"flow\\\",\\n            resource_ids=[uuid4(), uuid4()],\\n            actions=[\\\"read\\\", \\\"write\\\"],\\n            domain=\\\"*\\\",\\n        )\\n\\n\\nasync def test_invalidate_user_is_noop(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"Cache invalidation hooks are no-ops on the default LFX implementation.\\\"\\\"\\\"\\n    assert await service.invalidate_user(uuid4()) is None\\n\\n\\nasync def test_invalidate_role_is_noop(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"Cache invalidation hooks are no-ops on the default LFX implementation.\\\"\\\"\\\"\\n    assert await service.invalidate_role(uuid4()) is None\\n\\n\\nasync def test_invalidate_all_is_noop(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"Cache invalidation hooks are no-ops on the default LFX implementation.\\\"\\\"\\\"\\n    assert await service.invalidate_all() is None\\n\\n\\nasync def test_identity_and_directory_contracts_are_default_noops(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"OSS stays pass-through while exposing stable plugin lifecycle value objects.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    mutation = AuthorizationMutation(\\n        kind=AuthorizationMutationKind.USER_DISABLED,\\n        entity_id=user_id,\\n        affected_user_ids=(user_id,),\\n    )\\n    snapshot = DirectoryMembershipSnapshot(\\n        provider_id=\\\"directory-1\\\",\\n        source=\\\"scim\\\",\\n        observed_at=datetime.now(timezone.utc),\\n        user_id=user_id,\\n        provider_user_id=\\\"provider-user-1\\\",\\n        memberships=(\\\"engineering\\\", \\\"reviewers\\\"),\\n    )\\n    session = object()\\n\\n    assert (\\n        await service.acquire_identity_mutation_lock(\\n            session=session,\\n            kind=AuthorizationMutationKind.ROLE_ASSIGNMENT_CREATED,\\n            affected_user_ids=(user_id,),\\n        )\\n        is None\\n    )\\n    assert await service.validate_identity_mutation(session=session, mutation=mutation) is None\\n    assert await service.stage_identity_mutation(session=session, event=mutation) is None\\n    assert await service.identity_mutation_committed(mutation) is None\\n    result = await service.ingest_directory_membership_snapshot(session=session, snapshot=snapshot)\\n    assert result == DirectoryMembershipIngestResult()\\n    assert result.changed is False\\n    assert result.added == 0\\n    assert result.removed == 0\\n    assert not hasattr(result, \\\"__dict__\\\")\\n    with pytest.raises(FrozenInstanceError):\\n        result.changed = True  # type: ignore[misc]\\n\\n\\nasync def test_external_groups_claim_path_adapts_legacy_claim_selector(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"A legacy top-level claim selector remains a one-segment claim path.\\\"\\\"\\\"\\n    service.external_groups_claim = AsyncMock(return_value=\\\"groups\\\")  # type: ignore[method-assign]\\n\\n    assert await service.external_groups_claim_path(provider_id=\\\"directory-1\\\", issuer=None) == (\\\"groups\\\",)\\n\\n\\nasync def test_external_groups_claim_path_preserves_plugin_opt_out(service: AuthorizationService) -> None:\\n    \\\"\\\"\\\"The default no-op service does not opt into external group reconciliation.\\\"\\\"\\\"\\n    assert await service.external_groups_claim_path(provider_id=\\\"directory-1\\\", issuer=None) is None\\n\\n\\nasync def test_incomplete_directory_membership_snapshots_require_explicit_opt_in(\\n    service: AuthorizationService,\\n) -> None:\\n    \\\"\\\"\\\"Legacy plugins retain the complete-only ingestion contract by default.\\\"\\\"\\\"\\n    assert await service.supports_incomplete_directory_membership_snapshots() is False\\n\\n\\nasync def test_identity_committed_adapts_to_legacy_invalidation_hooks(\\n    service: AuthorizationService,\\n) -> None:\\n    \\\"\\\"\\\"Older plugins receive targeted invalidations without implementing the new hook.\\\"\\\"\\\"\\n    user_id = uuid4()\\n    role_id = uuid4()\\n    service.invalidate_user = AsyncMock()  # type: ignore[method-assign]\\n    service.invalidate_role = AsyncMock()  # type: ignore[method-assign]\\n    service.invalidate_all = AsyncMock()  # type: ignore[method-assign]\\n\\n    await service.identity_mutation_committed(\\n        AuthorizationMutation(\\n            kind=AuthorizationMutationKind.ROLE_ASSIGNMENT_CREATED,\\n            entity_id=uuid4(),\\n            affected_user_ids=(user_id,),\\n            role_id=role_id,\\n        )\\n    )\\n    service.invalidate_user.assert_awaited_once_with(user_id)\\n\\n    await service.identity_mutation_committed(\\n        AuthorizationMutation(\\n            kind=AuthorizationMutationKind.ROLE_UPDATED,\\n            entity_id=role_id,\\n            role_id=role_id,\\n        )\\n    )\\n    service.invalidate_role.assert_awaited_once_with(role_id)\\n\\n    await service.identity_mutation_committed(\\n        AuthorizationMutation(\\n            kind=AuthorizationMutationKind.TEAM_DELETED,\\n            entity_id=uuid4(),\\n        )\\n    )\\n    service.invalidate_all.assert_awaited_once_with()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/catalog_policy/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"41936cc8d363ada43e0808d5eb8a00bd9eaab8a2b569ed37dea363ba9041f1e3\",\"content\":\"\\\"\\\"\\\"Catalog-policy service tests.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/catalog_policy/test_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f9b9ebc07ac96de9e3e5c702a2044bfb2383a83692f0d46c470d1037cfc010d5\",\"content\":\"\\\"\\\"\\\"Catalog-policy contract tests.\\\"\\\"\\\"\\n\\nfrom dataclasses import FrozenInstanceError\\n\\nimport pytest\\nfrom lfx.services.catalog_policy import BaseCatalogPolicyService, CatalogPolicyService, CatalogPolicySnapshot\\nfrom lfx.services.schema import ServiceType\\n\\n\\ndef test_empty_default_is_fail_open_for_single_and_batch_decisions():\\n    service = CatalogPolicyService()\\n\\n    assert service.ready is True\\n    assert service.external_policy_snapshot is None\\n    assert service.enabled is False\\n    assert service.is_component_blocked(\\\"OpenAIModel\\\") is False\\n    assert service.is_template_blocked(\\\"starter-template\\\") is False\\n    assert service.is_component_allowed(\\\"OpenAIModel\\\") is True\\n    assert service.is_template_allowed(\\\"starter-template\\\") is True\\n    assert service.blocked_component_keys([\\\"OpenAIModel\\\", \\\"Agent\\\"]) == frozenset()\\n    assert service.blocked_template_keys([\\\"starter-template\\\"]) == frozenset()\\n\\n\\ndef test_snapshot_is_immutable_and_supports_batch_decisions():\\n    snapshot = CatalogPolicySnapshot(\\n        blocked_component_keys=frozenset({\\\"OpenAIModel\\\", \\\"Agent\\\"}),\\n        blocked_template_keys=frozenset({\\\"starter-template\\\"}),\\n    )\\n\\n    assert snapshot.enabled is True\\n    assert snapshot.is_component_blocked(\\\"Agent\\\") is True\\n    assert snapshot.is_component_blocked(\\\"agent\\\") is False\\n    assert snapshot.is_template_blocked(\\\"starter-template\\\") is True\\n    assert snapshot.blocked_components([\\\"Agent\\\", \\\"Agent\\\", \\\"Other\\\"]) == frozenset({\\\"Agent\\\"})\\n    assert snapshot.blocked_templates([\\\"other\\\", \\\"starter-template\\\"]) == frozenset({\\\"starter-template\\\"})\\n    with pytest.raises(FrozenInstanceError):\\n        snapshot.blocked_component_keys = frozenset()  # type: ignore[misc]\\n\\n\\ndef test_dependency_installs_stable_fail_open_fallback_for_broken_plugin(monkeypatch):\\n    from lfx.services import deps\\n    from lfx.services import manager as manager_module\\n    from lfx.services.manager import ServiceManager\\n\\n    class BrokenCatalogPolicyService(BaseCatalogPolicyService):\\n        attempts = 0\\n\\n        def __init__(self) -> None:\\n            type(self).attempts += 1\\n            message = \\\"broken catalog policy plugin\\\"\\n            raise RuntimeError(message)\\n\\n        @property\\n        def snapshot(self) -> CatalogPolicySnapshot:\\n            return CatalogPolicySnapshot()\\n\\n    manager = ServiceManager()\\n    manager._plugins_discovered = True\\n    manager.register_service_class(\\n        ServiceType.CATALOG_POLICY_SERVICE,\\n        BrokenCatalogPolicyService,\\n        override=True,\\n    )\\n    monkeypatch.setattr(manager_module, \\\"_service_manager\\\", manager)\\n    monkeypatch.setattr(deps, \\\"_catalog_policy_fallback\\\", None)\\n\\n    first = deps.get_catalog_policy_service()\\n    second = deps.get_catalog_policy_service()\\n\\n    assert first is second\\n    assert isinstance(first, CatalogPolicyService)\\n    assert first.is_component_allowed(\\\"anything\\\") is True\\n    assert first.is_template_allowed(\\\"anything\\\") is True\\n    assert manager.services[ServiceType.CATALOG_POLICY_SERVICE] is first\\n    assert BrokenCatalogPolicyService.attempts == 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/conftest.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a17330c5020a0b5b61352db80ef4c7bfb8681a6906f2743588cadaa1c0b750c9\",\"content\":\"\\\"\\\"\\\"Shared fixtures for service tests.\\\"\\\"\\\"\\n\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\nfrom lfx.services.adapters import registry as adapter_registry_mod\\nfrom lfx.services.base import Service\\nfrom lfx.services.manager import ServiceManager\\nfrom lfx.services.schema import ServiceType\\n\\n\\n@pytest.fixture\\nasync def clean_adapter_globals():\\n    \\\"\\\"\\\"Ensure global adapter registry state is isolated per test.\\\"\\\"\\\"\\n    await adapter_registry_mod._reset_registries()\\n    yield\\n    await adapter_registry_mod._reset_registries()\\n\\n\\nclass MockSessionService(Service):\\n    \\\"\\\"\\\"Mock session service for testing.\\n\\n    Provides a minimal session service implementation that satisfies\\n    the dependency requirements of services like LocalStorageService.\\n    \\\"\\\"\\\"\\n\\n    name = \\\"session_service\\\"\\n\\n    def __init__(self):\\n        super().__init__()\\n        self.set_ready()\\n\\n    async def teardown(self) -> None:\\n        pass\\n\\n\\n@pytest.fixture\\ndef mock_session_service():\\n    \\\"\\\"\\\"Create a mock session service using MagicMock.\\\"\\\"\\\"\\n    return MagicMock()\\n\\n\\n@pytest.fixture\\ndef mock_settings_service(tmp_path):\\n    \\\"\\\"\\\"Create a mock settings service with tmp_path as config_dir.\\\"\\\"\\\"\\n    mock = MagicMock()\\n    mock.settings.config_dir = str(tmp_path)\\n    return mock\\n\\n\\n@pytest.fixture\\ndef service_manager_with_session():\\n    \\\"\\\"\\\"Create a ServiceManager with MockSessionService registered.\\n\\n    This fixture is useful for tests that need to create services\\n    via the ServiceManager that depend on session_service.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    manager = ServiceManager()\\n    manager.register_service_class(ServiceType.SESSION_SERVICE, MockSessionService, override=True)\\n    yield manager\\n    asyncio.run(manager.teardown())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/deployment/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"99d6bae7f64757b00e2bfdb0fe426b0787be9e01aa1a8e77c3acf2d21caa30ec\",\"content\":\"\\\"\\\"\\\"Deployment service schema/protocol unit tests package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/deployment/test_deployment_exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"60f9d6ce3d4953a8207ee3f2f1390dc49d9a9528a5bcae8c99d1dde2c01b21da\",\"content\":\"\\\"\\\"\\\"Tests for deployment exception hierarchy, metadata, and service instantiation.\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.services.adapters.deployment import (\\n    BaseDeploymentService,\\n    DeploymentError,\\n    DeploymentNotConfiguredError,\\n    DeploymentService,\\n    DeploymentServiceError,\\n)\\nfrom lfx.services.adapters.deployment.exceptions import (\\n    AuthenticationError,\\n    AuthorizationError,\\n    AuthSchemeError,\\n    CredentialResolutionError,\\n    DeploymentNotFoundError,\\n    DeploymentSupportError,\\n    DeploymentTimeoutError,\\n    InvalidContentError,\\n    InvalidDeploymentOperationError,\\n    InvalidDeploymentTypeError,\\n    OperationNotSupportedError,\\n    RateLimitError,\\n    ResourceConflictError,\\n    ResourceNotFoundError,\\n    ServiceUnavailableError,\\n    http_status_for_deployment_error,\\n    raise_as_deployment_error,\\n)\\nfrom lfx.services.interfaces import DeploymentServiceProtocol\\n\\n\\ndef test_exception_hierarchy_is_preserved() -> None:\\n    # DeploymentServiceError is the common root\\n    assert issubclass(DeploymentError, DeploymentServiceError)\\n    assert issubclass(AuthenticationError, DeploymentServiceError)\\n    assert issubclass(AuthorizationError, DeploymentServiceError)\\n\\n    # AuthenticationError is a sibling of DeploymentError, NOT a child\\n    assert not issubclass(AuthenticationError, DeploymentError)\\n    assert not issubclass(AuthorizationError, DeploymentError)\\n    assert not issubclass(DeploymentError, AuthenticationError)\\n    assert not issubclass(DeploymentError, AuthorizationError)\\n\\n    # Auth subtypes\\n    assert issubclass(CredentialResolutionError, AuthenticationError)\\n    assert issubclass(AuthSchemeError, AuthenticationError)\\n\\n    # Deployment operation subtypes\\n    assert issubclass(ResourceConflictError, DeploymentError)\\n    assert issubclass(InvalidContentError, DeploymentError)\\n    assert issubclass(InvalidDeploymentOperationError, DeploymentError)\\n    assert issubclass(ResourceNotFoundError, DeploymentError)\\n    assert issubclass(DeploymentNotFoundError, ResourceNotFoundError)\\n    assert issubclass(DeploymentNotConfiguredError, DeploymentError)\\n    assert issubclass(OperationNotSupportedError, DeploymentError)\\n\\n\\ndef test_exception_error_codes_are_set() -> None:\\n    assert AuthorizationError(\\\"forbidden\\\", error_code=\\\"authorization_error\\\").error_code == \\\"authorization_error\\\"\\n    assert CredentialResolutionError().error_code == \\\"credentials_resolution_error\\\"\\n    assert ResourceConflictError().error_code == \\\"deployment_conflict\\\"\\n    assert RateLimitError().error_code == \\\"deployment_rate_limited\\\"\\n    assert DeploymentTimeoutError().error_code == \\\"deployment_timeout\\\"\\n    assert ServiceUnavailableError().error_code == \\\"deployment_provider_unavailable\\\"\\n    assert DeploymentSupportError().error_code == \\\"unsupported_deployment_type\\\"\\n    assert ResourceNotFoundError().error_code == \\\"resource_not_found\\\"\\n    assert InvalidDeploymentTypeError().error_code == \\\"invalid_deployment_type\\\"\\n    assert InvalidContentError().error_code == \\\"unprocessable_content_error\\\"\\n    assert InvalidDeploymentOperationError().error_code == \\\"invalid_deployment_operation\\\"\\n    assert AuthSchemeError().error_code == \\\"unsupported_auth_type\\\"\\n    assert DeploymentNotConfiguredError().error_code == \\\"deployment_not_configured\\\"\\n    assert OperationNotSupportedError().error_code == \\\"operation_not_supported\\\"\\n\\n\\ndef test_deployment_conflict_error_resource_is_optional_and_normalized() -> None:\\n    err = ResourceConflictError(resource=\\\" TOOL \\\")\\n    assert err.resource == \\\"tool\\\"\\n    assert ResourceConflictError().resource is None\\n\\n\\ndef test_deployment_type_exceptions_have_distinct_default_messages() -> None:\\n    assert str(DeploymentSupportError()) == \\\"Deployment type is unsupported by this adapter\\\"\\n    assert str(InvalidDeploymentTypeError()) == \\\"Deployment type is malformed or unknown\\\"\\n\\n\\ndef test_deployment_not_found_includes_context_when_id_is_provided() -> None:\\n    err = DeploymentNotFoundError(deployment_id=\\\"dep_1\\\")\\n    assert str(err) == \\\"Deployment not found: dep_1\\\"\\n    assert err.error_code == \\\"deployment_not_found\\\"\\n    assert err.deployment_id == \\\"dep_1\\\"\\n\\n\\ndef test_deployment_not_found_default_message() -> None:\\n    err = DeploymentNotFoundError()\\n    assert str(err) == \\\"Deployment not found\\\"\\n    assert err.deployment_id is None\\n\\n\\ndef test_resource_not_found_defaults() -> None:\\n    err = ResourceNotFoundError(resource_id=\\\"r1\\\")\\n    assert str(err) == \\\"Resource not found: r1\\\"\\n    assert err.resource_id == \\\"r1\\\"\\n    assert err.error_code == \\\"resource_not_found\\\"\\n\\n\\ndef test_deployment_not_found_preserves_deployment_id_with_custom_message() -> None:\\n    err = DeploymentNotFoundError(message=\\\"Custom error\\\", deployment_id=\\\"dep_1\\\")\\n    assert str(err) == \\\"Custom error\\\"\\n    assert err.deployment_id == \\\"dep_1\\\"\\n\\n\\ndef test_base_error_supports_cause_chaining() -> None:\\n    root = ValueError(\\\"boom\\\")\\n    err = DeploymentError(\\\"failed\\\", error_code=\\\"deployment_error\\\", cause=root)\\n    assert err.cause is root\\n    assert err.__cause__ is root\\n\\n\\ndef test_base_error_requires_error_code() -> None:\\n    err = DeploymentError(\\\"failed\\\", error_code=\\\"test_code\\\")\\n    assert err.error_code == \\\"test_code\\\"\\n\\n\\ndef test_deployment_service_is_instantiable() -> None:\\n    svc = DeploymentService()\\n    assert svc.name == \\\"deployment_service\\\"\\n\\n\\ndef test_deployment_service_satisfies_protocol() -> None:\\n    svc = DeploymentService()\\n    assert isinstance(svc, DeploymentServiceProtocol)\\n\\n\\ndef test_deployment_service_is_base_deployment_service() -> None:\\n    assert issubclass(DeploymentService, BaseDeploymentService)\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"method_name\\\", \\\"kwargs\\\"),\\n    [\\n        (\\\"create\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"payload\\\": None, \\\"db\\\": None}),\\n        (\\\"list_types\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"db\\\": None}),\\n        (\\\"list\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"db\\\": None}),\\n        (\\\"list_configs\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"db\\\": None}),\\n        (\\\"list_snapshots\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"db\\\": None}),\\n        (\\\"get\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"deployment_id\\\": \\\"d1\\\", \\\"db\\\": None}),\\n        (\\\"update\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"deployment_id\\\": \\\"d1\\\", \\\"payload\\\": None, \\\"db\\\": None}),\\n        (\\\"redeploy\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"deployment_id\\\": \\\"d1\\\", \\\"db\\\": None}),\\n        (\\\"duplicate\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"deployment_id\\\": \\\"d1\\\", \\\"db\\\": None}),\\n        (\\\"delete\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"deployment_id\\\": \\\"d1\\\", \\\"db\\\": None}),\\n        (\\\"get_status\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"deployment_id\\\": \\\"d1\\\", \\\"db\\\": None}),\\n        (\\\"create_execution\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"payload\\\": None, \\\"db\\\": None}),\\n        (\\\"get_execution\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"execution_id\\\": \\\"e1\\\", \\\"db\\\": None}),\\n        (\\\"verify_credentials\\\", {\\\"user_id\\\": \\\"u1\\\", \\\"payload\\\": None}),\\n    ],\\n)\\nasync def test_deployment_service_stub_methods_raise(method_name: str, kwargs: dict) -> None:\\n    svc = DeploymentService()\\n    with pytest.raises(DeploymentNotConfiguredError, match=\\\"requires a concrete deployment adapter\\\"):\\n        await getattr(svc, method_name)(**kwargs)\\n\\n\\nasync def test_deployment_service_teardown_is_noop() -> None:\\n    svc = DeploymentService()\\n    await svc.teardown()\\n\\n\\ndef test_deployment_not_configured_includes_method_name() -> None:\\n    err = DeploymentNotConfiguredError(method=\\\"create\\\")\\n    assert \\\"DeploymentService.create()\\\" in str(err)\\n    assert err.error_code == \\\"deployment_not_configured\\\"\\n\\n\\ndef test_deployment_not_configured_default_message() -> None:\\n    err = DeploymentNotConfiguredError()\\n    assert \\\"No deployment adapter is registered\\\" in str(err)\\n\\n\\ndef test_auth_errors_not_caught_by_deployment_error() -> None:\\n    \\\"\\\"\\\"Ensure except DeploymentError does NOT catch auth failures.\\\"\\\"\\\"\\n\\n    def raise_auth_error() -> None:\\n        try:\\n            raise CredentialResolutionError\\n        except DeploymentError:\\n            pytest.fail(\\\"DeploymentError should not catch AuthenticationError\\\")\\n\\n    with pytest.raises(AuthenticationError):\\n        raise_auth_error()\\n\\n\\ndef test_authorization_errors_not_caught_by_deployment_error() -> None:\\n    \\\"\\\"\\\"Ensure except DeploymentError does NOT catch authorization failures.\\\"\\\"\\\"\\n\\n    def raise_authorization_error() -> None:\\n        error_message = \\\"forbidden\\\"\\n        try:\\n            raise AuthorizationError(error_message, error_code=\\\"authorization_error\\\")\\n        except DeploymentError:\\n            pytest.fail(\\\"DeploymentError should not catch AuthorizationError\\\")\\n\\n    with pytest.raises(AuthorizationError):\\n        raise_authorization_error()\\n\\n\\ndef test_deployment_service_error_catches_both_hierarchies() -> None:\\n    \\\"\\\"\\\"DeploymentServiceError catches both deployment and auth errors.\\\"\\\"\\\"\\n    with pytest.raises(DeploymentServiceError):\\n        raise CredentialResolutionError\\n    with pytest.raises(DeploymentServiceError):\\n        raise DeploymentNotFoundError\\n\\n\\ndef test_raise_as_deployment_error_maps_known_http_statuses() -> None:\\n    with pytest.raises(AuthenticationError):\\n        raise_as_deployment_error(status_code=401, detail=\\\"unauthorized\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(AuthorizationError):\\n        raise_as_deployment_error(status_code=403, detail=\\\"forbidden\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(ResourceNotFoundError):\\n        raise_as_deployment_error(status_code=404, detail=\\\"missing\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(ResourceConflictError):\\n        raise_as_deployment_error(status_code=409, detail=\\\"conflict\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(InvalidContentError):\\n        raise_as_deployment_error(status_code=422, detail=\\\"unprocessable\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(InvalidDeploymentOperationError):\\n        raise_as_deployment_error(status_code=400, detail=\\\"bad request\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(InvalidDeploymentOperationError):\\n        raise_as_deployment_error(status_code=405, detail=\\\"method not allowed\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(InvalidContentError):\\n        raise_as_deployment_error(status_code=413, detail=\\\"payload too large\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(InvalidContentError):\\n        raise_as_deployment_error(status_code=415, detail=\\\"unsupported media type\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(ResourceNotFoundError):\\n        raise_as_deployment_error(status_code=410, detail=\\\"gone\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(RateLimitError):\\n        raise_as_deployment_error(status_code=429, detail=\\\"too many requests\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(DeploymentTimeoutError):\\n        raise_as_deployment_error(status_code=408, detail=\\\"timeout\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(DeploymentTimeoutError):\\n        raise_as_deployment_error(status_code=504, detail=\\\"gateway timeout\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(ServiceUnavailableError):\\n        raise_as_deployment_error(status_code=502, detail=\\\"bad gateway\\\", message_prefix=\\\"x\\\")\\n    with pytest.raises(ServiceUnavailableError):\\n        raise_as_deployment_error(status_code=503, detail=\\\"service unavailable\\\", message_prefix=\\\"x\\\")\\n\\n\\ndef test_raise_as_deployment_error_does_not_infer_conflict_hints_from_detail() -> None:\\n    with pytest.raises(ResourceConflictError) as exc_info:\\n        raise_as_deployment_error(\\n            status_code=409,\\n            detail=\\\"Tool with name 'Simple_Agent' already exists for this tenant.\\\",\\n            message_prefix=\\\"x\\\",\\n        )\\n    assert exc_info.value.resource is None\\n    assert exc_info.value.resource_name is None\\n\\n\\ndef test_raise_as_deployment_error_uses_explicit_conflict_hints() -> None:\\n    with pytest.raises(ResourceConflictError) as exc_info:\\n        raise_as_deployment_error(\\n            status_code=409,\\n            detail=\\\"already exists\\\",\\n            message_prefix=\\\"x\\\",\\n            resource=\\\"TOOL\\\",\\n            resource_name=\\\" Simple_Agent \\\",\\n        )\\n    assert exc_info.value.resource == \\\"tool\\\"\\n    assert exc_info.value.resource_name == \\\"Simple_Agent\\\"\\n\\n\\ndef test_raise_as_deployment_error_uses_detail_heuristics_without_status() -> None:\\n    with pytest.raises(AuthorizationError):\\n        raise_as_deployment_error(status_code=None, detail=\\\"permission denied\\\")\\n    with pytest.raises(InvalidContentError):\\n        raise_as_deployment_error(status_code=None, detail=\\\"invalid payload\\\")\\n    with pytest.raises(RateLimitError):\\n        raise_as_deployment_error(status_code=None, detail=\\\"rate limit exceeded\\\")\\n    with pytest.raises(DeploymentTimeoutError):\\n        raise_as_deployment_error(status_code=None, detail=\\\"request timed out\\\")\\n    with pytest.raises(ServiceUnavailableError):\\n        raise_as_deployment_error(status_code=None, detail=\\\"service unavailable\\\")\\n\\n\\ndef test_raise_as_deployment_error_chains_cause_when_provided() -> None:\\n    \\\"\\\"\\\"When cause is passed, the raised exception preserves the chain.\\\"\\\"\\\"\\n    original = RuntimeError(\\\"upstream broke\\\")\\n    with pytest.raises(ResourceNotFoundError) as exc_info:\\n        raise_as_deployment_error(status_code=404, detail=\\\"gone\\\", cause=original)\\n    assert exc_info.value.__cause__ is original\\n    assert exc_info.value.cause is original\\n\\n\\ndef _raise_for_status_inside_except_handler() -> None:\\n    \\\"\\\"\\\"Helper: call raise_as_deployment_error while an exception is active.\\\"\\\"\\\"\\n    try:\\n        msg = \\\"should be suppressed\\\"\\n        raise RuntimeError(msg)\\n    except RuntimeError:\\n        raise_as_deployment_error(status_code=404, detail=\\\"gone\\\")\\n\\n\\ndef test_raise_as_deployment_error_suppresses_context_without_cause() -> None:\\n    \\\"\\\"\\\"Default (no cause) suppresses implicit exception context.\\\"\\\"\\\"\\n    with pytest.raises(ResourceNotFoundError) as exc_info:\\n        _raise_for_status_inside_except_handler()\\n    assert exc_info.value.__cause__ is None\\n    assert exc_info.value.__suppress_context__ is True\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"exc\\\", \\\"expected_status\\\"),\\n    [\\n        (ResourceConflictError(), 409),\\n        (InvalidDeploymentOperationError(), 400),\\n        (DeploymentSupportError(), 400),\\n        (InvalidDeploymentTypeError(), 400),\\n        (InvalidContentError(), 422),\\n        (DeploymentNotFoundError(), 404),\\n        (ResourceNotFoundError(), 404),\\n        (RateLimitError(), 429),\\n        (DeploymentTimeoutError(), 408),\\n        (ServiceUnavailableError(), 503),\\n        (OperationNotSupportedError(), 501),\\n        (AuthenticationError(\\\"auth fail\\\", error_code=\\\"authentication_error\\\"), 401),\\n        (CredentialResolutionError(), 401),\\n        (AuthSchemeError(), 401),\\n        (AuthorizationError(\\\"forbidden\\\", error_code=\\\"authorization_error\\\"), 403),\\n        (DeploymentNotConfiguredError(), 503),\\n        (DeploymentNotConfiguredError(method=\\\"create\\\"), 503),\\n        (DeploymentError(\\\"generic\\\", error_code=\\\"deployment_error\\\"), 500),\\n        (DeploymentServiceError(\\\"bare root\\\", error_code=\\\"unknown\\\"), 500),\\n    ],\\n)\\ndef test_http_status_for_deployment_error_maps_exception_to_status(\\n    exc: DeploymentServiceError,\\n    expected_status: int,\\n) -> None:\\n    assert http_status_for_deployment_error(exc) == expected_status\\n\\n\\ndef test_package_exports_base_and_error() -> None:\\n    from lfx.services.adapters.deployment import BaseDeploymentService, DeploymentError, DeploymentService\\n\\n    assert BaseDeploymentService is not None\\n    assert DeploymentError is not None\\n    assert DeploymentService is not None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/deployment/test_deployment_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"64dc3c94bc84a1cce8abf72d688bd6cb4c30eb0709ff36a1dda10f6f0e2df7ed\",\"content\":\"\\\"\\\"\\\"Tests for deployment schema validation and shared model shapes.\\\"\\\"\\\"\\n\\nimport json\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom lfx.services.adapters.deployment.schema import (\\n    BaseDeploymentData,\\n    BaseDeploymentDataUpdate,\\n    BaseFlowArtifact,\\n    ConfigDeploymentBindingUpdate,\\n    ConfigItem,\\n    ConfigListItem,\\n    ConfigListParams,\\n    ConfigListResult,\\n    DeploymentConfig,\\n    DeploymentCreate,\\n    DeploymentCreateResult,\\n    DeploymentDeleteResult,\\n    DeploymentListParams,\\n    DeploymentType,\\n    DeploymentUpdate,\\n    DeploymentUpdateResult,\\n    EnvVarSource,\\n    EnvVarValueSpec,\\n    ExecutionCreate,\\n    ExecutionCreateResult,\\n    ExecutionStatusResult,\\n    ItemResult,\\n    RedeployResult,\\n    SnapshotDeploymentBindingUpdate,\\n    SnapshotItem,\\n    SnapshotItems,\\n    SnapshotListParams,\\n    SnapshotListResult,\\n    get_deployment_create_schema,\\n    get_str_id,\\n    get_uuid,\\n)\\nfrom pydantic import ValidationError\\n\\n\\ndef test_snapshot_items_requires_at_least_one_source() -> None:\\n    with pytest.raises(ValidationError, match=\\\"At least one of 'raw_payloads' or 'ids'\\\"):\\n        SnapshotItems()\\n\\n\\ndef test_snapshot_items_accepts_ids_only() -> None:\\n    snap_uuid = uuid4()\\n    payload = SnapshotItems(ids=[snap_uuid, f\\\"  {snap_uuid}  \\\", \\\"snap_1\\\", \\\"snap_1\\\"])\\n    assert payload.raw_payloads is None\\n    assert payload.ids == [str(snap_uuid), \\\"snap_1\\\"]\\n\\n\\ndef test_snapshot_items_accepts_raw_payloads_and_ids() -> None:\\n    snap_uuid = uuid4()\\n    payload = SnapshotItems(\\n        raw_payloads=[\\n            {\\n                \\\"id\\\": uuid4(),\\n                \\\"name\\\": \\\"Flow\\\",\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            }\\n        ],\\n        ids=[snap_uuid],\\n    )\\n    assert payload.raw_payloads is not None\\n    assert payload.ids == [str(snap_uuid)]\\n\\n\\ndef test_snapshot_items_rejects_unknown_fields() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Extra inputs are not permitted\\\"):\\n        SnapshotItems(\\n            raw_payloads=[\\n                {\\n                    \\\"id\\\": uuid4(),\\n                    \\\"name\\\": \\\"Flow\\\",\\n                    \\\"description\\\": \\\"test\\\",\\n                    \\\"data\\\": {},\\n                    \\\"tags\\\": [],\\n                }\\n            ],\\n            reference_ids=[\\\"snap_1\\\"],\\n        )\\n\\n\\ndef test_config_item_requires_exactly_one_source() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of 'reference_id' or 'raw_payload'\\\"):\\n        ConfigItem()\\n\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of 'reference_id' or 'raw_payload'\\\"):\\n        ConfigItem(reference_id=\\\"cfg_1\\\", raw_payload={\\\"name\\\": \\\"cfg\\\"})\\n\\n\\ndef test_config_item_accepts_reference_id_only() -> None:\\n    item = ConfigItem(reference_id=\\\"cfg_1\\\")\\n    assert item.reference_id == \\\"cfg_1\\\"\\n    assert item.raw_payload is None\\n\\n\\ndef test_config_item_accepts_raw_payload_only() -> None:\\n    item = ConfigItem(raw_payload={\\\"name\\\": \\\"cfg\\\"})\\n    assert item.raw_payload is not None\\n    assert item.reference_id is None\\n\\n\\ndef test_deployment_list_params_normalizes_and_dedupes_id_filters() -> None:\\n    dep_uuid = uuid4()\\n    cfg_uuid = uuid4()\\n\\n    params = DeploymentListParams(\\n        deployment_ids=[dep_uuid, \\\"  dep-id  \\\", \\\"dep-id\\\"],\\n        snapshot_ids=[\\\"  snap-id  \\\", \\\"snap-id\\\"],\\n        config_ids=[cfg_uuid, str(cfg_uuid)],\\n    )\\n\\n    assert params.deployment_ids == [str(dep_uuid), \\\"dep-id\\\"]\\n    assert params.snapshot_ids == [\\\"snap-id\\\"]\\n    assert params.config_ids == [str(cfg_uuid)]\\n\\n\\ndef test_deployment_list_params_defaults_to_none() -> None:\\n    params = DeploymentListParams()\\n    assert params.deployment_ids is None\\n    assert params.snapshot_ids is None\\n    assert params.config_ids is None\\n    assert params.deployment_types is None\\n    assert params.provider_params is None\\n\\n\\ndef test_deployment_list_params_dedupes_types_preserving_order() -> None:\\n    params = DeploymentListParams(\\n        deployment_types=[\\n            DeploymentType.AGENT,\\n            DeploymentType.AGENT,\\n        ]\\n    )\\n    assert params.deployment_types == [DeploymentType.AGENT]\\n\\n\\ndef test_deployment_list_params_rejects_blank_filter_ids() -> None:\\n    with pytest.raises(ValidationError):\\n        DeploymentListParams(deployment_ids=[\\\"   \\\"])\\n\\n\\ndef test_deployment_list_params_validates_entity_filter_ids() -> None:\\n    params = DeploymentListParams(snapshot_ids=[\\\" snap-1 \\\", \\\"snap-1\\\"], config_ids=[\\\" cfg-1 \\\"])\\n    assert params.snapshot_ids == [\\\"snap-1\\\"]\\n    assert params.config_ids == [\\\"cfg-1\\\"]\\n\\n    with pytest.raises(ValidationError):\\n        DeploymentListParams(snapshot_ids=[\\\"snap-1\\\", \\\"  \\\"])\\n\\n\\ndef test_item_result_normalizes_name() -> None:\\n    item = ItemResult(id=\\\"dep_1\\\", name=\\\" Deployment 1 \\\", type=DeploymentType.AGENT)\\n    assert item.name == \\\"Deployment 1\\\"\\n\\n\\ndef test_item_result_rejects_blank_name() -> None:\\n    with pytest.raises(ValidationError):\\n        ItemResult(id=\\\"dep_1\\\", name=\\\"   \\\", type=DeploymentType.AGENT)\\n\\n\\ndef test_item_result_rejects_blank_id() -> None:\\n    with pytest.raises(ValidationError):\\n        ItemResult(id=\\\"   \\\", name=\\\"Deployment 1\\\", type=DeploymentType.AGENT)\\n\\n\\ndef test_snapshot_binding_update_add_ids_dedupes() -> None:\\n    snapshot_uuid = uuid4()\\n    payload = SnapshotDeploymentBindingUpdate(\\n        add_ids=[snapshot_uuid, f\\\"  {snapshot_uuid}  \\\", \\\"snap_1\\\", \\\"snap_1\\\"],\\n    )\\n    assert payload.add_ids == [str(snapshot_uuid), \\\"snap_1\\\"]\\n\\n\\ndef test_snapshot_binding_update_remove_ids_dedupes() -> None:\\n    snapshot_uuid = uuid4()\\n    payload = SnapshotDeploymentBindingUpdate(\\n        remove_ids=[snapshot_uuid, f\\\"  {snapshot_uuid}  \\\", \\\"snap_2\\\", \\\"snap_2\\\"],\\n    )\\n    assert payload.remove_ids == [str(snapshot_uuid), \\\"snap_2\\\"]\\n\\n\\ndef test_snapshot_binding_update_add_ids_only() -> None:\\n    payload = SnapshotDeploymentBindingUpdate(add_ids=[\\\"snap_1\\\"])\\n    assert payload.add_ids == [\\\"snap_1\\\"]\\n    assert payload.add_raw_payloads is None\\n    assert payload.remove_ids is None\\n\\n\\ndef test_snapshot_binding_update_add_raw_payloads_only() -> None:\\n    flow_id = uuid4()\\n    payload = SnapshotDeploymentBindingUpdate(\\n        add_raw_payloads=[\\n            {\\n                \\\"id\\\": flow_id,\\n                \\\"name\\\": \\\"Flow\\\",\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            }\\n        ]\\n    )\\n    assert payload.add_raw_payloads is not None\\n    assert len(payload.add_raw_payloads) == 1\\n    assert payload.add_ids is None\\n    assert payload.remove_ids is None\\n\\n\\ndef test_snapshot_binding_update_remove_ids_only() -> None:\\n    payload = SnapshotDeploymentBindingUpdate(remove_ids=[\\\"snap_1\\\"])\\n    assert payload.remove_ids == [\\\"snap_1\\\"]\\n    assert payload.add_ids is None\\n    assert payload.add_raw_payloads is None\\n\\n\\ndef test_snapshot_binding_update_rejects_overlap_after_normalization() -> None:\\n    snapshot_uuid = uuid4()\\n    with pytest.raises(ValidationError, match=\\\"cannot be present in both\\\"):\\n        SnapshotDeploymentBindingUpdate(\\n            add_ids=[snapshot_uuid, \\\" snap_1 \\\"],\\n            remove_ids=[str(snapshot_uuid), \\\"snap_1\\\"],\\n        )\\n\\n\\ndef test_snapshot_binding_update_rejects_blank_ids() -> None:\\n    with pytest.raises(ValidationError):\\n        SnapshotDeploymentBindingUpdate(add_ids=[\\\"   \\\"])\\n\\n\\ndef test_snapshot_binding_update_preserves_order_while_deduping() -> None:\\n    payload = SnapshotDeploymentBindingUpdate(add_ids=[\\\"b\\\", \\\"a\\\", \\\"b\\\", \\\"c\\\", \\\"a\\\"])\\n    assert payload.add_ids == [\\\"b\\\", \\\"a\\\", \\\"c\\\"]\\n\\n\\ndef test_snapshot_binding_update_rejects_noop_payload() -> None:\\n    with pytest.raises(ValidationError, match=\\\"At least one of\\\"):\\n        SnapshotDeploymentBindingUpdate()\\n\\n\\ndef test_snapshot_binding_update_add_ids_and_raw_payloads_together() -> None:\\n    flow_id = uuid4()\\n    payload = SnapshotDeploymentBindingUpdate(\\n        add_ids=[\\\"existing_snap\\\"],\\n        add_raw_payloads=[\\n            {\\n                \\\"id\\\": flow_id,\\n                \\\"name\\\": \\\"New Flow\\\",\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            }\\n        ],\\n    )\\n    assert payload.add_ids == [\\\"existing_snap\\\"]\\n    assert payload.add_raw_payloads is not None\\n    assert len(payload.add_raw_payloads) == 1\\n\\n\\ndef test_config_item_reference_id_rejects_blank() -> None:\\n    with pytest.raises(ValidationError):\\n        ConfigItem(reference_id=\\\"   \\\")\\n\\n\\ndef test_config_deployment_binding_update_normalizes_and_accepts_uuid() -> None:\\n    cfg_uuid = uuid4()\\n\\n    normalized = ConfigDeploymentBindingUpdate(config_id=\\\"  cfg_1  \\\")\\n    assert normalized.config_id == \\\"cfg_1\\\"\\n\\n    passthrough = ConfigDeploymentBindingUpdate(config_id=cfg_uuid)\\n    assert passthrough.config_id == cfg_uuid\\n\\n\\ndef test_config_deployment_binding_update_rejects_blank() -> None:\\n    with pytest.raises(ValidationError):\\n        ConfigDeploymentBindingUpdate(config_id=\\\"   \\\")\\n\\n\\ndef test_config_deployment_binding_update_accepts_raw_payload() -> None:\\n    update = ConfigDeploymentBindingUpdate(raw_payload={\\\"name\\\": \\\"new cfg\\\"})\\n    assert update.raw_payload is not None\\n    assert update.config_id is None\\n    assert update.unbind is False\\n\\n\\ndef test_config_deployment_binding_update_accepts_unbind() -> None:\\n    update = ConfigDeploymentBindingUpdate(unbind=True)\\n    assert update.unbind is True\\n    assert update.config_id is None\\n    assert update.raw_payload is None\\n\\n\\ndef test_config_deployment_binding_update_rejects_both_config_id_and_raw_payload() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of\\\"):\\n        ConfigDeploymentBindingUpdate(config_id=\\\"cfg_1\\\", raw_payload={\\\"name\\\": \\\"cfg\\\"})\\n\\n\\ndef test_config_deployment_binding_update_rejects_config_id_with_unbind() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of\\\"):\\n        ConfigDeploymentBindingUpdate(config_id=\\\"cfg_1\\\", unbind=True)\\n\\n\\ndef test_config_deployment_binding_update_rejects_raw_payload_with_unbind() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of\\\"):\\n        ConfigDeploymentBindingUpdate(raw_payload={\\\"name\\\": \\\"cfg\\\"}, unbind=True)\\n\\n\\ndef test_config_deployment_binding_update_rejects_all_three() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of\\\"):\\n        ConfigDeploymentBindingUpdate(config_id=\\\"cfg_1\\\", raw_payload={\\\"name\\\": \\\"cfg\\\"}, unbind=True)\\n\\n\\ndef test_config_deployment_binding_update_rejects_noop() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of\\\"):\\n        ConfigDeploymentBindingUpdate()\\n\\n\\ndef test_config_deployment_binding_update_rejects_unbind_false_alone() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Exactly one of\\\"):\\n        ConfigDeploymentBindingUpdate(unbind=False)\\n\\n\\ndef test_deployment_create_rejects_invalid_deployment_type() -> None:\\n    with pytest.raises(ValidationError, match=\\\"type\\\"):\\n        DeploymentCreate(spec={\\\"name\\\": \\\"my deployment\\\", \\\"type\\\": \\\"invalid-type\\\"})\\n\\n\\ndef test_snapshot_items_rejects_empty_raw_payload_list() -> None:\\n    with pytest.raises(ValidationError):\\n        SnapshotItems(raw_payloads=[])\\n\\n\\ndef test_snapshot_items_rejects_empty_ids_without_raw_payloads() -> None:\\n    with pytest.raises(ValidationError, match=\\\"At least one of 'raw_payloads' or 'ids'\\\"):\\n        SnapshotItems(ids=[])\\n\\n\\ndef test_base_flow_artifact_allows_extra_fields() -> None:\\n    flow = BaseFlowArtifact(\\n        id=uuid4(),\\n        name=\\\"Flow\\\",\\n        description=\\\"desc\\\",\\n        data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        tags=[\\\"tag\\\"],\\n        viewport={\\\"x\\\": 10, \\\"y\\\": 20},\\n    )\\n    assert flow.model_extra is not None\\n    assert flow.model_extra[\\\"viewport\\\"] == {\\\"x\\\": 10, \\\"y\\\": 20}\\n\\n\\ndef test_base_flow_artifact_requires_nodes_and_edges() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Flow must have nodes\\\"):\\n        BaseFlowArtifact(\\n            id=uuid4(),\\n            name=\\\"Flow\\\",\\n            data={\\\"edges\\\": []},\\n        )\\n\\n    with pytest.raises(ValidationError, match=\\\"Flow must have edges\\\"):\\n        BaseFlowArtifact(\\n            id=uuid4(),\\n            name=\\\"Flow\\\",\\n            data={\\\"nodes\\\": []},\\n        )\\n\\n\\ndef test_base_flow_artifact_validates_nodes_and_edges_are_lists() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Flow 'nodes' must be a list\\\"):\\n        BaseFlowArtifact(\\n            id=uuid4(),\\n            name=\\\"Flow\\\",\\n            data={\\\"nodes\\\": \\\"not a list\\\", \\\"edges\\\": []},\\n        )\\n\\n    with pytest.raises(ValidationError, match=\\\"Flow 'edges' must be a list\\\"):\\n        BaseFlowArtifact(\\n            id=uuid4(),\\n            name=\\\"Flow\\\",\\n            data={\\\"nodes\\\": [], \\\"edges\\\": 42},\\n        )\\n\\n\\ndef test_base_flow_artifact_rejects_empty_name() -> None:\\n    with pytest.raises(ValidationError):\\n        BaseFlowArtifact(\\n            id=uuid4(),\\n            name=\\\"\\\",\\n            data={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        )\\n\\n\\ndef test_snapshot_items_accepts_starter_project_data_shape() -> None:\\n    payload = SnapshotItems(\\n        raw_payloads=[\\n            {\\n                \\\"id\\\": uuid4(),\\n                \\\"name\\\": \\\"Starter Project Flow\\\",\\n                \\\"description\\\": \\\"starter project payload shape\\\",\\n                \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n            }\\n        ]\\n    )\\n    assert payload.raw_payloads is not None\\n    assert payload.raw_payloads[0].data == {\\\"nodes\\\": [], \\\"edges\\\": []}\\n\\n\\ndef test_snapshot_items_rejects_wrapped_data_shape() -> None:\\n    with pytest.raises(ValidationError, match=\\\"Flow must have nodes\\\"):\\n        SnapshotItems(\\n            raw_payloads=[\\n                {\\n                    \\\"id\\\": uuid4(),\\n                    \\\"name\\\": \\\"Wrapped Flow\\\",\\n                    # Invalid for BaseFlowArtifact.data: this is one level too high.\\n                    \\\"data\\\": {\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}},\\n                }\\n            ]\\n        )\\n\\n\\ndef test_execution_create_normalizes_string_deployment_id() -> None:\\n    payload = ExecutionCreate(deployment_id=\\\"  dep_1  \\\")\\n    assert payload.deployment_id == \\\"dep_1\\\"\\n\\n\\ndef test_execution_create_accepts_uuid_deployment_id() -> None:\\n    dep_uuid = uuid4()\\n    payload = ExecutionCreate(deployment_id=dep_uuid)\\n    assert payload.deployment_id == dep_uuid\\n\\n\\ndef test_execution_create_accepts_deployment_type() -> None:\\n    payload = ExecutionCreate(deployment_id=\\\"dep_1\\\", deployment_type=DeploymentType.AGENT)\\n    assert payload.deployment_type == DeploymentType.AGENT\\n\\n\\ndef test_execution_create_rejects_invalid_deployment_type() -> None:\\n    with pytest.raises(ValidationError, match=\\\"deployment_type\\\"):\\n        ExecutionCreate(deployment_id=\\\"dep_1\\\", deployment_type=\\\"invalid-type\\\")\\n\\n\\ndef test_execution_create_rejects_blank_deployment_id() -> None:\\n    with pytest.raises(ValidationError):\\n        ExecutionCreate(deployment_id=\\\"   \\\")\\n\\n\\ndef test_get_id_helpers_round_trip() -> None:\\n    value = uuid4()\\n    value_str = get_str_id(value)\\n    assert isinstance(value_str, str)\\n    assert get_uuid(value_str) == value\\n\\n    passthrough = \\\"dep_1\\\"\\n    assert get_str_id(passthrough) == passthrough\\n    assert get_uuid(str(value)) == UUID(str(value))\\n\\n\\ndef test_get_uuid_rejects_non_uuid_strings() -> None:\\n    with pytest.raises(ValueError, match=\\\"Use get_str_id\\\\\\\\(\\\\\\\\) for opaque IDs\\\"):\\n        get_uuid(\\\"dep_1\\\")\\n\\n\\ndef test_execution_create_and_status_results_have_same_shape() -> None:\\n    payload = {\\n        \\\"execution_id\\\": \\\"exec_1\\\",\\n        \\\"deployment_id\\\": \\\"dep_1\\\",\\n        \\\"provider_result\\\": {\\\"status\\\": \\\"running\\\"},\\n    }\\n\\n    create_result = ExecutionCreateResult(**payload)\\n    status_result = ExecutionStatusResult(**payload)\\n\\n    assert create_result.model_dump() == status_result.model_dump()\\n\\n\\ndef test_deployment_update_result_uses_base_operation_shape() -> None:\\n    result = DeploymentUpdateResult(id=\\\"dep_1\\\")\\n    assert result.id == \\\"dep_1\\\"\\n    assert result.provider_result is None\\n\\n\\ndef test_operation_results_share_provider_result_contract() -> None:\\n    provider_result = {\\\"accepted\\\": True}\\n\\n    deleted = DeploymentDeleteResult(id=\\\"dep_1\\\", provider_result=provider_result)\\n    updated = DeploymentUpdateResult(id=\\\"dep_1\\\", provider_result=provider_result)\\n    redeployed = RedeployResult(id=\\\"dep_1\\\", provider_result=provider_result)\\n\\n    assert deleted.provider_result == provider_result\\n    assert updated.provider_result == provider_result\\n    assert redeployed.provider_result == provider_result\\n\\n\\ndef test_base_deployment_data_update_requires_at_least_one_field() -> None:\\n    with pytest.raises(ValidationError, match=\\\"At least one of 'name' or 'description'\\\"):\\n        BaseDeploymentDataUpdate()\\n\\n\\ndef test_base_deployment_data_update_accepts_explicit_null_description() -> None:\\n    payload = BaseDeploymentDataUpdate(description=None)\\n\\n    assert payload.description is None\\n    assert \\\"description\\\" in payload.model_fields_set\\n\\n\\ndef test_base_deployment_data_normalizes_name() -> None:\\n    payload = BaseDeploymentData(name=\\\" My Deployment \\\", type=DeploymentType.AGENT)\\n    assert payload.name == \\\"My Deployment\\\"\\n\\n\\ndef test_base_deployment_data_allows_omitted_name() -> None:\\n    payload = BaseDeploymentData(type=DeploymentType.AGENT)\\n    assert payload.name is None\\n\\n\\ndef test_base_deployment_data_rejects_blank_name() -> None:\\n    with pytest.raises(ValidationError):\\n        BaseDeploymentData(name=\\\"   \\\", type=DeploymentType.AGENT)\\n\\n\\ndef test_base_deployment_data_update_normalizes_name() -> None:\\n    payload = BaseDeploymentDataUpdate(name=\\\" My Deployment \\\")\\n    assert payload.name == \\\"My Deployment\\\"\\n\\n\\ndef test_base_deployment_data_update_rejects_blank_name() -> None:\\n    with pytest.raises(ValidationError):\\n        BaseDeploymentDataUpdate(name=\\\"   \\\")\\n\\n\\ndef test_base_deployment_data_update_rejects_explicit_null_name() -> None:\\n    with pytest.raises(ValidationError, match=\\\"'name' cannot be set to null\\\"):\\n        BaseDeploymentDataUpdate(name=None)\\n\\n\\ndef test_deployment_update_requires_at_least_one_section() -> None:\\n    with pytest.raises(ValidationError, match=\\\"At least one of\\\"):\\n        DeploymentUpdate()\\n\\n\\ndef test_deployment_update_rejects_explicit_null_only_payload() -> None:\\n    with pytest.raises(ValidationError, match=\\\"At least one of\\\"):\\n        DeploymentUpdate(spec=None)\\n\\n\\ndef test_deployment_update_accepts_spec_only() -> None:\\n    update = DeploymentUpdate(spec={\\\"name\\\": \\\"new name\\\"})\\n    assert update.spec is not None\\n    assert update.snapshot is None\\n    assert update.config is None\\n\\n\\ndef test_deployment_update_accepts_config_only() -> None:\\n    update = DeploymentUpdate(config={\\\"config_id\\\": \\\"cfg_1\\\"})\\n    assert update.config is not None\\n    assert update.spec is None\\n    assert update.snapshot is None\\n\\n\\ndef test_deployment_update_accepts_snapshot_only() -> None:\\n    update = DeploymentUpdate(snapshot={\\\"add_ids\\\": [\\\"snap_1\\\"]})\\n    assert update.snapshot is not None\\n    assert update.spec is None\\n    assert update.config is None\\n\\n\\ndef test_deployment_update_accepts_provider_data_only() -> None:\\n    update = DeploymentUpdate(provider_data={\\\"mode\\\": \\\"dry_run\\\"})\\n    assert update.provider_data == {\\\"mode\\\": \\\"dry_run\\\"}\\n    assert update.spec is None\\n    assert update.snapshot is None\\n    assert update.config is None\\n\\n\\ndef test_env_var_config_accepts_raw_and_variable_sources() -> None:\\n    config = DeploymentConfig(\\n        name=\\\"cfg\\\",\\n        environment_variables={\\n            \\\"RAW_TOKEN\\\": EnvVarValueSpec(value=\\\"literal\\\", source=EnvVarSource.RAW),\\n            \\\"VAR_TOKEN\\\": EnvVarValueSpec(value=\\\"OPENAI_API_KEY\\\", source=EnvVarSource.VARIABLE),\\n        },\\n    )\\n    assert config.environment_variables is not None\\n    assert config.environment_variables[\\\"RAW_TOKEN\\\"].source == EnvVarSource.RAW\\n    assert config.environment_variables[\\\"VAR_TOKEN\\\"].source == EnvVarSource.VARIABLE\\n\\n\\ndef test_env_var_value_spec_rejects_blank_value() -> None:\\n    with pytest.raises(ValidationError):\\n        EnvVarValueSpec(value=\\\"  \\\")\\n\\n\\ndef test_deployment_create_happy_path_with_snapshot_and_config() -> None:\\n    payload = DeploymentCreate(\\n        spec={\\\"name\\\": \\\"my deployment\\\", \\\"description\\\": \\\"desc\\\", \\\"type\\\": DeploymentType.AGENT},\\n        snapshot={\\n            \\\"raw_payloads\\\": [\\n                {\\n                    \\\"id\\\": uuid4(),\\n                    \\\"name\\\": \\\"Flow\\\",\\n                    \\\"description\\\": \\\"flow description\\\",\\n                    \\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n                }\\n            ]\\n        },\\n        config={\\\"raw_payload\\\": {\\\"name\\\": \\\"cfg\\\", \\\"description\\\": \\\"cfg desc\\\"}},\\n    )\\n    assert payload.spec.type == DeploymentType.AGENT\\n    assert payload.snapshot is not None\\n    assert payload.config is not None\\n\\n\\ndef test_deployment_create_result_defaults() -> None:\\n    result = DeploymentCreateResult(\\n        id=\\\"dep_1\\\",\\n        type=DeploymentType.AGENT,\\n    )\\n    assert result.name is None\\n    assert result.description is None\\n\\n\\ndef test_deployment_create_result_allows_long_provider_description() -> None:\\n    description = \\\"x\\\" * 501\\n\\n    result = DeploymentCreateResult(\\n        id=\\\"dep_1\\\",\\n        type=DeploymentType.AGENT,\\n        description=description,\\n    )\\n\\n    assert result.description == description\\n\\n\\ndef test_get_deployment_create_schema_returns_valid_json() -> None:\\n    schema_str = get_deployment_create_schema()\\n    schema = json.loads(schema_str)\\n    assert \\\"properties\\\" in schema\\n    assert \\\"spec\\\" in schema[\\\"properties\\\"]\\n\\n\\ndef test_get_deployment_create_schema_is_cached() -> None:\\n    first = get_deployment_create_schema()\\n    second = get_deployment_create_schema()\\n    assert first is second\\n\\n\\n# ---------------------------------------------------------------------------\\n# SnapshotItem\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_snapshot_item_accepts_minimal_fields() -> None:\\n    item = SnapshotItem(id=\\\"snap_1\\\", name=\\\"Snapshot\\\")\\n    assert item.id == \\\"snap_1\\\"\\n    assert item.name == \\\"Snapshot\\\"\\n    assert item.provider_data is None\\n\\n\\ndef test_snapshot_item_accepts_uuid_id() -> None:\\n    snap_uuid = uuid4()\\n    item = SnapshotItem(id=snap_uuid, name=\\\"Snapshot\\\")\\n    assert item.id == snap_uuid\\n\\n\\ndef test_snapshot_item_does_not_have_description() -> None:\\n    assert \\\"description\\\" not in SnapshotItem.model_fields\\n\\n\\n# ---------------------------------------------------------------------------\\n# ConfigListItem\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_config_list_item_accepts_minimal_fields() -> None:\\n    item = ConfigListItem(id=\\\"cfg_1\\\", name=\\\"Config\\\")\\n    assert item.id == \\\"cfg_1\\\"\\n    assert item.name == \\\"Config\\\"\\n    assert item.created_at is None\\n    assert item.updated_at is None\\n\\n\\ndef test_config_list_item_accepts_uuid_id() -> None:\\n    cfg_uuid = uuid4()\\n    item = ConfigListItem(id=cfg_uuid, name=\\\"Config\\\")\\n    assert item.id == cfg_uuid\\n\\n\\ndef test_config_list_item_does_not_have_description() -> None:\\n    assert \\\"description\\\" not in ConfigListItem.model_fields\\n\\n\\ndef test_config_list_item_accepts_all_fields() -> None:\\n    import datetime\\n\\n    now = datetime.datetime.now(tz=datetime.timezone.utc)\\n    item = ConfigListItem(\\n        id=\\\"cfg_1\\\",\\n        name=\\\"Config\\\",\\n        created_at=now,\\n        updated_at=now,\\n    )\\n    assert item.created_at == now\\n    assert item.updated_at == now\\n\\n\\n# ---------------------------------------------------------------------------\\n# ConfigListResult / SnapshotListResult\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_config_list_result_wraps_items() -> None:\\n    result = ConfigListResult(\\n        configs=[\\n            ConfigListItem(id=\\\"cfg_1\\\", name=\\\"Config 1\\\"),\\n            ConfigListItem(id=\\\"cfg_2\\\", name=\\\"Config 2\\\"),\\n        ],\\n    )\\n    assert len(result.configs) == 2\\n    assert result.provider_result is None\\n\\n\\ndef test_config_list_result_accepts_provider_result() -> None:\\n    result = ConfigListResult(\\n        configs=[],\\n        provider_result={\\\"total\\\": 0},\\n    )\\n    assert result.provider_result == {\\\"total\\\": 0}\\n\\n\\ndef test_snapshot_list_result_wraps_items() -> None:\\n    result = SnapshotListResult(\\n        snapshots=[\\n            SnapshotItem(id=\\\"snap_1\\\", name=\\\"Snapshot 1\\\"),\\n        ],\\n    )\\n    assert len(result.snapshots) == 1\\n    assert result.provider_result is None\\n\\n\\ndef test_snapshot_list_result_accepts_provider_result() -> None:\\n    result = SnapshotListResult(\\n        snapshots=[],\\n        provider_result={\\\"total\\\": 0},\\n    )\\n    assert result.provider_result == {\\\"total\\\": 0}\\n\\n\\n# ---------------------------------------------------------------------------\\n# ConfigListParams / SnapshotListParams / DeploymentListParams\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_config_list_params_defaults_to_none() -> None:\\n    params = ConfigListParams()\\n    assert params.provider_params is None\\n    assert params.deployment_ids is None\\n    assert params.config_ids is None\\n\\n\\ndef test_config_list_params_inherits_filter_validation() -> None:\\n    cfg_uuid = uuid4()\\n    params = ConfigListParams(\\n        config_ids=[cfg_uuid, str(cfg_uuid)],\\n        deployment_ids=[\\\"  dep-id  \\\", \\\"dep-id\\\"],\\n    )\\n    assert params.config_ids == [str(cfg_uuid)]\\n    assert params.deployment_ids == [\\\"dep-id\\\"]\\n\\n\\ndef test_config_list_params_rejects_blank_ids() -> None:\\n    with pytest.raises(ValidationError):\\n        ConfigListParams(config_ids=[\\\"   \\\"])\\n\\n\\ndef test_snapshot_list_params_defaults_to_none() -> None:\\n    params = SnapshotListParams()\\n    assert params.provider_params is None\\n    assert params.deployment_ids is None\\n    assert params.snapshot_ids is None\\n\\n\\ndef test_snapshot_list_params_inherits_filter_validation() -> None:\\n    params = SnapshotListParams(\\n        snapshot_ids=[\\\"  snap-id  \\\", \\\"snap-id\\\"],\\n    )\\n    assert params.snapshot_ids == [\\\"snap-id\\\"]\\n\\n\\ndef test_snapshot_list_params_rejects_blank_ids() -> None:\\n    with pytest.raises(ValidationError):\\n        SnapshotListParams(snapshot_ids=[\\\"   \\\"])\\n\\n\\ndef test_base_list_params_fields_shared_across_all_subclasses() -> None:\\n    \\\"\\\"\\\"All params classes share only provider/deployment-scoped base fields.\\\"\\\"\\\"\\n    for params_cls in (DeploymentListParams, ConfigListParams, SnapshotListParams):\\n        params = params_cls(\\n            provider_params={\\\"key\\\": \\\"value\\\"},\\n            deployment_ids=[\\\"dep_1\\\"],\\n        )\\n        assert params.provider_params == {\\\"key\\\": \\\"value\\\"}\\n        assert params.deployment_ids == [\\\"dep_1\\\"]\\n\\n\\ndef test_entity_specific_fields_are_scoped_to_own_params_classes() -> None:\\n    deployment_fields = set(DeploymentListParams.model_fields)\\n    config_fields = set(ConfigListParams.model_fields)\\n    snapshot_fields = set(SnapshotListParams.model_fields)\\n\\n    assert \\\"deployment_types\\\" in deployment_fields\\n    assert \\\"snapshot_ids\\\" in deployment_fields\\n    assert \\\"config_ids\\\" in deployment_fields\\n\\n    assert \\\"config_ids\\\" in config_fields\\n    assert \\\"snapshot_ids\\\" not in config_fields\\n    assert \\\"deployment_types\\\" not in config_fields\\n\\n    assert \\\"snapshot_ids\\\" in snapshot_fields\\n    assert \\\"config_ids\\\" not in snapshot_fields\\n    assert \\\"deployment_types\\\" not in snapshot_fields\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/deployment/test_payload_formalization.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a3c31f102ebfcca65867d291c4e8c86422269419c0ab9b95725149df30c9c65b\",\"content\":\"\\\"\\\"\\\"Tests for deployment payload slot formalization.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import fields\\nfrom datetime import datetime, timezone\\nfrom enum import Enum\\nfrom uuid import UUID\\n\\nimport pytest\\nfrom lfx.services.adapters.deployment.payloads import DeploymentPayloadSchemas\\nfrom lfx.services.adapters.deployment.schema import (\\n    ConfigListParams,\\n    ConfigListResult,\\n    DeploymentCreateResult,\\n    DeploymentListParams,\\n    DeploymentListResult,\\n    DeploymentOperationResult,\\n    DeploymentStatusResult,\\n    DeploymentType,\\n    DeploymentUpdateResult,\\n    ExecutionCreateResult,\\n    ExecutionResultBase,\\n    ExecutionStatusResult,\\n    ItemResult,\\n    SnapshotListParams,\\n    SnapshotListResult,\\n)\\nfrom lfx.services.adapters.payload import (\\n    AdapterPayloadMissingError,\\n    AdapterPayloadValidationError,\\n    PayloadSlot,\\n    PayloadSlotPolicy,\\n)\\nfrom pydantic import BaseModel, ConfigDict\\n\\n\\nclass _SpecModel(BaseModel):\\n    region: str\\n\\n\\nclass _SpecModelCompat(BaseModel):\\n    region: str\\n\\n\\nclass _SpecModelWithExtra(BaseModel):\\n    region: str\\n    zone: str\\n\\n\\nclass _StatusModel(BaseModel):\\n    healthy: bool\\n\\n\\nclass _FilterModel(BaseModel):\\n    env: str\\n\\n\\nclass _ResultModel(BaseModel):\\n    external_url: str\\n\\n\\nclass _ExecutionResultModel(BaseModel):\\n    status: str\\n\\n\\nclass _ConfigFilterModel(BaseModel):\\n    namespace: str\\n\\n\\nclass _SnapshotFilterModel(BaseModel):\\n    label: str\\n\\n\\nclass _ApiLikeConfigModel(BaseModel):\\n    retries: int\\n\\n\\nclass _StrictApiLikeConfigModel(BaseModel):\\n    model_config = ConfigDict(extra=\\\"forbid\\\")\\n\\n    retries: int\\n\\n\\nclass _Color(str, Enum):\\n    BLUE = \\\"blue\\\"\\n\\n\\nclass _NestedPayload(BaseModel):\\n    tag: str\\n\\n\\nclass _RichPayload(BaseModel):\\n    uid: UUID\\n    created_at: datetime\\n    color: _Color\\n    nested: _NestedPayload\\n\\n\\ndef test_payload_slot_parse_and_dump_round_trip() -> None:\\n    slot = PayloadSlot(_SpecModel)\\n\\n    parsed = slot.parse({\\\"region\\\": \\\"us-east-1\\\"})\\n\\n    assert isinstance(parsed, _SpecModel)\\n    assert slot.dump(parsed) == {\\\"region\\\": \\\"us-east-1\\\"}\\n\\n\\ndef test_payload_slot_parse_accepts_same_model_instance() -> None:\\n    slot = PayloadSlot(_SpecModel)\\n\\n    parsed = slot.parse(_SpecModel(region=\\\"us-east-1\\\"))\\n\\n    assert isinstance(parsed, _SpecModel)\\n    assert parsed.region == \\\"us-east-1\\\"\\n\\n\\ndef test_payload_slot_parse_rejects_compatible_model_instance() -> None:\\n    slot = PayloadSlot(_SpecModel)\\n\\n    with pytest.raises(AdapterPayloadValidationError, match=\\\"Invalid payload\\\"):\\n        slot.parse(_SpecModelCompat(region=\\\"us-east-1\\\"))\\n\\n\\ndef test_payload_slot_parse_rejects_non_matching_model_instance() -> None:\\n    slot = PayloadSlot(_SpecModel)\\n\\n    with pytest.raises(AdapterPayloadValidationError, match=\\\"Invalid payload\\\"):\\n        slot.parse(_SpecModelWithExtra(region=\\\"us-east-1\\\", zone=\\\"1a\\\"))\\n\\n\\ndef test_payload_slot_raises_typed_validation_error() -> None:\\n    slot = PayloadSlot(_SpecModel)\\n\\n    with pytest.raises(AdapterPayloadValidationError, match=\\\"Invalid payload\\\") as exc:\\n        slot.parse({\\\"missing\\\": \\\"region\\\"})\\n    assert exc.value.model_name == \\\"_SpecModel\\\"\\n    assert exc.value.error is not None\\n    assert exc.value.format_first_error() == \\\"Missing required field 'region'.\\\"\\n\\n\\ndef test_payload_validation_error_formats_non_missing_with_field_path() -> None:\\n    slot = PayloadSlot(_ApiLikeConfigModel)\\n\\n    with pytest.raises(AdapterPayloadValidationError, match=\\\"Invalid payload\\\") as exc:\\n        slot.parse({\\\"retries\\\": \\\"not-an-int\\\"})\\n\\n    assert exc.value.format_first_error() == \\\"Invalid value for field 'retries'.\\\"\\n\\n\\ndef test_payload_validation_error_formats_extra_field_as_invalid_field() -> None:\\n    slot = PayloadSlot(_StrictApiLikeConfigModel)\\n\\n    with pytest.raises(AdapterPayloadValidationError, match=\\\"Invalid payload\\\") as exc:\\n        slot.parse({\\\"retries\\\": 3, \\\"resource_name_prefix\\\": \\\"lf_\\\"})\\n\\n    assert exc.value.format_first_error() == \\\"Invalid field 'resource_name_prefix'. Please remove it.\\\"\\n\\n\\ndef test_payload_slot_raises_typed_missing_error_for_none() -> None:\\n    slot = PayloadSlot(_SpecModel)\\n\\n    with pytest.raises(AdapterPayloadMissingError, match=\\\"Missing payload\\\") as exc:\\n        slot.parse(None)\\n    assert exc.value.model_name == \\\"_SpecModel\\\"\\n\\n\\ndef test_payload_slot_dump_json_serializes_uuid_datetime_enum_and_nested_model() -> None:\\n    slot = PayloadSlot(_RichPayload)\\n    parsed = slot.parse(\\n        {\\n            \\\"uid\\\": \\\"d779b2b7-302e-4f7b-af66-3fe4fd51b9fe\\\",\\n            \\\"created_at\\\": \\\"2026-01-02T03:04:05Z\\\",\\n            \\\"color\\\": \\\"blue\\\",\\n            \\\"nested\\\": {\\\"tag\\\": \\\"x\\\"},\\n        }\\n    )\\n\\n    dumped = slot.dump(parsed)\\n\\n    assert dumped == {\\n        \\\"uid\\\": \\\"d779b2b7-302e-4f7b-af66-3fe4fd51b9fe\\\",\\n        \\\"created_at\\\": \\\"2026-01-02T03:04:05Z\\\",\\n        \\\"color\\\": \\\"blue\\\",\\n        \\\"nested\\\": {\\\"tag\\\": \\\"x\\\"},\\n    }\\n\\n\\ndef test_payload_slot_apply_validate_only_policy_returns_original_payload() -> None:\\n    slot = PayloadSlot(_SpecModel, policy=PayloadSlotPolicy.VALIDATE_ONLY)\\n    raw = {\\\"region\\\": \\\"us-east-1\\\"}\\n\\n    applied = slot.apply(raw)\\n\\n    assert applied == raw\\n    assert applied is raw\\n\\n\\ndef test_payload_slot_apply_validate_and_dump_policy_normalizes_payload() -> None:\\n    slot = PayloadSlot(_ApiLikeConfigModel, policy=PayloadSlotPolicy.VALIDATE_AND_DUMP)\\n    raw = {\\\"retries\\\": \\\"3\\\"}\\n\\n    applied = slot.apply(raw)\\n\\n    assert applied == {\\\"retries\\\": 3}\\n    assert applied is not raw\\n\\n\\ndef test_deployment_payload_schemas_exposes_slots_and_active_slots() -> None:\\n    schemas = DeploymentPayloadSchemas(\\n        deployment_spec=PayloadSlot(_SpecModel),\\n        deployment_status_data=PayloadSlot(_StatusModel),\\n    )\\n\\n    all_slots = schemas.slots()\\n    active_slots = schemas.active_slots()\\n\\n    assert set(all_slots) == {field.name for field in fields(DeploymentPayloadSchemas)}\\n    assert set(active_slots) == {\\\"deployment_spec\\\", \\\"deployment_status_data\\\"}\\n    assert all_slots[\\\"deployment_config\\\"] is None\\n\\n\\ndef test_deployment_payload_schemas_defaults_to_no_active_slots() -> None:\\n    assert DeploymentPayloadSchemas().active_slots() == {}\\n\\n\\ndef test_generic_parametrization_applies_to_provider_fields() -> None:\\n    typed_status = DeploymentStatusResult[_StatusModel](\\n        id=\\\"dep_1\\\",\\n        provider_data={\\\"healthy\\\": True},\\n    )\\n    typed_params = DeploymentListParams[_FilterModel](provider_params={\\\"env\\\": \\\"prod\\\"})\\n\\n    assert isinstance(typed_status.provider_data, _StatusModel)\\n    assert isinstance(typed_params.provider_params, _FilterModel)\\n\\n\\ndef test_generic_parametrization_applies_to_result_and_list_models() -> None:\\n    typed_create = DeploymentCreateResult[_ResultModel](\\n        id=\\\"dep_1\\\",\\n        type=DeploymentType.AGENT,\\n        provider_result={\\\"external_url\\\": \\\"https://dep.example\\\"},\\n    )\\n    typed_operation = DeploymentOperationResult[_ResultModel](\\n        id=\\\"dep_1\\\",\\n        provider_result={\\\"external_url\\\": \\\"https://dep.example\\\"},\\n    )\\n    typed_update = DeploymentUpdateResult[_ResultModel](\\n        id=\\\"dep_1\\\",\\n        provider_result={\\\"external_url\\\": \\\"https://dep.example\\\"},\\n    )\\n    typed_execution = ExecutionResultBase[_ExecutionResultModel](\\n        execution_id=\\\"exec_1\\\",\\n        deployment_id=\\\"dep_1\\\",\\n        provider_result={\\\"status\\\": \\\"running\\\"},\\n    )\\n    typed_execution_create = ExecutionCreateResult[_ExecutionResultModel](\\n        execution_id=\\\"exec_1\\\",\\n        deployment_id=\\\"dep_1\\\",\\n        provider_result={\\\"status\\\": \\\"running\\\"},\\n    )\\n    typed_execution_status = ExecutionStatusResult[_ExecutionResultModel](\\n        execution_id=\\\"exec_1\\\",\\n        deployment_id=\\\"dep_1\\\",\\n        provider_result={\\\"status\\\": \\\"running\\\"},\\n    )\\n    typed_item = ItemResult[_StatusModel](\\n        id=\\\"dep_1\\\",\\n        name=\\\"dep\\\",\\n        type=DeploymentType.AGENT,\\n        provider_data={\\\"healthy\\\": True},\\n    )\\n    typed_deployment_list = DeploymentListResult[_ResultModel](\\n        deployments=[],\\n        provider_result={\\\"external_url\\\": \\\"https://dep.example\\\"},\\n    )\\n    typed_config_list = ConfigListResult[_ResultModel](\\n        configs=[],\\n        provider_result={\\\"external_url\\\": \\\"https://dep.example\\\"},\\n    )\\n    typed_snapshot_list = SnapshotListResult[_ResultModel, _StatusModel](\\n        snapshots=[],\\n        provider_result={\\\"external_url\\\": \\\"https://dep.example\\\"},\\n    )\\n    typed_config_params = ConfigListParams[_ConfigFilterModel](provider_params={\\\"namespace\\\": \\\"prod\\\"})\\n    typed_snapshot_params = SnapshotListParams[_SnapshotFilterModel](provider_params={\\\"label\\\": \\\"nightly\\\"})\\n\\n    assert isinstance(typed_create.provider_result, _ResultModel)\\n    assert isinstance(typed_operation.provider_result, _ResultModel)\\n    assert isinstance(typed_update.provider_result, _ResultModel)\\n    assert isinstance(typed_execution.provider_result, _ExecutionResultModel)\\n    assert isinstance(typed_execution_create.provider_result, _ExecutionResultModel)\\n    assert isinstance(typed_execution_status.provider_result, _ExecutionResultModel)\\n    assert isinstance(typed_item.provider_data, _StatusModel)\\n    assert isinstance(typed_deployment_list.provider_result, _ResultModel)\\n    assert isinstance(typed_config_list.provider_result, _ResultModel)\\n    assert isinstance(typed_snapshot_list.provider_result, _ResultModel)\\n    assert isinstance(typed_config_params.provider_params, _ConfigFilterModel)\\n    assert isinstance(typed_snapshot_params.provider_params, _SnapshotFilterModel)\\n\\n\\ndef test_payload_slot_dump_json_serializes_rich_payload() -> None:\\n    now = datetime(2026, 1, 2, 3, 4, 5, tzinfo=timezone.utc)\\n    rich_slot = PayloadSlot(_RichPayload)\\n    dumped = rich_slot.dump(\\n        _RichPayload(\\n            uid=UUID(\\\"d779b2b7-302e-4f7b-af66-3fe4fd51b9fe\\\"),\\n            created_at=now,\\n            color=_Color.BLUE,\\n            nested=_NestedPayload(tag=\\\"x\\\"),\\n        )\\n    )\\n    assert dumped[\\\"uid\\\"] == \\\"d779b2b7-302e-4f7b-af66-3fe4fd51b9fe\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/durable/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/durable/test_resume_after_restart.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c8dea45e27bb8545fdb4bce088cf315484af0b3d017732217c4539eaf131e05e\",\"content\":\"\\\"\\\"\\\"LE-1695 acceptance (seam-independent): a paused run survives a process restart.\\n\\nDrives the REAL pause/resume machinery (``graph.process`` + ``GraphPausedException`` +\\n``resume_from_checkpoint``) against the durable SQLite stores. The \\\"restart\\\" is a fresh\\nstore instance on the same file \u2014 everything in memory is discarded, exactly like a new\\nprocess \u2014 and the run must resume to completion without re-executing built vertices.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.components.flow_controls.human_input import HumanInput\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph.exceptions import GraphPausedException\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.schema.schema import INPUT_FIELD_NAME\\nfrom lfx.services.durable.models import JobStatus\\nfrom lfx.services.durable.sqlite_checkpoints import SqliteCheckpointStore\\nfrom lfx.services.durable.sqlite_store import SqliteDurableJobStore\\n\\nJOB_ID = \\\"job-restart-1\\\"\\n\\n\\ndef _node(component) -> dict:\\n    frontend = component.to_frontend_node()\\n    return {\\\"id\\\": frontend[\\\"id\\\"], \\\"data\\\": frontend[\\\"data\\\"]}\\n\\n\\ndef _edge(source: str, target: str, handle: str, field: str = \\\"input_value\\\") -> dict:\\n    return {\\n        \\\"source\\\": source,\\n        \\\"target\\\": target,\\n        \\\"id\\\": f\\\"{source}-{handle}-{target}\\\",\\n        \\\"data\\\": {\\n            \\\"sourceHandle\\\": {\\\"dataType\\\": \\\"x\\\", \\\"id\\\": source, \\\"name\\\": handle, \\\"output_types\\\": [\\\"Message\\\"]},\\n            \\\"targetHandle\\\": {\\\"fieldName\\\": field, \\\"id\\\": target, \\\"inputTypes\\\": [\\\"Message\\\"], \\\"type\\\": \\\"str\\\"},\\n        },\\n    }\\n\\n\\ndef _pausing_graph() -> Graph:\\n    payload = {\\n        \\\"nodes\\\": [\\n            _node(ChatInput(_id=\\\"chat_input\\\")),\\n            _node(HumanInput(_id=\\\"hitl1\\\")),\\n            _node(ChatOutput(_id=\\\"co_approve\\\")),\\n            _node(ChatOutput(_id=\\\"co_reject\\\")),\\n        ],\\n        \\\"edges\\\": [\\n            _edge(\\\"chat_input\\\", \\\"hitl1\\\", \\\"message\\\", field=\\\"prompt\\\"),\\n            _edge(\\\"hitl1\\\", \\\"co_approve\\\", \\\"branch_approve\\\"),\\n            _edge(\\\"hitl1\\\", \\\"co_reject\\\", \\\"branch_reject\\\"),\\n        ],\\n    }\\n    graph = Graph.from_payload(payload, flow_id=\\\"durable-restart\\\")\\n    graph.prepare()\\n    return graph\\n\\n\\n@pytest.mark.asyncio\\nasync def test_suspended_run_resumes_to_completion_after_restart(tmp_path):\\n    db_path = tmp_path / \\\"durable.db\\\"\\n    jobs = SqliteDurableJobStore(db_path)\\n    checkpoints = SqliteCheckpointStore(db_path)\\n\\n    graph = _pausing_graph()\\n    graph.job_id = JOB_ID\\n    graph.checkpointing_enabled = True\\n    graph.checkpoint_store = checkpoints\\n    graph._set_inputs([], {INPUT_FIELD_NAME: \\\"hello\\\"}, \\\"chat\\\")\\n    await jobs.create_job(job_id=JOB_ID, flow_id=\\\"durable-restart\\\", user_id=\\\"u1\\\")\\n    await jobs.update_status(JOB_ID, JobStatus.IN_PROGRESS)\\n\\n    with pytest.raises(GraphPausedException) as pause:\\n        await graph.process(fallback_to_env_vars=False)\\n    await jobs.update_status(JOB_ID, JobStatus.SUSPENDED)\\n    request_id = (pause.value.data or {}).get(\\\"request_id\\\")\\n    run_id = str(graph.run_id)\\n\\n    # ---- \\\"process restart\\\": all live objects are gone; only the SQLite file remains ----\\n    del graph, jobs, checkpoints\\n    jobs_after = SqliteDurableJobStore(db_path)\\n    checkpoints_after = SqliteCheckpointStore(db_path)\\n\\n    assert (await jobs_after.get_job(JOB_ID)).status == JobStatus.SUSPENDED\\n    assert await jobs_after.claim_suspended_for_resume(JOB_ID) is True\\n\\n    checkpoint = await checkpoints_after.load_by_run_id(run_id)\\n    assert checkpoint is not None\\n    resumed = Graph.resume_from_checkpoint(checkpoint, checkpoint_store=checkpoints_after)\\n    resumed.checkpointing_enabled = True\\n    resumed.checkpoint_store = checkpoints_after\\n    resumed.human_input_decisions = {request_id: {\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}}}\\n    for vertex in resumed.vertices:\\n        if f\\\"{vertex.id}:{resumed.run_id}\\\" == request_id:\\n            vertex.built = False\\n\\n    await resumed.process(fallback_to_env_vars=False)\\n    await jobs_after.set_result(JOB_ID, {\\\"status\\\": \\\"completed\\\"})\\n\\n    assert (await jobs_after.get_job(JOB_ID)).status == JobStatus.COMPLETED\\n    assert resumed.get_vertex(\\\"co_approve\\\").built is True\\n    assert resumed.get_vertex(\\\"co_reject\\\").built is False\\n    # Built-before-the-pause vertices were restored, not re-executed.\\n    assert resumed.get_vertex(\\\"chat_input\\\").built is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/durable/test_sqlite_checkpoints.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6d3fbaba048cb0ed650da056660f78e246c306e56ffb2e6e155d590ddb82d039\",\"content\":\"\\\"\\\"\\\"SqliteCheckpointStore \u2014 durable CheckpointStore backend (LE-1695).\\n\\nImplements the existing ``lfx.graph.checkpoint.store.CheckpointStore`` ABC on the same\\nsingle SQLite file as the job store, so one crash-safe artifact holds a run's job row,\\nevent log, and checkpoint. Round-trips a REAL GraphCheckpoint built from a real paused\\ngraph \u2014 not a hand-made stub \u2014 per the prefer-real-integrations policy.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timedelta, timezone\\n\\nimport pytest\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph import Graph\\nfrom lfx.services.durable.sqlite_checkpoints import SqliteCheckpointStore\\n\\n\\n@pytest.fixture\\ndef store(tmp_path):\\n    return SqliteCheckpointStore(tmp_path / \\\"durable.db\\\")\\n\\n\\nasync def _real_checkpoint(job_id: str = \\\"job-1\\\"):\\n    chat_input = ChatInput(_id=\\\"chat_input\\\", input_value=\\\"hello\\\")\\n    chat_input.set(should_store_message=False)\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response, should_store_message=False)\\n    graph = Graph(chat_input, chat_output)\\n    graph.session_id = \\\"sess-1\\\"\\n    graph.set_run_id()\\n    graph.checkpointing_enabled = True\\n    graph.job_id = job_id\\n    await graph.astep()\\n    return graph.build_checkpoint()\\n\\n\\nclass TestCheckpointRoundTrip:\\n    async def test_should_load_a_saved_checkpoint_by_id(self, store):\\n        checkpoint = await _real_checkpoint()\\n\\n        await store.save(checkpoint)\\n        loaded = await store.load(checkpoint.checkpoint_id)\\n\\n        assert loaded is not None\\n        assert loaded.checkpoint_id == checkpoint.checkpoint_id\\n        assert loaded.run_id == checkpoint.run_id\\n        assert loaded.vertex_results.keys() == checkpoint.vertex_results.keys()\\n\\n    async def test_should_survive_a_process_restart(self, store, tmp_path):\\n        checkpoint = await _real_checkpoint()\\n        await store.save(checkpoint)\\n\\n        reopened = SqliteCheckpointStore(tmp_path / \\\"durable.db\\\")\\n\\n        assert await reopened.load(checkpoint.checkpoint_id) is not None\\n\\n    async def test_should_load_latest_checkpoint_by_run_id(self, store):\\n        first = await _real_checkpoint()\\n        second = await _real_checkpoint()\\n        second.run_id = first.run_id\\n\\n        await store.save(first)\\n        await store.save(second)\\n\\n        loaded = await store.load_by_run_id(first.run_id)\\n        assert loaded is not None\\n        assert loaded.checkpoint_id == second.checkpoint_id\\n\\n    async def test_should_return_none_for_unknown_ids(self, store):\\n        assert await store.load(\\\"nope\\\") is None\\n        assert await store.load_by_run_id(\\\"nope\\\") is None\\n\\n    async def test_should_delete_a_checkpoint(self, store):\\n        checkpoint = await _real_checkpoint()\\n        await store.save(checkpoint)\\n\\n        await store.delete(checkpoint.checkpoint_id)\\n\\n        assert await store.load(checkpoint.checkpoint_id) is None\\n\\n    async def test_should_list_checkpoints_by_session(self, store):\\n        checkpoint = await _real_checkpoint()\\n        await store.save(checkpoint)\\n\\n        by_session = await store.list_by_session(\\\"sess-1\\\")\\n\\n        assert [c.checkpoint_id for c in by_session] == [checkpoint.checkpoint_id]\\n        assert await store.list_by_session(\\\"other\\\") == []\\n\\n\\nclass TestExpiry:\\n    async def test_should_not_load_an_expired_checkpoint(self, store):\\n        checkpoint = await _real_checkpoint()\\n        checkpoint.expires_at = datetime.now(timezone.utc) - timedelta(seconds=1)\\n        await store.save(checkpoint)\\n\\n        assert await store.load(checkpoint.checkpoint_id) is None\\n        assert await store.load_by_run_id(checkpoint.run_id) is None\\n\\n\\nclass TestBlobs:\\n    async def test_should_round_trip_a_blob_per_job_and_kind(self, store):\\n        await store.save_blob(\\\"job-9\\\", \\\"agent\\\", '{\\\"tool_state\\\": 1}')\\n\\n        assert await store.load_blob(\\\"job-9\\\", \\\"agent\\\") == '{\\\"tool_state\\\": 1}'\\n        assert await store.load_blob(\\\"job-9\\\", \\\"other\\\") is None\\n\\n    async def test_should_overwrite_a_blob_for_same_key(self, store):\\n        await store.save_blob(\\\"job-9\\\", \\\"agent\\\", \\\"v1\\\")\\n        await store.save_blob(\\\"job-9\\\", \\\"agent\\\", \\\"v2\\\")\\n\\n        assert await store.load_blob(\\\"job-9\\\", \\\"agent\\\") == \\\"v2\\\"\\n\\n    async def test_blob_should_survive_restart(self, store, tmp_path):\\n        await store.save_blob(\\\"job-9\\\", \\\"agent\\\", \\\"persisted\\\")\\n\\n        reopened = SqliteCheckpointStore(tmp_path / \\\"durable.db\\\")\\n\\n        assert await reopened.load_blob(\\\"job-9\\\", \\\"agent\\\") == \\\"persisted\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/durable/test_sqlite_store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd55a2053e28b6b562dfa6819d00358d3412d2cf9ff948bcb4219f40fa2c6d8a\",\"content\":\"\\\"\\\"\\\"SqliteDurableJobStore \u2014 the single-node durable substrate for lfx serve (LE-1695).\\n\\nReal-integration tests: every test runs against a real SQLite file in tmp_path (no\\nmocks), because durability across process boundaries is the point \u2014 a fresh store\\ninstance opened on the same file must see everything a previous instance wrote.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport uuid\\n\\nimport pytest\\nfrom lfx.services.durable.models import JobStatus, JobType, SignalType\\nfrom lfx.services.durable.sqlite_store import SqliteDurableJobStore\\n\\n\\n@pytest.fixture\\ndef db_path(tmp_path):\\n    return tmp_path / \\\"durable jobs \u2014 teste.db\\\"\\n\\n\\n@pytest.fixture\\ndef store(db_path):\\n    return SqliteDurableJobStore(db_path)\\n\\n\\ndef _ids():\\n    return str(uuid.uuid4()), str(uuid.uuid4()), str(uuid.uuid4())\\n\\n\\nclass TestJobLifecycle:\\n    async def test_should_persist_and_return_a_created_job(self, store):\\n        job_id, flow_id, user_id = _ids()\\n\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n        job = await store.get_job(job_id)\\n\\n        assert job is not None\\n        assert job.job_id == job_id\\n        assert job.flow_id == flow_id\\n        assert job.user_id == user_id\\n        assert job.status == JobStatus.QUEUED\\n        assert job.job_type == JobType.WORKFLOW\\n\\n    async def test_should_survive_a_process_restart(self, store, db_path):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        reopened = SqliteDurableJobStore(db_path)\\n        job = await reopened.get_job(job_id)\\n\\n        assert job is not None\\n        assert job.status == JobStatus.QUEUED\\n\\n    async def test_should_return_none_for_unknown_job(self, store):\\n        assert await store.get_job(str(uuid.uuid4())) is None\\n\\n    async def test_should_reject_duplicate_job_id(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        with pytest.raises(ValueError, match=\\\"already exists\\\"):\\n            await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n\\nclass TestJobStateTransitions:\\n    async def test_should_update_status(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        await store.update_status(job_id, JobStatus.SUSPENDED)\\n\\n        assert (await store.get_job(job_id)).status == JobStatus.SUSPENDED\\n\\n    async def test_should_store_result_and_mark_completed(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        await store.set_result(job_id, {\\\"outputs\\\": [1, 2]})\\n        job = await store.get_job(job_id)\\n\\n        assert job.status == JobStatus.COMPLETED\\n        assert job.result == {\\\"outputs\\\": [1, 2]}\\n\\n    async def test_should_store_error_and_mark_failed(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        await store.set_error(job_id, {\\\"type\\\": \\\"boom\\\", \\\"detail\\\": \\\"x\\\"})\\n        job = await store.get_job(job_id)\\n\\n        assert job.status == JobStatus.FAILED\\n        assert job.error == {\\\"type\\\": \\\"boom\\\", \\\"detail\\\": \\\"x\\\"}\\n\\n    async def test_should_merge_metadata_not_replace_it(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        await store.update_metadata(job_id, {\\\"request\\\": {\\\"session_id\\\": \\\"s1\\\"}})\\n        await store.update_metadata(job_id, {\\\"card_message_id\\\": \\\"m1\\\"})\\n        job = await store.get_job(job_id)\\n\\n        assert job.job_metadata == {\\\"request\\\": {\\\"session_id\\\": \\\"s1\\\"}, \\\"card_message_id\\\": \\\"m1\\\"}\\n\\n    async def test_should_round_trip_hostile_metadata_strings(self, store):\\n        # Parameterized queries only: quotes / SQL fragments must survive verbatim.\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n        hostile = {\\\"note\\\": \\\"Robert'); DROP TABLE jobs;--\\\", \\\"emoji\\\": \\\"aprova\u00e7\u00e3o \u2705\\\"}\\n\\n        await store.update_metadata(job_id, hostile)\\n\\n        assert (await store.get_job(job_id)).job_metadata == hostile\\n        assert await store.get_job(job_id) is not None\\n\\n\\nclass TestEventLog:\\n    async def test_should_append_with_monotonic_per_job_seq(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        first = await store.append_event(job_id, \\\"add_message\\\", {\\\"text\\\": \\\"a\\\"})\\n        second = await store.append_event(job_id, \\\"add_message\\\", {\\\"text\\\": \\\"b\\\"})\\n\\n        assert (first, second) == (1, 2)\\n\\n    async def test_should_scope_seq_per_job(self, store):\\n        a, flow_id, user_id = _ids()\\n        b = str(uuid.uuid4())\\n        await store.create_job(job_id=a, flow_id=flow_id, user_id=user_id)\\n        await store.create_job(job_id=b, flow_id=flow_id, user_id=user_id)\\n\\n        await store.append_event(a, \\\"e\\\", {})\\n        seq_b = await store.append_event(b, \\\"e\\\", {})\\n\\n        assert seq_b == 1\\n\\n    async def test_should_read_events_after_seq_in_order(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n        for i in range(5):\\n            await store.append_event(job_id, \\\"e\\\", {\\\"i\\\": i})\\n\\n        events = await store.read_events(job_id, after_seq=2)\\n\\n        assert [e.seq for e in events] == [3, 4, 5]\\n        assert [e.payload[\\\"i\\\"] for e in events] == [2, 3, 4]\\n\\n    async def test_should_keep_seq_gap_free_under_concurrent_appends(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        seqs = await asyncio.gather(*(store.append_event(job_id, \\\"e\\\", {\\\"i\\\": i}) for i in range(25)))\\n\\n        assert sorted(seqs) == list(range(1, 26))\\n\\n\\nclass TestSignals:\\n    async def test_should_deliver_written_signal_once(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        await store.write_signal(job_id, SignalType.RESUME, {\\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}})\\n        pending = await store.unconsumed_signals(job_id)\\n        assert len(pending) == 1\\n        assert pending[0].signal_type == SignalType.RESUME\\n        assert pending[0].data == {\\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}}\\n\\n        consumed = await store.consume_signals(job_id, SignalType.RESUME)\\n\\n        assert consumed == 1\\n        assert await store.unconsumed_signals(job_id) == []\\n\\n\\nclass TestSingleFlightClaims:\\n    async def test_should_grant_suspended_resume_claim_to_exactly_one_caller(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n        await store.update_status(job_id, JobStatus.SUSPENDED)\\n\\n        wins = await asyncio.gather(*(store.claim_suspended_for_resume(job_id) for _ in range(8)))\\n\\n        assert wins.count(True) == 1\\n        assert (await store.get_job(job_id)).status == JobStatus.IN_PROGRESS\\n\\n    async def test_should_reject_resume_claim_when_not_suspended(self, store):\\n        job_id, flow_id, user_id = _ids()\\n        await store.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n        assert await store.claim_suspended_for_resume(job_id) is False\\n\\n    async def test_should_list_queued_workflow_job_ids(self, store):\\n        queued, flow_id, user_id = _ids()\\n        running = str(uuid.uuid4())\\n        await store.create_job(job_id=queued, flow_id=flow_id, user_id=user_id)\\n        await store.create_job(job_id=running, flow_id=flow_id, user_id=user_id)\\n        await store.update_status(running, JobStatus.IN_PROGRESS)\\n\\n        assert await store.queued_workflow_job_ids() == [queued]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/model_provider_policy/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"659bd2b49f9a722125e65859b7086f5e39d4f8532e86fa408357862f5783ab4f\",\"content\":\"\\\"\\\"\\\"Tests for the model-provider policy service contract.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/services/model_provider_policy/test_policy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"03dfea4acd5545c6137824bb4821527b404bda65beeb24436fb5c5b1a089b120\",\"content\":\"from __future__ import annotations\\n\\nimport builtins\\nfrom dataclasses import FrozenInstanceError\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\nfrom lfx.base.models.unified_models import get_embeddings, get_llm\\nfrom lfx.services.model_provider_policy import (\\n    BaseModelProviderPolicyService,\\n    ModelProviderPolicyContext,\\n    ModelProviderPolicyError,\\n    ModelProviderPolicyPurpose,\\n    ModelProviderPolicyService,\\n    ModelProviderPolicySnapshot,\\n    reset_current_model_provider_policy_context,\\n    set_current_model_provider_policy_context,\\n)\\nfrom lfx.services.policy_bundle import PolicyBundleService, PolicyBundleSnapshot, policy_bundle_content_hash\\n\\n_DENIED_RUNTIME_CATALOG_CALLS: list[None] = []\\n\\n\\ndef _denied_runtime_catalog_loader():\\n    _DENIED_RUNTIME_CATALOG_CALLS.append(None)\\n    return [{\\\"name\\\": \\\"blocked-model\\\", \\\"model_type\\\": \\\"llm\\\"}]\\n\\n\\ndef _restricted_snapshot(*allowed: str) -> ModelProviderPolicySnapshot:\\n    return ModelProviderPolicySnapshot(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\", \\\"ollama\\\"}),\\n        allowed_provider_ids=frozenset(allowed),\\n    )\\n\\n\\nclass _CountingPolicy(BaseModelProviderPolicyService):\\n    def __init__(self) -> None:\\n        super().__init__()\\n        self.evaluations = 0\\n        self.set_ready()\\n\\n    def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n        _ = (context, purpose)\\n        self.evaluations += 1\\n        return candidate_provider_ids\\n\\n\\ndef test_default_service_allows_every_candidate():\\n    service = ModelProviderPolicyService()\\n\\n    snapshot = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert snapshot.allowed_provider_ids == frozenset({\\\"openai\\\", \\\"anthropic\\\"})\\n    assert snapshot.allows(\\\"OpenAI\\\")\\n    assert snapshot.allows(\\\"Anthropic\\\")\\n\\n\\ndef test_default_service_does_not_claim_an_external_policy_source():\\n    service = ModelProviderPolicyService()\\n\\n    assert service.external_approved_provider_ids is None\\n\\n\\ndef test_default_service_allows_every_registered_provider():\\n    from lfx.base.models.provider_registry import get_registry_snapshot\\n\\n    service = ModelProviderPolicyService()\\n    provider_ids = get_registry_snapshot().provider_ids\\n\\n    snapshot = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=provider_ids,\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert snapshot.allowed_provider_ids == provider_ids\\n\\n\\ndef test_default_service_applies_install_wide_approved_provider_ceiling():\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"}, version=7)\\n\\n    snapshot = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert snapshot.allowed_provider_ids == frozenset({\\\"openai\\\"})\\n    assert service.approved_provider_ids == frozenset({\\\"openai\\\"})\\n    assert service.policy_version == 7\\n\\n\\ndef test_empty_approved_provider_ceiling_preserves_allow_all_default():\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"})\\n    service.set_approved_provider_ids(set())\\n\\n    snapshot = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        purpose=ModelProviderPolicyPurpose.CONFIGURE,\\n    )\\n\\n    assert snapshot.allowed_provider_ids == frozenset({\\\"openai\\\", \\\"anthropic\\\"})\\n    assert not service.approved_provider_ids\\n\\n\\ndef test_shared_bundle_rejects_provider_only_mutation_without_poisoning_revision_or_hash():\\n    bundle_service = PolicyBundleService()\\n    initial = PolicyBundleSnapshot(\\n        revision=3,\\n        initialized=True,\\n        source=\\\"api\\\",\\n        approved_provider_ids=frozenset({\\\"openai\\\"}),\\n        blocked_component_keys=frozenset({\\\"PythonREPL\\\"}),\\n        blocked_template_keys=frozenset({\\\"Starter\\\"}),\\n        content_hash=policy_bundle_content_hash(\\n            approved_provider_ids={\\\"openai\\\"},\\n            blocked_component_keys={\\\"PythonREPL\\\"},\\n            blocked_template_keys={\\\"Starter\\\"},\\n        ),\\n    )\\n    bundle_service.publish(initial)\\n    service = ModelProviderPolicyService(bundle_service)\\n\\n    with pytest.raises(RuntimeError, match=\\\"Provider-only mutation is not allowed\\\"):\\n        service.set_approved_provider_ids({\\\"anthropic\\\"}, version=4)\\n\\n    assert bundle_service.snapshot is initial\\n\\n\\ndef test_default_service_rejects_a_stale_persisted_policy_version():\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"}, version=5)\\n\\n    changed = service.set_approved_provider_ids({\\\"anthropic\\\"}, version=4)\\n\\n    assert changed is False\\n    assert service.approved_provider_ids == frozenset({\\\"openai\\\"})\\n    assert service.policy_version == 5\\n\\n\\ndef test_default_service_fails_closed_until_policy_source_recovers():\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\", \\\"anthropic\\\"}, version=5)\\n\\n    assert service.fail_closed() is True\\n    denied = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert denied.allowed_provider_ids == frozenset()\\n    assert service.policy_source_available is False\\n\\n    # A same-version refresh is enough to recover because the persisted state\\n    # may not have changed while the store was temporarily unavailable.\\n    assert service.set_approved_provider_ids({\\\"openai\\\", \\\"anthropic\\\"}, version=5) is True\\n    recovered = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n    assert recovered.allowed_provider_ids == frozenset({\\\"openai\\\", \\\"anthropic\\\"})\\n    assert service.policy_source_available is True\\n\\n\\ndef test_default_service_stays_available_when_unrestricted_policy_source_fails():\\n    service = ModelProviderPolicyService()\\n\\n    assert service.fail_closed() is False\\n    snapshot = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert snapshot.allowed_provider_ids == frozenset({\\\"openai\\\", \\\"anthropic\\\"})\\n    assert service.policy_source_available is True\\n\\n\\nasync def test_async_resolver_caches_until_invalidation():\\n    service = ModelProviderPolicyService()\\n    kwargs = {\\n        \\\"context\\\": ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        \\\"candidate_provider_ids\\\": frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        \\\"purpose\\\": ModelProviderPolicyPurpose.USE,\\n    }\\n\\n    first = await service.aresolve(**kwargs)\\n    cached = await service.aresolve(**kwargs)\\n    service.invalidate()\\n    refreshed = await service.aresolve(**kwargs)\\n\\n    assert cached is first\\n    assert refreshed == first\\n    assert refreshed is not first\\n\\n\\ndef test_sync_resolver_caches_until_invalidation():\\n    service = _CountingPolicy()\\n    kwargs = {\\n        \\\"context\\\": ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        \\\"candidate_provider_ids\\\": frozenset({\\\"openai\\\"}),\\n        \\\"purpose\\\": ModelProviderPolicyPurpose.USE,\\n    }\\n\\n    first = service.resolve(**kwargs)\\n    cached = service.resolve(**kwargs)\\n    service.invalidate()\\n    refreshed = service.resolve(**kwargs)\\n\\n    assert cached is first\\n    assert refreshed == first\\n    assert refreshed is not first\\n    assert service.evaluations == 2\\n\\n\\ndef test_snapshot_cache_separates_users():\\n    service = _CountingPolicy()\\n    candidates = frozenset({\\\"openai\\\"})\\n\\n    first_user = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=candidates,\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n    second_user = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-2\\\"),\\n        candidate_provider_ids=candidates,\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n    first_user_cached = service.resolve(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        candidate_provider_ids=candidates,\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert first_user_cached is first_user\\n    assert second_user is not first_user\\n    assert service.evaluations == 2\\n\\n\\ndef test_snapshot_cache_expires_after_ttl(monkeypatch):\\n    from lfx.services.model_provider_policy import base as policy_base\\n\\n    now = [100.0]\\n    monkeypatch.setattr(policy_base, \\\"time\\\", SimpleNamespace(monotonic=lambda: now[0]))\\n    service = _CountingPolicy()\\n    service.SNAPSHOT_CACHE_TTL_SECONDS = 5.0\\n    kwargs = {\\n        \\\"context\\\": ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        \\\"candidate_provider_ids\\\": frozenset({\\\"openai\\\"}),\\n        \\\"purpose\\\": ModelProviderPolicyPurpose.USE,\\n    }\\n\\n    first = service.resolve(**kwargs)\\n    now[0] += 4.0\\n    cached = service.resolve(**kwargs)\\n    now[0] += 1.0\\n    refreshed = service.resolve(**kwargs)\\n\\n    assert cached is first\\n    assert refreshed == first\\n    assert refreshed is not first\\n    assert service.evaluations == 2\\n\\n\\ndef test_snapshot_cache_evicts_least_recently_used_entry():\\n    service = _CountingPolicy()\\n    service.SNAPSHOT_CACHE_MAX_SIZE = 2\\n    candidates = frozenset({\\\"openai\\\"})\\n\\n    def _resolve(scope: str) -> ModelProviderPolicySnapshot:\\n        return service.resolve(\\n            context=ModelProviderPolicyContext(user_id=\\\"user-1\\\", attributes={\\\"scope\\\": scope}),\\n            candidate_provider_ids=candidates,\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n\\n    first = _resolve(\\\"first\\\")\\n    _resolve(\\\"second\\\")\\n    assert _resolve(\\\"first\\\") is first\\n    _resolve(\\\"third\\\")\\n    assert _resolve(\\\"first\\\") is first\\n    _resolve(\\\"second\\\")\\n\\n    assert service.evaluations == 4\\n\\n\\ndef test_zero_sized_snapshot_cache_reevaluates_every_resolution():\\n    service = _CountingPolicy()\\n    service.SNAPSHOT_CACHE_MAX_SIZE = 0\\n    kwargs = {\\n        \\\"context\\\": ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        \\\"candidate_provider_ids\\\": frozenset({\\\"openai\\\"}),\\n        \\\"purpose\\\": ModelProviderPolicyPurpose.USE,\\n    }\\n\\n    first = service.resolve(**kwargs)\\n    second = service.resolve(**kwargs)\\n\\n    assert second == first\\n    assert second is not first\\n    assert service.evaluations == 2\\n\\n\\ndef test_unhashable_policy_attributes_bypass_snapshot_cache():\\n    class UnhashableAttribute:\\n        __hash__ = None\\n\\n    service = _CountingPolicy()\\n    kwargs = {\\n        \\\"context\\\": ModelProviderPolicyContext(attributes={\\\"request\\\": UnhashableAttribute()}),\\n        \\\"candidate_provider_ids\\\": frozenset({\\\"openai\\\"}),\\n        \\\"purpose\\\": ModelProviderPolicyPurpose.USE,\\n    }\\n\\n    first = service.resolve(**kwargs)\\n    second = service.resolve(**kwargs)\\n\\n    assert second == first\\n    assert second is not first\\n    assert service.evaluations == 2\\n\\n\\nasync def test_async_policy_hook_shares_cache_and_honors_invalidation():\\n    class AsyncPolicy(_CountingPolicy):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.async_evaluations = 0\\n\\n        async def aget_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            _ = (context, purpose)\\n            self.async_evaluations += 1\\n            return candidate_provider_ids\\n\\n    service = AsyncPolicy()\\n    kwargs = {\\n        \\\"context\\\": ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        \\\"candidate_provider_ids\\\": frozenset({\\\"openai\\\"}),\\n        \\\"purpose\\\": ModelProviderPolicyPurpose.USE,\\n    }\\n\\n    first = await service.aresolve(**kwargs)\\n    cached = await service.aresolve(**kwargs)\\n    assert service.resolve(**kwargs) is first\\n    service.invalidate()\\n    refreshed = await service.aresolve(**kwargs)\\n\\n    assert cached is first\\n    assert refreshed == first\\n    assert refreshed is not first\\n    assert service.async_evaluations == 2\\n    assert service.evaluations == 0\\n\\n\\ndef test_snapshot_cache_lazily_initializes_for_legacy_subclass():\\n    class LegacyPolicy(BaseModelProviderPolicyService):\\n        def __init__(self) -> None:\\n            self.evaluations = 0\\n            self.set_ready()\\n\\n        def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            _ = (context, purpose)\\n            self.evaluations += 1\\n            return candidate_provider_ids\\n\\n    service = LegacyPolicy()\\n    kwargs = {\\n        \\\"context\\\": ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        \\\"candidate_provider_ids\\\": frozenset({\\\"openai\\\"}),\\n        \\\"purpose\\\": ModelProviderPolicyPurpose.USE,\\n    }\\n\\n    first = service.resolve(**kwargs)\\n    cached = service.resolve(**kwargs)\\n    service.invalidate()\\n    refreshed = service.resolve(**kwargs)\\n\\n    assert cached is first\\n    assert refreshed is not first\\n    assert service.evaluations == 2\\n\\n\\ndef test_snapshot_cache_preserves_policy_attribute_types():\\n    class TypedAttributePolicy(BaseModelProviderPolicyService):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.evaluations = 0\\n            self.set_ready()\\n\\n        def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            _ = purpose\\n            self.evaluations += 1\\n            if context.attributes[\\\"flag\\\"] is True:\\n                return candidate_provider_ids\\n            return frozenset()\\n\\n    service = TypedAttributePolicy()\\n    candidates = frozenset({\\\"openai\\\"})\\n\\n    allowed = service.resolve(\\n        context=ModelProviderPolicyContext(attributes={\\\"flag\\\": True}),\\n        candidate_provider_ids=candidates,\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n    denied = service.resolve(\\n        context=ModelProviderPolicyContext(attributes={\\\"flag\\\": 1}),\\n        candidate_provider_ids=candidates,\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert allowed.allows(\\\"openai\\\")\\n    assert not denied.allows(\\\"openai\\\")\\n    assert service.evaluations == 2\\n\\n\\ndef test_service_distinguishes_use_and_configure_purposes():\\n    class PurposePolicy(BaseModelProviderPolicyService):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.set_ready()\\n\\n        def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            _ = context\\n            if purpose is ModelProviderPolicyPurpose.USE:\\n                return candidate_provider_ids\\n            return frozenset()\\n\\n    service = PurposePolicy()\\n\\n    assert service.is_allowed(\\\"openai\\\", ModelProviderPolicyPurpose.USE)\\n    assert not service.is_allowed(\\\"openai\\\", ModelProviderPolicyPurpose.CONFIGURE)\\n\\n\\ndef test_is_allowed_canonicalizes_alias_and_uses_ambient_context():\\n    class CapturingPolicy(BaseModelProviderPolicyService):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.calls = []\\n\\n        def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            self.calls.append((context, candidate_provider_ids, purpose))\\n            return candidate_provider_ids\\n\\n    service = CapturingPolicy()\\n    token = set_current_model_provider_policy_context(\\n        user_id=\\\"user-1\\\",\\n        attributes={\\\"workspace_id\\\": \\\"workspace-1\\\"},\\n    )\\n    try:\\n        allowed = service.is_allowed(\\\"IBM watsonx.ai\\\", ModelProviderPolicyPurpose.USE)\\n    finally:\\n        reset_current_model_provider_policy_context(token)\\n\\n    assert allowed is True\\n    context, candidates, purpose = service.calls[0]\\n    assert context.user_id == \\\"user-1\\\"\\n    assert context.attributes[\\\"workspace_id\\\"] == \\\"workspace-1\\\"\\n    assert candidates == frozenset({\\\"ibm-watsonx\\\"})\\n    assert purpose is ModelProviderPolicyPurpose.USE\\n\\n\\ndef test_default_resolution_preserves_unknown_legacy_provider_names(monkeypatch):\\n    from lfx.services.model_provider_policy import utils\\n\\n    service = ModelProviderPolicyService()\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_model_provider_policy_service\\\", lambda: service)\\n\\n    snapshot = utils.resolve_model_provider_policy(\\n        user_id=\\\"user-1\\\",\\n        providers=[\\\"Legacy Custom Provider\\\"],\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert snapshot.allows(\\\"Legacy Custom Provider\\\")\\n\\n\\ndef test_default_resolution_preserves_non_sluggable_legacy_provider(monkeypatch):\\n    from lfx.services.model_provider_policy import utils\\n\\n    service = ModelProviderPolicyService()\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_model_provider_policy_service\\\", lambda: service)\\n\\n    snapshot = utils.resolve_model_provider_policy(\\n        user_id=\\\"user-1\\\",\\n        providers=[\\\"\ud83d\udd25\\\"],\\n        purpose=ModelProviderPolicyPurpose.USE,\\n    )\\n\\n    assert len(snapshot.candidate_provider_ids) == 1\\n    assert next(iter(snapshot.candidate_provider_ids)).startswith(\\\"legacy-\\\")\\n    assert snapshot.allows(\\\"\ud83d\udd25\\\")\\n\\n\\ndef test_request_principal_attributes_follow_only_the_matching_user(monkeypatch):\\n    from lfx.services.model_provider_policy import utils\\n\\n    service = ModelProviderPolicyService()\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_model_provider_policy_service\\\", lambda: service)\\n    token = set_current_model_provider_policy_context(\\n        user_id=\\\"user-1\\\",\\n        attributes={\\\"is_superuser\\\": True},\\n    )\\n    try:\\n        matching = utils.resolve_model_provider_policy(\\n            user_id=\\\"user-1\\\",\\n            providers=[\\\"OpenAI\\\"],\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n        different = utils.resolve_model_provider_policy(\\n            user_id=\\\"user-2\\\",\\n            providers=[\\\"OpenAI\\\"],\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n    finally:\\n        reset_current_model_provider_policy_context(token)\\n\\n    assert matching.context.attributes[\\\"is_superuser\\\"] is True\\n    assert dict(different.context.attributes) == {}\\n\\n\\ndef test_watsonx_legacy_alias_resolves_to_stable_provider_id():\\n    from lfx.base.models.provider_registry import provider_id_for\\n\\n    assert provider_id_for(\\\"IBM watsonx.ai\\\") == \\\"ibm-watsonx\\\"\\n    assert _restricted_snapshot(\\\"openai\\\").allows(\\\"IBM watsonx.ai\\\") is False\\n\\n\\ndef test_snapshot_is_immutable_and_cannot_allow_non_candidates():\\n    snapshot = _restricted_snapshot(\\\"openai\\\")\\n\\n    with pytest.raises(FrozenInstanceError):\\n        snapshot.purpose = ModelProviderPolicyPurpose.CONFIGURE  # type: ignore[misc]\\n\\n    with pytest.raises(ValueError, match=\\\"subset\\\"):\\n        ModelProviderPolicySnapshot(\\n            context=ModelProviderPolicyContext(),\\n            purpose=ModelProviderPolicyPurpose.DISCOVER,\\n            candidate_provider_ids=frozenset({\\\"openai\\\"}),\\n            allowed_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        )\\n\\n\\ndef test_policy_error_for_non_sluggable_selector_is_generic_and_opaque():\\n    from lfx.base.models.provider_registry import resolve_provider_id\\n\\n    selector = \\\"\ud83d\udd25\\\"\\n    opaque_provider_id = resolve_provider_id(selector)\\n    snapshot = ModelProviderPolicySnapshot(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n        candidate_provider_ids=frozenset({opaque_provider_id}),\\n        allowed_provider_ids=frozenset(),\\n    )\\n\\n    with pytest.raises(ModelProviderPolicyError) as exc_info:\\n        snapshot.require(selector)\\n\\n    assert str(exc_info.value) == \\\"The requested model provider is not available\\\"\\n    assert exc_info.value.provider_id == opaque_provider_id\\n    assert exc_info.value.provider_id.startswith(\\\"legacy-\\\")\\n    assert selector not in exc_info.value.provider_id\\n\\n\\ndef test_context_attributes_are_deeply_immutable():\\n    attributes = {\\\"roles\\\": [\\\"member\\\"], \\\"scope\\\": {\\\"workspace\\\": \\\"one\\\"}}\\n    context = ModelProviderPolicyContext(attributes=attributes)\\n    attributes[\\\"roles\\\"].append(\\\"admin\\\")\\n\\n    assert context.attributes[\\\"roles\\\"] == (\\\"member\\\",)\\n    with pytest.raises(TypeError):\\n        context.attributes[\\\"scope\\\"][\\\"workspace\\\"] = \\\"two\\\"\\n\\n\\ndef test_runtime_denies_provider_before_credential_resolution(monkeypatch):\\n    credential_lookup_called = False\\n    class_lookup_called = False\\n    runtime_imports = []\\n    real_import = builtins.__import__\\n\\n    def _credential_lookup(*_args, **_kwargs):\\n        nonlocal credential_lookup_called\\n        credential_lookup_called = True\\n        return \\\"secret\\\"\\n\\n    def _track_import(name, *args, **kwargs):\\n        runtime_imports.append(name)\\n        return real_import(name, *args, **kwargs)\\n\\n    def _class_lookup(*_args, **_kwargs):\\n        nonlocal class_lookup_called\\n        class_lookup_called = True\\n        return object\\n\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", _credential_lookup)\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_model_class\\\", _class_lookup)\\n    monkeypatch.setattr(builtins, \\\"__import__\\\", _track_import)\\n\\n    with pytest.raises(ModelProviderPolicyError) as exc_info:\\n        get_llm(\\n            [{\\\"name\\\": \\\"claude-test\\\", \\\"provider\\\": \\\"Anthropic\\\", \\\"metadata\\\": {}}],\\n            user_id=\\\"user-1\\\",\\n            provider_policy=_restricted_snapshot(\\\"openai\\\"),\\n        )\\n\\n    assert exc_info.value.code == \\\"policy_blocked\\\"\\n    assert credential_lookup_called is False\\n    assert class_lookup_called is False\\n    assert \\\"langchain_core.language_models\\\" not in runtime_imports\\n    assert not any(name.startswith(\\\"langchain_anthropic\\\") for name in runtime_imports)\\n\\n\\ndef test_embedding_runtime_denies_provider_before_credential_resolution(monkeypatch):\\n    credential_lookup_called = False\\n    class_lookup_called = False\\n    runtime_imports = []\\n    real_import = builtins.__import__\\n\\n    def _credential_lookup(*_args, **_kwargs):\\n        nonlocal credential_lookup_called\\n        credential_lookup_called = True\\n        return \\\"secret\\\"\\n\\n    def _track_import(name, *args, **kwargs):\\n        runtime_imports.append(name)\\n        return real_import(name, *args, **kwargs)\\n\\n    def _class_lookup(*_args, **_kwargs):\\n        nonlocal class_lookup_called\\n        class_lookup_called = True\\n        return object\\n\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", _credential_lookup)\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_embedding_class\\\", _class_lookup)\\n    monkeypatch.setattr(builtins, \\\"__import__\\\", _track_import)\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        get_embeddings(\\n            [{\\\"name\\\": \\\"embed-test\\\", \\\"provider\\\": \\\"Anthropic\\\", \\\"metadata\\\": {}}],\\n            user_id=\\\"user-1\\\",\\n            provider_policy=_restricted_snapshot(\\\"openai\\\"),\\n        )\\n\\n    assert credential_lookup_called is False\\n    assert class_lookup_called is False\\n    assert \\\"langchain_core.embeddings\\\" not in runtime_imports\\n    assert not any(name.startswith(\\\"langchain_anthropic\\\") for name in runtime_imports)\\n\\n\\n@pytest.mark.parametrize(\\\"instantiate\\\", [get_llm, get_embeddings])\\ndef test_denied_extension_runtime_does_not_execute_catalog_loader(monkeypatch, instantiate):\\n    from lfx.base.models.provider_registry import ProviderSpec, register_provider, unregister_provider\\n\\n    provider = \\\"Denied Runtime Extension\\\"\\n    register_provider(\\n        ProviderSpec(\\n            name=provider,\\n            provider_id=\\\"denied-runtime-extension\\\",\\n            metadata={\\n                \\\"icon\\\": \\\"Bot\\\",\\n                \\\"variables\\\": [],\\n                \\\"mapping\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\", \\\"model_param\\\": \\\"model\\\"},\\n            },\\n            catalog_loader=f\\\"{__name__}:_denied_runtime_catalog_loader\\\",\\n        )\\n    )\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"})\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_model_provider_policy_service\\\", lambda: service)\\n    _DENIED_RUNTIME_CATALOG_CALLS.clear()\\n\\n    try:\\n        with pytest.raises(ModelProviderPolicyError):\\n            instantiate(\\n                [{\\\"name\\\": \\\"blocked-model\\\", \\\"provider\\\": provider, \\\"metadata\\\": {}}],\\n                user_id=\\\"user-1\\\",\\n            )\\n    finally:\\n        unregister_provider(provider)\\n\\n    assert _DENIED_RUNTIME_CATALOG_CALLS == []\\n\\n\\n@pytest.mark.parametrize(\\\"runtime\\\", [get_llm, get_embeddings], ids=[\\\"llm\\\", \\\"embeddings\\\"])\\ndef test_legacy_non_sluggable_runtime_denied_before_credential_resolution(monkeypatch, runtime):\\n    from lfx.base.models.provider_registry import resolve_provider_id\\n\\n    selector = \\\"\ud83d\udd25\\\"\\n    credential_lookup_called = False\\n\\n    def _credential_lookup(*_args, **_kwargs):\\n        nonlocal credential_lookup_called\\n        credential_lookup_called = True\\n        return \\\"secret\\\"\\n\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", _credential_lookup)\\n    provider_id = resolve_provider_id(selector)\\n    policy = ModelProviderPolicySnapshot(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n        candidate_provider_ids=frozenset({provider_id}),\\n        allowed_provider_ids=frozenset(),\\n    )\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        runtime(\\n            [{\\\"name\\\": \\\"legacy-test\\\", \\\"provider\\\": selector, \\\"metadata\\\": {}}],\\n            user_id=\\\"user-1\\\",\\n            provider_policy=policy,\\n        )\\n\\n    assert credential_lookup_called is False\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"runtime\\\", \\\"message\\\"),\\n    [\\n        (get_llm, \\\"selected model is missing a provider\\\"),\\n        (get_embeddings, \\\"selected embedding model is missing a provider\\\"),\\n    ],\\n    ids=[\\\"llm\\\", \\\"embeddings\\\"],\\n)\\ndef test_whitespace_only_provider_uses_friendly_missing_provider_error(runtime, message):\\n    with pytest.raises(ValueError, match=message):\\n        runtime(\\n            [{\\\"name\\\": \\\"legacy-test\\\", \\\"provider\\\": \\\" \\\\t \\\", \\\"metadata\\\": {}}],\\n            user_id=\\\"user-1\\\",\\n        )\\n\\n\\nasync def test_standalone_model_component_denied_before_build_method(monkeypatch):\\n    \\\"\\\"\\\"Saved legacy model nodes cannot bypass policy by skipping the unified-model helpers.\\\"\\\"\\\"\\n    from lfx.base.models.model import LCModelComponent\\n    from lfx.io import Output\\n\\n    build_called = False\\n\\n    class StandaloneOpenAIComponent(LCModelComponent):\\n        display_name = \\\"OpenAI\\\"\\n        outputs = [Output(name=\\\"model\\\", display_name=\\\"Model\\\", method=\\\"build_model\\\")]\\n\\n        def build_model(self):\\n            nonlocal build_called\\n            build_called = True\\n            return \\\"should-not-run\\\"\\n\\n    def _deny(*, user_id, providers, purpose, attributes=None):\\n        candidate_ids = frozenset(providers)\\n        return ModelProviderPolicySnapshot(\\n            context=ModelProviderPolicyContext(user_id=user_id, attributes=attributes or {}),\\n            purpose=purpose,\\n            candidate_provider_ids=candidate_ids,\\n            allowed_provider_ids=frozenset(),\\n        )\\n\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.utils.resolve_model_provider_policy\\\", _deny)\\n    component = StandaloneOpenAIComponent(_user_id=\\\"user-1\\\")\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        await component.build_results()\\n\\n    assert build_called is False\\n\\n\\ndef test_standalone_model_component_denied_before_dynamic_configuration(monkeypatch):\\n    from lfx.base.models.model import LCModelComponent\\n\\n    class StandaloneAnthropicComponent(LCModelComponent):\\n        display_name = \\\"Anthropic\\\"\\n\\n    purposes = []\\n\\n    def _deny(*, user_id, providers, purpose, attributes=None):\\n        purposes.append(purpose)\\n        return ModelProviderPolicySnapshot(\\n            context=ModelProviderPolicyContext(user_id=user_id, attributes=attributes or {}),\\n            purpose=purpose,\\n            candidate_provider_ids=frozenset(providers),\\n            allowed_provider_ids=frozenset(),\\n        )\\n\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.utils.resolve_model_provider_policy\\\", _deny)\\n    component = StandaloneAnthropicComponent(_user_id=\\\"user-1\\\")\\n\\n    with pytest.raises(ModelProviderPolicyError):\\n        component.require_model_provider_policy(ModelProviderPolicyPurpose.CONFIGURE)\\n\\n    assert purposes == [ModelProviderPolicyPurpose.CONFIGURE]\\n\\n\\ndef test_delegating_model_component_skips_outer_provider_gate(monkeypatch):\\n    from lfx.base.models.model import LCModelComponent\\n\\n    class UnifiedSelectorComponent(LCModelComponent):\\n        display_name = \\\"Language Model\\\"\\n        model_provider_policy_mode = \\\"delegate\\\"\\n\\n    resolver = AsyncMock()\\n    monkeypatch.setattr(\\\"lfx.services.model_provider_policy.utils.resolve_model_provider_policy\\\", resolver)\\n\\n    UnifiedSelectorComponent(_user_id=\\\"user-1\\\").require_model_provider_policy(ModelProviderPolicyPurpose.CONFIGURE)\\n\\n    resolver.assert_not_called()\\n\\n\\ndef test_known_llm_provider_ignores_spoofed_runtime_metadata(monkeypatch):\\n    from lfx.base.models.unified_models import instantiation\\n\\n    requested_classes = []\\n    captured = {}\\n\\n    class _OllamaChatModel:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    def _get_model_class(class_name):\\n        requested_classes.append(class_name)\\n        return _OllamaChatModel\\n\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_model_class\\\", _get_model_class)\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", lambda *_args, **_kwargs: None)\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\", lambda *_args: {})\\n    # ollama.test (RFC 6761 reserved TLD) never resolves, so the DNS-pinning\\n    # SSRF transport for ChatOllama fails in every environment. The URL value\\n    # is irrelevant to this test's subject (spoofed metadata being ignored),\\n    # so stub the transport factory (same seam test_provider_registry stubs).\\n    monkeypatch.setattr(instantiation, \\\"ssrf_protected_httpx_client_kwargs_for_url\\\", lambda _url: ({}, {}))\\n\\n    result = get_llm(\\n        [\\n            {\\n                \\\"name\\\": \\\"llama-test\\\",\\n                \\\"provider\\\": \\\"Ollama\\\",\\n                \\\"metadata\\\": {\\n                    \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n                    \\\"model_name_param\\\": \\\"anthropic_model\\\",\\n                    \\\"api_key_param\\\": \\\"anthropic_api_key\\\",  # pragma: allowlist secret\\n                    \\\"base_url_param\\\": \\\"anthropic_base_url\\\",\\n                },\\n            }\\n        ],\\n        user_id=\\\"user-1\\\",\\n        ollama_base_url=\\\"http://ollama.test\\\",\\n        provider_policy=_restricted_snapshot(\\\"ollama\\\"),\\n    )\\n\\n    assert isinstance(result, _OllamaChatModel)\\n    assert requested_classes == [\\\"ChatOllama\\\"]\\n    assert captured == {\\n        \\\"model\\\": \\\"llama-test\\\",\\n        \\\"streaming\\\": False,\\n        \\\"api_key\\\": None,\\n        \\\"base_url\\\": \\\"http://ollama.test\\\",\\n    }\\n\\n\\ndef test_known_embedding_provider_ignores_spoofed_runtime_metadata(monkeypatch):\\n    from lfx.base.models.unified_models import instantiation\\n\\n    requested_classes = []\\n    captured = {}\\n\\n    class _OllamaEmbeddings:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    def _get_embedding_class(class_name):\\n        requested_classes.append(class_name)\\n        return _OllamaEmbeddings\\n\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_embedding_class\\\", _get_embedding_class)\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\", lambda *_args, **_kwargs: None)\\n    monkeypatch.setattr(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\", lambda *_args: {})\\n    monkeypatch.setattr(instantiation, \\\"_get_configured_embedding_providers\\\", lambda *_args: [])\\n    # See the LLM variant above: ollama.test never resolves, and DNS is not\\n    # what this test is about.\\n    monkeypatch.setattr(instantiation, \\\"ssrf_protected_httpx_client_kwargs_for_url\\\", lambda _url: ({}, {}))\\n\\n    result = get_embeddings(\\n        [\\n            {\\n                \\\"name\\\": \\\"nomic-embed-text\\\",\\n                \\\"provider\\\": \\\"Ollama\\\",\\n                \\\"metadata\\\": {\\n                    \\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\",\\n                    \\\"param_mapping\\\": {\\n                        \\\"model\\\": \\\"deployment\\\",\\n                        \\\"api_key\\\": \\\"openai_api_key\\\",  # pragma: allowlist secret\\n                        \\\"base_url\\\": \\\"openai_api_base\\\",\\n                    },\\n                },\\n            }\\n        ],\\n        user_id=\\\"user-1\\\",\\n        ollama_base_url=\\\"http://ollama.test\\\",\\n        provider_policy=_restricted_snapshot(\\\"ollama\\\"),\\n    )\\n\\n    assert isinstance(result.embeddings, _OllamaEmbeddings)\\n    assert requested_classes == [\\\"OllamaEmbeddings\\\"]\\n    assert captured == {\\\"model\\\": \\\"nomic-embed-text\\\", \\\"base_url\\\": \\\"http://ollama.test\\\"}\\n\\n\\ndef test_default_runtime_policy_preserves_unknown_legacy_llm_provider(monkeypatch):\\n    \\\"\\\"\\\"Unknown saved providers must reach the historical runtime validation path.\\\"\\\"\\\"\\n    from lfx.services import deps\\n\\n    captured = {}\\n\\n    class _LegacyChatModel:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    monkeypatch.setattr(deps, \\\"get_model_provider_policy_service\\\", lambda: ModelProviderPolicyService())\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.get_api_key_for_provider\\\",\\n        lambda *_args, **_kwargs: \\\"legacy-key\\\",  # pragma: allowlist secret\\n    )\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.get_model_class\\\",\\n        lambda _class_name: _LegacyChatModel,\\n    )\\n\\n    result = get_llm(\\n        [\\n            {\\n                \\\"name\\\": \\\"legacy-model\\\",\\n                \\\"provider\\\": \\\"Legacy Custom Provider\\\",\\n                \\\"metadata\\\": {\\n                    \\\"model_class\\\": \\\"LegacyChatModel\\\",\\n                    \\\"model_name_param\\\": \\\"model\\\",\\n                    \\\"api_key_param\\\": \\\"api_key\\\",  # pragma: allowlist secret\\n                },\\n            }\\n        ],\\n        user_id=\\\"user-1\\\",\\n    )\\n\\n    assert isinstance(result, _LegacyChatModel)\\n    assert captured == {  # pragma: allowlist secret\\n        \\\"model\\\": \\\"legacy-model\\\",\\n        \\\"streaming\\\": False,\\n        \\\"api_key\\\": \\\"legacy-key\\\",  # pragma: allowlist secret\\n    }\\n\\n\\ndef test_default_runtime_policy_preserves_unknown_legacy_embedding_provider(monkeypatch):\\n    \\\"\\\"\\\"The allow-all default must not turn an old embedding selection into a policy denial.\\\"\\\"\\\"\\n    from lfx.base.models.unified_models import instantiation\\n    from lfx.services import deps\\n\\n    captured = {}\\n\\n    class _LegacyEmbeddings:\\n        def __init__(self, **kwargs):\\n            captured.update(kwargs)\\n\\n    monkeypatch.setattr(deps, \\\"get_model_provider_policy_service\\\", lambda: ModelProviderPolicyService())\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.get_api_key_for_provider\\\",\\n        lambda *_args, **_kwargs: \\\"legacy-key\\\",\\n    )\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.get_embedding_class\\\",\\n        lambda _class_name: _LegacyEmbeddings,\\n    )\\n    monkeypatch.setattr(instantiation, \\\"_get_provider_embedding_model_names\\\", lambda *_args: [])\\n\\n    result = get_embeddings(\\n        [\\n            {\\n                \\\"name\\\": \\\"legacy-embedding-model\\\",\\n                \\\"provider\\\": \\\"Legacy Custom Provider\\\",\\n                \\\"metadata\\\": {\\n                    \\\"embedding_class\\\": \\\"LegacyEmbeddings\\\",\\n                    \\\"param_mapping\\\": {\\n                        \\\"model\\\": \\\"model\\\",\\n                        \\\"api_key\\\": \\\"api_key\\\",  # pragma: allowlist secret\\n                    },\\n                },\\n            }\\n        ],\\n        user_id=None,\\n    )\\n\\n    assert isinstance(result.embeddings, _LegacyEmbeddings)\\n    assert captured == {\\n        \\\"model\\\": \\\"legacy-embedding-model\\\",\\n        \\\"api_key\\\": \\\"legacy-key\\\",  # pragma: allowlist secret\\n    }\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"option_builder\\\", \\\"model_type\\\", \\\"openai_model\\\"),\\n    [\\n        (\\\"get_language_model_options\\\", \\\"llm\\\", \\\"gpt-test\\\"),\\n        (\\\"get_embedding_model_options\\\", \\\"embeddings\\\", \\\"text-embedding-test\\\"),\\n    ],\\n)\\ndef test_model_options_filter_denied_dynamic_sources(option_builder, model_type, openai_model):\\n    from lfx.base.models.unified_models import model_catalog\\n\\n    catalog = [\\n        {\\n           ";
